24	// MaxJobNumPerRun is the maximum number of jobs in a single run.
25	// https://docs.github.com/en/actions/reference/limits#existing-system-limits
26	// TODO: check this limit when creating jobs
27	const MaxJobNumPerRun = 256
28	
29	// ActionRunJob represents a job of a run
30	type ActionRunJob struct {
31		ID                int64
32		RunID             int64                  `xorm:"index"`
33		Run               *ActionRun             `xorm:"-"`
34		RepoID            int64                  `xorm:"index(repo_concurrency)"`
35		Repo              *repo_model.Repository `xorm:"-"`
36		OwnerID           int64                  `xorm:"index"`
37		CommitSHA         string                 `xorm:"index"`
38		IsForkPullRequest bool
39		Name              string `xorm:"VARCHAR(255)"`
40	
41		// for legacy jobs, this counts how many times the job has run;
42		// otherwise it matches the Attempt of the ActionRunAttempt identified by job.RunAttemptID
43		Attempt int64
44	
45		// WorkflowPayload is act/jobparser.SingleWorkflow for act/jobparser.Parse
46		// it should contain exactly one job with global workflow fields for this model
47		WorkflowPayload []byte
48	
49		JobID  string   `xorm:"VARCHAR(255)"` // job id in workflow, not job's id
50		Needs  []string `xorm:"JSON TEXT"`
51		RunsOn []string `xorm:"JSON TEXT"`
52	
53		TaskID       int64 // the task created by this job in its own attempt
54		SourceTaskID int64 `xorm:"NOT NULL DEFAULT 0"` // SourceTaskID points to a historical task when this job reuses an earlier attempt's result.
55	
56		Status Status `xorm:"index"`
57	
58		RawConcurrency string // raw concurrency from job YAML's "concurrency" section
59	
60		// IsConcurrencyEvaluated is only valid/needed when this job's RawConcurrency is not empty.
61		// If RawConcurrency can't be evaluated (e.g. depend on other job's outputs or have errors), this field will be false.
62		// If RawConcurrency has been successfully evaluated, this field will be true, ConcurrencyGroup and ConcurrencyCancel are also set.
63		IsConcurrencyEvaluated bool
64	
65		ConcurrencyGroup  string `xorm:"index(repo_concurrency) NOT NULL DEFAULT ''"` // evaluated concurrency.group
66		ConcurrencyCancel bool   `xorm:"NOT NULL DEFAULT FALSE"`                      // evaluated concurrency.cancel-in-progress
67	
68		// TokenPermissions stores the explicit permissions from workflow/job YAML (no org/repo clamps applied).
69		// Org/repo clamps are enforced when the token is used at runtime.
70		// It is JSON-encoded repo_model.ActionsTokenPermissions and may be empty if not specified.
71		TokenPermissions *repo_model.ActionsTokenPermissions `xorm:"JSON TEXT"`
72	
73		// RunAttemptID identifies the ActionRunAttempt this job belongs to.
74		// A value of 0 indicates a legacy job created before ActionRunAttempt existed.
75		RunAttemptID int64 `xorm:"index NOT NULL DEFAULT 0"`
76		// AttemptJobID is unique within a single attempt.
77		// For jobs created after ActionRunAttempt was introduced, the same logical job is expected to keep the same AttemptJobID across attempts.
78		// A value of 0 indicates a legacy job created before ActionRunAttempt existed.
79		AttemptJobID int64 `xorm:"index NOT NULL DEFAULT 0"`
80	
81		// WorkflowSourceRepoID + WorkflowSourceCommitSHA record the (repo, commit) this job's containing workflow file came from.
82		WorkflowSourceRepoID    int64  `xorm:"NOT NULL DEFAULT 0"`
83		WorkflowSourceCommitSHA string `xorm:"VARCHAR(64) NOT NULL DEFAULT ''"`
84	
85		// IsReusableCaller marks this job as a reusable workflow caller.
86		// Caller jobs do not run on a runner; their status is derived from their child jobs.
87		IsReusableCaller bool `xorm:"index NOT NULL DEFAULT FALSE"`
88		// IsExpanded reports whether this job's lazy expansion (children-row insertion) is complete.
89		// For a reusable workflow caller, true means children rows exist and CallPayload is populated.
90		IsExpanded bool `xorm:"NOT NULL DEFAULT FALSE"`
91		// CallUses stores the raw "uses:" string of a reusable workflow caller job.
92		// Only set when IsReusableCaller is true.
93		CallUses string `xorm:"VARCHAR(512) NOT NULL DEFAULT ''"`
94		// ReusableWorkflowContent is the content of the reusable workflow specified by "uses:".
95		// Only set when IsReusableCaller is true.
96		ReusableWorkflowContent []byte `xorm:"LONGBLOB"`
97		// CallSecrets encodes the reusable workflow caller's "secrets:" section:
98		//   - ""           : no "secrets:" section (children only see auto-generated tokens).
99		//   - "inherit"    : the caller wrote "secrets: inherit".
100		//   - JSON object  : explicit mapping {alias: source_name}; names only, no values.
101		// Only set when IsReusableCaller is true.
102		CallSecrets string `xorm:"LONGTEXT"`
103		// CallPayload is the JSON-encoded WorkflowCallPayload exposed to children as gitea.event.
104		// Populated atomically with IsExpanded at the end of expandReusableWorkflowCaller.
105		// Only set when IsReusableCaller is true.
106		CallPayload string `xorm:"LONGTEXT"`
107	
108		// ParentJobID scopes `Needs` resolution: name lookups happen only among rows sharing the same ParentJobID. 0 for top-level rows.
109		ParentJobID int64 `xorm:"index NOT NULL DEFAULT 0"`
110	
111		// ContinueOnError mirrors the job-level continue-on-error field from the workflow YAML.
112		// When true, a failure of this job does not fail the overall workflow run.
113		ContinueOnError bool `xorm:"NOT NULL DEFAULT FALSE"`
114	
115		Started timeutil.TimeStamp
116		Stopped timeutil.TimeStamp
117		Created timeutil.TimeStamp `xorm:"created"`
118		Updated timeutil.TimeStamp `xorm:"updated index"`
119	}
