196	func GetRunJobByRepoAndID(ctx context.Context, repoID, jobID int64) (*ActionRunJob, error) {
197		var job ActionRunJob
198		has, err := db.GetEngine(ctx).Where("id=? AND repo_id=?", jobID, repoID).Get(&job)
199		if err != nil {
200			return nil, err
201		} else if !has {
202			return nil, fmt.Errorf("run job with id %d: %w", jobID, util.ErrNotExist)
203		}
204	
205		return &job, nil
206	}
