232	// GetLatestAttemptJobsByRepoAndRunID returns the jobs of the latest attempt for a run.
233	// It prefers the latest attempt when one exists, and falls back to legacy jobs with run_attempt_id=0 for runs created before ActionRunAttempt existed.
234	func GetLatestAttemptJobsByRepoAndRunID(ctx context.Context, repoID, runID int64) (ActionJobList, error) {
235		run, err := GetRunByRepoAndID(ctx, repoID, runID)
236		if err != nil {
237			return nil, err
238		}
239		if run.LatestAttemptID > 0 {
240			return GetRunJobsByRunAndAttemptID(ctx, runID, run.LatestAttemptID)
241		}
242	
243		var jobs []*ActionRunJob
244		if err := db.GetEngine(ctx).Where("repo_id=? AND run_id=? AND run_attempt_id=0", repoID, runID).OrderBy("id").Find(&jobs); err != nil {
245			return nil, err
246		}
247		return jobs, nil
248	}
