269	// GetPriorAttemptChildrenByParent returns the children of the most recent prior attempt where
270	// the parent (identified by parentAttemptJobID) actually had children, indexed by child JobID then child Name.
271	// Returns (nil, nil) when no such attempt exists.
272	// The (JobID, Name) key disambiguates both reusable-workflow subtrees and matrix-expanded instances (whose Name carries the matrix suffix).
273	func GetPriorAttemptChildrenByParent(ctx context.Context, runID, currentAttemptID, parentAttemptJobID int64) (map[string]map[string]*ActionRunJob, error) {
274		// query every prior caller row sharing this AttemptJobID, newest first.
275		var priorCallers []*ActionRunJob
276		if err := db.GetEngine(ctx).
277			Where("run_id = ? AND attempt_job_id = ? AND run_attempt_id < ?", runID, parentAttemptJobID, currentAttemptID).
278			Desc("run_attempt_id").
279			Find(&priorCallers); err != nil {
280			return nil, fmt.Errorf("find prior callers: %w", err)
281		}
282		if len(priorCallers) == 0 {
283			return nil, nil //nolint:nilnil // caller is brand new in this attempt
284		}
285	
286		// query for every child of every prior caller
287		callerIDs := make([]int64, len(priorCallers))
288		for i, c := range priorCallers {
289			callerIDs[i] = c.ID
290		}
291		var allChildren []*ActionRunJob
292		if err := db.GetEngine(ctx).
293			Where("run_id = ?", runID).
294			In("parent_job_id", callerIDs).
295			Find(&allChildren); err != nil {
296			return nil, fmt.Errorf("find prior children: %w", err)
297		}
298	
299		childrenByCallerID := make(map[int64][]*ActionRunJob, len(callerIDs))
300		for _, c := range allChildren {
301			childrenByCallerID[c.ParentJobID] = append(childrenByCallerID[c.ParentJobID], c)
302		}
303	
304		// Walk priorCallers in run_attempt_id-desc order and return the children of the first caller that actually had any.
305		// Skipped attempts (caller exists but no children) are bypassed.
306		for _, caller := range priorCallers {
307			children := childrenByCallerID[caller.ID]
308			if len(children) == 0 {
309				continue
310			}
311			out := make(map[string]map[string]*ActionRunJob)
312			for _, c := range children {
313				if out[c.JobID] == nil {
314					out[c.JobID] = make(map[string]*ActionRunJob)
315				}
316				out[c.JobID][c.Name] = c
317			}
318			return out, nil
319		}
320	
321		return nil, nil //nolint:nilnil // every prior attempt skipped this caller
322	}
323	
324	// GetDirectChildJobsByParent returns the direct child jobs of a parent job (e.g. a reusable workflow caller).
325	func GetDirectChildJobsByParent(ctx context.Context, parentJob *ActionRunJob) (ActionJobList, error) {
326		var jobs []*ActionRunJob
327		if err := db.GetEngine(ctx).
328			Where("run_id=? AND parent_job_id=?", parentJob.RunID, parentJob.ID).
329			OrderBy("id").
330			Find(&jobs); err != nil {
331			return nil, err
332		}
333		return jobs, nil
334	}
335	
336	// CollectAllDescendantJobs returns every job in `allJobs` that lives under parent's subtree (recursively), excluding `parent` itself
337	func CollectAllDescendantJobs(parent *ActionRunJob, allJobs []*ActionRunJob) []*ActionRunJob {
338		parents := map[int64]bool{parent.ID: true}
339		for {
340			grew := false
341			for _, j := range allJobs {
342				if j.ParentJobID == 0 {
343					continue
344				}
345				if parents[j.ParentJobID] && !parents[j.ID] {
346					parents[j.ID] = true
347					grew = true
348				}
349			}
350			if !grew {
351				break
352			}
353		}
354		out := make([]*ActionRunJob, 0)
355		for _, j := range allJobs {
356			if j.ID == parent.ID || !parents[j.ID] {
357				continue
358			}
359			out = append(out, j)
360		}
361		return out
362	}
363	
364	// hasWaitingJobsToPick reports whether any waiting, unclaimed, non-reusable job
365	// remains in the repo, i.e. work that an idle runner could still pick up.
366	func hasWaitingJobsToPick(ctx context.Context, repoID int64) (bool, error) {
367		return db.GetEngine(ctx).
368			Where("repo_id = ? AND task_id = ? AND status = ? AND is_reusable_caller = ?", repoID, 0, StatusWaiting, false).
369			Exist(&ActionRunJob{})
370	}
371	
372	func UpdateRunJob(ctx context.Context, job *ActionRunJob, cond builder.Cond, cols ...string) (int64, error) {
373		e := db.GetEngine(ctx)
374	
375		sess := e.ID(job.ID)
376		if len(cols) > 0 {
377			sess.Cols(cols...)
378		}
379	
380		if cond != nil {
381			sess.Where(cond)
382		}
383	
384		affected, err := sess.Update(job)
385		if err != nil {
386			return 0, err
387		}
388	
389		// xorm's Update writes only non-zero fields when cols is empty, so a zero job.Status
390		// with empty cols means status isn't actually being persisted — skip aggregation.
391		statusUpdated := slices.Contains(cols, "status") || (len(cols) == 0 && job.Status != 0)
392		if affected == 0 || !statusUpdated {
393			return affected, nil
394		}
395	
396		if job.RunID == 0 {
397			var err error
398			if job, err = GetRunJobByRepoAndID(ctx, job.RepoID, job.ID); err != nil {
399				return 0, err
400			}
401		}
402	
403		// Reusable workflow caller jobs are never picked up by runners, so they don't need a task-version bump.
404		if statusUpdated && !job.IsReusableCaller {
405			switch {
406			case job.Status.IsWaiting():
407				// A job returning to the waiting queue is work a runner can pick up, so bump the
408				// version to wake idle runners whose tasksVersion already equals latestVersion.
409				if err := IncreaseTaskVersion(ctx, job.OwnerID, job.RepoID); err != nil {
410					return 0, err
411				}
412			case job.Status.IsDone():
413				// When a job finishes, bump the version so that idle runners — whose
414				// tasksVersion already equals the current latestVersion — learn that
415				// remaining waiting jobs are still available and attempt PickTask again.
416				// Without this bump, runners that completed their tasks would see
417				// tasksVersion==latestVersion and skip PickTask, leaving the other jobs
418				// permanently unassigned until the version changes for another reason.
419				// Only bump when waiting work actually remains for this repo, otherwise
420				// every job completion would needlessly bump the global version and wake
421				// every idle runner instance-wide for nothing.
422				hasWaiting, err := hasWaitingJobsToPick(ctx, job.RepoID)
423				if err != nil {
424					return 0, err
425				}
426				if hasWaiting {
427					if err := IncreaseTaskVersion(ctx, job.OwnerID, job.RepoID); err != nil {
428						return 0, err
429					}
430				}
431			}
432		}
433	
434		if statusUpdated && job.ParentJobID > 0 {
435			// Reusable workflow caller's children cascade their status changes upward to the parent caller.
436			parent, err := GetRunJobByRunAndID(ctx, job.RunID, job.ParentJobID)
437			if err != nil {
438				return affected, fmt.Errorf("load parent caller %d: %w", job.ParentJobID, err)
439			}
440			return affected, RefreshReusableCallerStatus(ctx, parent)
441		}
442	
443		{
444			// Other goroutines may aggregate the status of the attempt/run and update it too.
445			// So we need to load the current jobs before updating the aggregate state.
446			if job.RunAttemptID > 0 {
447				attempt, err := GetRunAttemptByRepoAndID(ctx, job.RepoID, job.RunAttemptID)
448				if err != nil {
449					return 0, err
450				}
451				jobs, err := GetRunJobsByRunAndAttemptID(ctx, job.RunID, job.RunAttemptID)
452				if err != nil {
453					return 0, err
454				}
455				attempt.Status = AggregateJobStatus(jobs)
456				if attempt.Started.IsZero() && attempt.Status.IsRunning() {
457					attempt.Started = timeutil.TimeStampNow()
458				}
459				if attempt.Stopped.IsZero() && attempt.Status.IsDone() {
460					attempt.Stopped = timeutil.TimeStampNow()
461				}
462				if err := UpdateRunAttempt(ctx, attempt, "status", "started", "stopped"); err != nil {
463					return 0, fmt.Errorf("update run attempt %d: %w", attempt.ID, err)
464				}
465			} else {
466				// TODO: Remove this fallback in the future.
467				// Legacy fallback: jobs created before migration v331 have RunAttemptID=0 and are NOT backfilled.
468				// This path keeps those runs' status consistent when their jobs finish, including:
469				//   - jobs created before migration v331 and complete on the new version starts
470				//   - zombie/abandoned cleanup cron tasks that call UpdateRunJob on legacy jobs
471				run, err := GetRunByRepoAndID(ctx, job.RepoID, job.RunID)
472				if err != nil {
473					return 0, err
474				}
475				jobs, err := GetLatestAttemptJobsByRepoAndRunID(ctx, job.RepoID, job.RunID)
476				if err != nil {
477					return 0, err
478				}
479				run.Status = AggregateJobStatus(jobs)
480				if run.Started.IsZero() && run.Status.IsRunning() {
481					run.Started = timeutil.TimeStampNow()
482				}
483				if run.Stopped.IsZero() && run.Status.IsDone() {
484					run.Stopped = timeutil.TimeStampNow()
485				}
486				if err := UpdateRun(ctx, run, "status", "started", "stopped"); err != nil {
487					return 0, fmt.Errorf("update run %d: %w", run.ID, err)
488				}
489			}
490		}
491	
492		return affected, nil
493	}
494	
495	// RefreshReusableCallerStatus recomputes a reusable workflow caller's Status, Started and Stopped from its current direct children and persists the change.
496	// No-op if caller is not a reusable caller.
497	//
498	// Concurrency: two sibling children finishing at roughly the same time can each invoke this for the same parent caller.
499	// No row-level lock is taken because AggregateJobStatus is a pure function of the children's statuses (order-independent), so racing callers arrive at the same Status.
500	func RefreshReusableCallerStatus(ctx context.Context, caller *ActionRunJob) error {
501		if !caller.IsReusableCaller {
502			return nil
503		}
504		children, err := GetDirectChildJobsByParent(ctx, caller)
505		if err != nil {
506			return err
507		}
508	
509		newStatus := AggregateJobStatus(children)
510		cols := make([]string, 0, 3)
511		if caller.Status != newStatus {
512			caller.Status = newStatus
513			cols = append(cols, "status")
514		}
515		if newStatus != StatusSkipped {
516			now := timeutil.TimeStampNow()
517			if caller.Started.IsZero() && newStatus == StatusRunning {
518				caller.Started = now
519				cols = append(cols, "started")
520			}
521			if caller.Stopped.IsZero() && newStatus.IsDone() {
522				caller.Stopped = now
523				cols = append(cols, "stopped")
524			}
525		}
526		if len(cols) == 0 {
527			return nil
528		}
529		_, err = UpdateRunJob(ctx, caller, nil, cols...)
530		return err
531	}
532	
533	func AggregateJobStatus(jobs []*ActionRunJob) Status {
534		allSuccessOrSkipped := len(jobs) != 0
535		allSkipped := len(jobs) != 0
536		var hasFailure, hasCancelled, hasCancelling, hasWaiting, hasRunning, hasBlocked bool
537		for _, job := range jobs {
538			// A failed job with continue-on-error:true does not fail the workflow run.
539			// It counts as a "continued failure" and is treated like success for aggregation.
540			isContinuedFailure := job.ContinueOnError && job.Status == StatusFailure
541			allSuccessOrSkipped = allSuccessOrSkipped && (job.Status == StatusSuccess || job.Status == StatusSkipped || isContinuedFailure)
542			allSkipped = allSkipped && job.Status == StatusSkipped
543			hasFailure = hasFailure || (job.Status == StatusFailure && !job.ContinueOnError)
544			hasCancelled = hasCancelled || job.Status == StatusCancelled
545			hasCancelling = hasCancelling || job.Status == StatusCancelling
546			hasWaiting = hasWaiting || job.Status == StatusWaiting
547			hasRunning = hasRunning || job.Status == StatusRunning
548			hasBlocked = hasBlocked || job.Status == StatusBlocked
549		}
550		switch {
551		case allSkipped:
552			return StatusSkipped
553		case allSuccessOrSkipped:
554			return StatusSuccess
555		case hasCancelling:
556			return StatusCancelling
557		case hasRunning:
558			return StatusRunning
559		case hasWaiting:
560			return StatusWaiting
561		case hasBlocked:
562			// Blocked is still a pending state, so it should outrank terminal
563			// statuses like cancelled/failure when no job is waiting or running.
564			return StatusBlocked
565		case hasCancelled:
566			return StatusCancelled
567		case hasFailure:
568			return StatusFailure
569		default:
570			return StatusUnknown // it shouldn't happen
571		}
572	}
573	
574	// CancelPreviousJobs cancels all previous jobs of the same repository, reference, workflow, and event.
575	// It's useful when a new run is triggered, and all previous runs needn't be continued anymore.
576	func CancelPreviousJobs(ctx context.Context, repoID int64, ref, workflowID string, event webhook_module.HookEventType) ([]*ActionRunJob, error) {
577		// Find all runs in the specified repository, reference, and workflow with non-final status
578		runs, total, err := db.FindAndCount[ActionRun](ctx, FindRunOptions{
579			RepoID:       repoID,
580			Ref:          ref,
581			WorkflowID:   workflowID,
582			TriggerEvent: event,
583			Status:       []Status{StatusRunning, StatusWaiting, StatusBlocked, StatusCancelling},
584		})
585		if err != nil {
586			return nil, err
587		}
588	
589		// If there are no runs found, there's no need to proceed with cancellation, so return nil.
590		if total == 0 {
591			return nil, nil
592		}
593	
594		cancelledJobs := make([]*ActionRunJob, 0, total)
595	
596		// Iterate over each found run and cancel its associated jobs.
597		for _, run := range runs {
598			// Find all jobs associated with the current run.
599			jobs, err := db.Find[ActionRunJob](ctx, FindRunJobOptions{
600				RunID: run.ID,
601			})
602			if err != nil {
603				return cancelledJobs, err
604			}
605	
606			cjs, err := CancelJobs(ctx, jobs)
607			if err != nil {
608				return cancelledJobs, err
609			}
610			cancelledJobs = append(cancelledJobs, cjs...)
611		}
612	
613		// Return nil to indicate successful cancellation of all running and waiting jobs.
614		return cancelledJobs, nil
615	}
616	
617	func CancelPreviousJobsByJobConcurrency(ctx context.Context, job *ActionRunJob) (jobsToCancel []*ActionRunJob, _ error) {
618		if job.RawConcurrency == "" {
619			return nil, nil
620		}
621		if !job.IsConcurrencyEvaluated {
622			return nil, nil
623		}
624		if job.ConcurrencyGroup == "" {
625			return nil, nil
626		}
627	
628		statusFindOption := []Status{StatusWaiting, StatusBlocked}
629		if job.ConcurrencyCancel {
630			statusFindOption = append(statusFindOption, StatusRunning)
631			statusFindOption = append(statusFindOption, StatusCancelling)
632		}
633		attempts, jobs, err := GetConcurrentRunAttemptsAndJobs(ctx, job.RepoID, job.ConcurrencyGroup, statusFindOption)
634		if err != nil {
635			return nil, fmt.Errorf("find concurrent runs and jobs: %w", err)
636		}
637		jobs = slices.DeleteFunc(jobs, func(j *ActionRunJob) bool { return j.ID == job.ID })
638		jobsToCancel = append(jobsToCancel, jobs...)
639	
640		// cancel runs in the same concurrency group
641		for _, attempt := range attempts {
642			if attempt.ID == job.RunAttemptID {
643				continue
644			}
645			jobs, err := GetRunJobsByRunAndAttemptID(ctx, attempt.RunID, attempt.ID)
646			if err != nil {
647				return nil, fmt.Errorf("find run %d attempt %d jobs: %w", attempt.RunID, attempt.ID, err)
648			}
649			jobsToCancel = append(jobsToCancel, jobs...)
650		}
651	
652		return CancelJobs(ctx, jobsToCancel)
653	}
654	
655	func CancelJobs(ctx context.Context, jobs []*ActionRunJob) ([]*ActionRunJob, error) {
656		cancelledJobs := make([]*ActionRunJob, 0, len(jobs))
657	
658		for _, job := range jobs {
659			if job.IsReusableCaller {
660				sub, err := cancelReusableCaller(ctx, job)
661				if err != nil {
662					return cancelledJobs, err
663				}
664				cancelledJobs = append(cancelledJobs, sub...)
665				continue
666			}
667	
668			c, err := cancelOneJob(ctx, job)
669			if err != nil {
670				return cancelledJobs, err
671			}
672			if c != nil {
673				cancelledJobs = append(cancelledJobs, c)
674			}
675		}
676		return cancelledJobs, nil
677	}
678	
679	// cancelOneJob cancels a single job and returns the post-cancel row
680	func cancelOneJob(ctx context.Context, job *ActionRunJob) (*ActionRunJob, error) {
681		if job.Status.IsDone() {
682			return nil, nil //nolint:nilnil // signal "nothing to cancel; not an error"
683		}
684		// No associated task: mark Cancelled directly. This includes reusable callers and jobs that never reached PickTask.
685		if job.TaskID == 0 {
686			job.Status = StatusCancelled
687			job.Stopped = timeutil.TimeStampNow()
688			n, err := UpdateRunJob(ctx, job, builder.Eq{"task_id": 0}, "status", "stopped")
689			if err != nil {
690				return nil, err
691			}
692			if n == 0 {
693				log.Error("Failed to cancel job %d because it has changed", job.ID)
694				return nil, nil //nolint:nilnil // signal "nothing to cancel; not an error"
695			}
696			return job, nil
697		}
698		// Has a task: stop the task and re-read the row.
699		if err := StopTask(ctx, job.TaskID, StatusCancelling); err != nil {
700			return nil, err
701		}
702		updated, err := GetRunJobByRunAndID(ctx, job.RunID, job.ID)
703		if err != nil {
704			return nil, fmt.Errorf("get job: %w", err)
705		}
706		return updated, nil
707	}
708	
709	// cancelReusableCaller cancels `caller` and all its child jobs
710	func cancelReusableCaller(ctx context.Context, caller *ActionRunJob) ([]*ActionRunJob, error) {
711		cancelledJobs := make([]*ActionRunJob, 0)
712	
713		attemptJobs, err := GetRunJobsByRunAndAttemptID(ctx, caller.RunID, caller.RunAttemptID)
714		if err != nil {
715			return cancelledJobs, err
716		}
717	
718		// Cancel descendants deepest-first, then the caller: a caller's status is aggregated from its children,
719		// so each child must reach its final state before its parent caller is re-aggregated.
720		// A child's ID always exceeds its parent's, so descending ID is a valid deepest-first order.
721		descendants := CollectAllDescendantJobs(caller, attemptJobs)
722		slices.SortFunc(descendants, func(a, b *ActionRunJob) int { return cmp.Compare(b.ID, a.ID) })
723	
724		for _, c := range descendants {
725			cancelled, err := cancelOneJob(ctx, c)
726			if err != nil {
727				return cancelledJobs, err
728			}
729			if cancelled != nil {
730				cancelledJobs = append(cancelledJobs, cancelled)
731			}
732		}
733	
734		if c, err := cancelOneJob(ctx, caller); err != nil {
735			return cancelledJobs, err
736		} else if c != nil {
737			cancelledJobs = append(cancelledJobs, c)
738		}
739		return cancelledJobs, nil
740	}
741

