679	// cancelOneJob cancels a single job and returns the post-cancel row
680	func cancelOneJob(ctx context.Context, job *ActionRunJob) (*ActionRunJob, error) {
681		if job.Status.IsDone() {
682			return nil, nil //nolint:nilnil // signal "nothing to cancel; not an error"
683		}
684		// No associated task: mark Cancelled directly. This includes reusable callers and jobs that never reached PickTask.
685		if job.TaskID == 0 {
686			job.Status = StatusCancelled
687			job.Stopped = timeutil.TimeStampNow()
688			n, err := UpdateRunJob(ctx, job, builder.Eq{"task_id": 0}, "status", "stopped")
689			if err != nil {
690				return nil, err
691			}
692			if n == 0 {
693				log.Error("Failed to cancel job %d because it has changed", job.ID)
694				return nil, nil //nolint:nilnil // signal "nothing to cancel; not an error"
695			}
696			return job, nil
697		}
698		// Has a task: stop the task and re-read the row.
699		if err := StopTask(ctx, job.TaskID, StatusCancelling); err != nil {
700			return nil, err
701		}
702		updated, err := GetRunJobByRunAndID(ctx, job.RunID, job.ID)
703		if err != nil {
704			return nil, fmt.Errorf("get job: %w", err)
705		}
706		return updated, nil
707	}
708	
709	// cancelReusableCaller cancels `caller` and all its child jobs
710	func cancelReusableCaller(ctx context.Context, caller *ActionRunJob) ([]*ActionRunJob, error) {
711		cancelledJobs := make([]*ActionRunJob, 0)
712	
713		attemptJobs, err := GetRunJobsByRunAndAttemptID(ctx, caller.RunID, caller.RunAttemptID)
714		if err != nil {
715			return cancelledJobs, err
716		}
717	
718		// Cancel descendants deepest-first, then the caller: a caller's status is aggregated from its children,
719		// so each child must reach its final state before its parent caller is re-aggregated.
720		// A child's ID always exceeds its parent's, so descending ID is a valid deepest-first order.
721		descendants := CollectAllDescendantJobs(caller, attemptJobs)
722		slices.SortFunc(descendants, func(a, b *ActionRunJob) int { return cmp.Compare(b.ID, a.ID) })
723	
724		for _, c := range descendants {
725			cancelled, err := cancelOneJob(ctx, c)
726			if err != nil {
727				return cancelledJobs, err
728			}
729			if cancelled != nil {
730				cancelledJobs = append(cancelledJobs, cancelled)
731			}
732		}
733	
734		if c, err := cancelOneJob(ctx, caller); err != nil {
735			return cancelledJobs, err
736		} else if c != nil {
737			cancelledJobs = append(cancelledJobs, c)
738		}
739		return cancelledJobs, nil
740	}
