392	// ReleaseTaskForRunner reverts a freshly-claimed but undelivered task: it deletes
393	// the task together with its steps and returns the job to the waiting queue. It is
394	// used when assembling the runner response fails after the job was already claimed,
395	// so the job is not stranded in running state with no runner ever executing it.
396	func ReleaseTaskForRunner(ctx context.Context, task *ActionTask) error {
397		return db.WithTx(ctx, func(ctx context.Context) error {
398			e := db.GetEngine(ctx)
399	
400			job, err := GetRunJobByRepoAndID(ctx, task.RepoID, task.JobID)
401			if err != nil {
402				return err
403			}
404	
405			job.Status = StatusWaiting
406			job.Started = 0
407			job.TaskID = 0
408			// Guard on task_id and status so we only release while the job still
409			// references this task and has not progressed past running.
410			n, err := UpdateRunJob(ctx, job, builder.Eq{"task_id": task.ID, "status": StatusRunning}, "status", "started", "task_id")
411			if err != nil {
412				return err
413			}
414			if n != 1 {
415				return fmt.Errorf("release task %d: job %d no longer references it", task.ID, task.JobID)
416			}
417	
418			if _, err := e.Delete(&ActionTaskStep{TaskID: task.ID}); err != nil {
419				return err
420			}
421			if _, err := e.ID(task.ID).Delete(&ActionTask{}); err != nil {
422				return err
423			}
424			return nil
425		})
426	}
