540	func StopTask(ctx context.Context, taskID int64, status Status) error {
541		if !status.IsDone() && status != StatusCancelling {
542			return fmt.Errorf("cannot stop task with status %v", status)
543		}
544		e := db.GetEngine(ctx)
545	
546		task := &ActionTask{}
547		if has, err := e.ID(taskID).Get(task); err != nil {
548			return err
549		} else if !has {
550			return util.ErrNotExist
551		}
552		if task.Status.IsDone() {
553			return nil
554		}
555	
556		now := timeutil.TimeStampNow()
557		if status == StatusCancelling {
558			runner, err := GetRunnerByID(ctx, task.RunnerID)
559			if err != nil {
560				if !errors.Is(err, util.ErrNotExist) {
561					return err
562				}
563				status = StatusCancelled
564			} else if !runner.HasCancellingSupport {
565				status = StatusCancelled
566			}
567		}
568	
569		if status == StatusCancelling {
570			task.Status = StatusCancelling
571	
572			if _, err := UpdateRunJob(ctx, &ActionRunJob{
573				ID:     task.JobID,
574				RepoID: task.RepoID,
575				Status: StatusCancelling,
576			}, nil, "status"); err != nil {
577				return err
578			}
579	
580			return UpdateTask(ctx, task, "status")
581		}
582	
583		task.Status = status
584		task.Stopped = now
585		if _, err := UpdateRunJob(ctx, &ActionRunJob{
586			ID:      task.JobID,
587			RepoID:  task.RepoID,
588			Status:  task.Status,
589			Stopped: task.Stopped,
590		}, nil); err != nil {
591			return err
592		}
593	
594		if err := UpdateTask(ctx, task, "status", "stopped"); err != nil {
595			return err
596		}
597	
598		if err := task.LoadAttributes(ctx); err != nil {
599			return err
600		}
601	
602		for _, step := range task.Steps {
603			if !step.Status.IsDone() {
604				step.Status = status
605				if step.Started == 0 {
606					step.Started = now
607				}
608				step.Stopped = now
609			}
610			if _, err := e.ID(step.ID).Update(step); err != nil {
611				return err
612			}
613		}
614	
615		return nil
616	}
