302	func GetWorkflowLatestRun(ctx context.Context, repoID int64, workflowFile, branch, event string) (*ActionRun, error) {
303		var run ActionRun
304		q := db.GetEngine(ctx).Where("repo_id=?", repoID).
305			And("ref = ?", branch).
306			And("workflow_id = ?", workflowFile).
307			// TODO: the badge only reflects the repo's own (repo-level) runs; a same-named scoped run must not leak in.
308			// Support a scoped-workflow badge later by making this source-aware.
309			And("is_scoped_run = ?", false)
310		if event != "" {
311			q.And("event = ?", event)
312		}
313		has, err := q.Desc("id").Get(&run)
314		if err != nil {
315			return nil, err
316		} else if !has {
317			return nil, util.NewNotExistErrorf("run with repo_id %d, ref %s, workflow_id %s", repoID, branch, workflowFile)
318		}
