77			// 1. increase global
78			if err := increaseTasksVersionByScope(ctx, 0, 0); err != nil {
79				log.Error("IncreaseTasksVersionByScope(Global): %v", err)
80				return err
81			}
82	
83			// 2. increase owner
84			if ownerID > 0 {
85				if err := increaseTasksVersionByScope(ctx, ownerID, 0); err != nil {
86					log.Error("IncreaseTasksVersionByScope(Owner): %v", err)
87					return err
88				}
89			}
90	
91			// 3. increase repo
92			if repoID > 0 {
93				if err := increaseTasksVersionByScope(ctx, 0, repoID); err != nil {
94					log.Error("IncreaseTasksVersionByScope(Repo): %v", err)
95					return err
96				}
97			}
98	
99			return nil
100		})
101	}
