237	// UpdateRepoRunsNumbers updates the number of runs and closed runs of a repository.
238	// Callers MUST invoke this from outside any transaction that has X-locked action_run rows for the same repo, otherwise, transaction deadlock
239	func UpdateRepoRunsNumbers(ctx context.Context, repoID int64) {
240		if db.InTransaction(ctx) {
241			setting.PanicInDevOrTesting("UpdateRepoRunsNumbers must not be called inside a transaction")
242		}
243	
244		e := db.GetEngine(ctx)
245	
246		numActionRuns, err := e.Where("repo_id = ?", repoID).Count(new(ActionRun))
247		if err != nil {
248			log.Error("UpdateRepoRunsNumbers count num_action_runs for repo %d: %v", repoID, err)
249			return
250		}
251	
252		numClosedActionRuns, err := e.Where("repo_id = ?", repoID).
253			In("status", StatusSuccess, StatusFailure, StatusCancelled, StatusSkipped).
254			Count(new(ActionRun))
255		if err != nil {
256			log.Error("UpdateRepoRunsNumbers count num_closed_action_runs for repo %d: %v", repoID, err)
257			return
258		}
259	
260		if _, err := e.ID(repoID).Cols("num_action_runs", "num_closed_action_runs").NoAutoTime().Update(&repo_model.Repository{
261			NumActionRuns:       int(numActionRuns),
262			NumClosedActionRuns: int(numClosedActionRuns),
263		}); err != nil {
264			log.Error("UpdateRepoRunsNumbers update repo %d: %v", repoID, err)
265		}
266	}
