322	// UpdateRun updates a run.
323	// It requires the inputted run has Version set.
324	// It will return error if the version is not matched (it means the run has been changed after loaded).
325	func UpdateRun(ctx context.Context, run *ActionRun, cols ...string) error {
326		sess := db.GetEngine(ctx).ID(run.ID)
327		if len(cols) > 0 {
328			sess.Cols(cols...)
329		}
330		run.Title = util.EllipsisDisplayString(run.Title, 255)
331		affected, err := sess.Update(run)
332		if err != nil {
333			return err
334		}
335		if affected == 0 {
336			return errors.New("run has changed")
337			// It's impossible that the run is not found, since Gitea never deletes runs.
338		}
339	
340		return nil
341	}
