345	// GetConcurrentRunAttemptsAndJobs returns run attempts and jobs in the same concurrency group by statuses.
346	func GetConcurrentRunAttemptsAndJobs(ctx context.Context, repoID int64, concurrencyGroup string, status []Status) ([]*ActionRunAttempt, []*ActionRunJob, error) {
347		attempts, err := FindConcurrentRunAttempts(ctx, repoID, concurrencyGroup, status)
348		if err != nil {
349			return nil, nil, fmt.Errorf("find run attempts: %w", err)
350		}
351	
352		jobs, err := db.Find[ActionRunJob](ctx, &FindRunJobOptions{
353			RepoID:           repoID,
354			ConcurrencyGroup: concurrencyGroup,
355			Statuses:         status,
356		})
357		if err != nil {
358			return nil, nil, fmt.Errorf("find jobs: %w", err)
359		}
360	
361		return attempts, jobs, nil
362	}
363	
364	func CancelPreviousJobsByRunConcurrency(ctx context.Context, attempt *ActionRunAttempt) ([]*ActionRunJob, error) {
365		if attempt.ConcurrencyGroup == "" {
366			return nil, nil
367		}
368	
369		var jobsToCancel []*ActionRunJob
370	
371		statusFindOption := []Status{StatusWaiting, StatusBlocked}
372		if attempt.ConcurrencyCancel {
373			statusFindOption = append(statusFindOption, StatusRunning)
374			statusFindOption = append(statusFindOption, StatusCancelling)
375		}
376		attempts, jobs, err := GetConcurrentRunAttemptsAndJobs(ctx, attempt.RepoID, attempt.ConcurrencyGroup, statusFindOption)
377		if err != nil {
378			return nil, fmt.Errorf("find concurrent runs and jobs: %w", err)
379		}
380		jobsToCancel = append(jobsToCancel, jobs...)
381	
382		// cancel runs in the same concurrency group
383		for _, concurrentAttempt := range attempts {
384			if concurrentAttempt.RunID == attempt.RunID {
385				continue
386			}
387			jobs, err := GetRunJobsByRunAndAttemptID(ctx, concurrentAttempt.RunID, concurrentAttempt.ID)
388			if err != nil {
389				return nil, fmt.Errorf("find run %d attempt %d jobs: %w", concurrentAttempt.RunID, concurrentAttempt.ID, err)
390			}
391			jobsToCancel = append(jobsToCancel, jobs...)
392		}
393	
394		return CancelJobs(ctx, jobsToCancel)
395	}
