97	// FindConcurrentRunAttempts returns attempts in the given concurrency group and status set.
98	// Results are unordered; callers must not depend on any particular row order.
99	func FindConcurrentRunAttempts(ctx context.Context, repoID int64, concurrencyGroup string, statuses []Status) ([]*ActionRunAttempt, error) {
100		attempts := make([]*ActionRunAttempt, 0)
101		sess := db.GetEngine(ctx).Where("repo_id=? AND concurrency_group=?", repoID, concurrencyGroup)
102		if len(statuses) > 0 {
103			sess = sess.In("status", statuses)
104		}
105		return attempts, sess.Find(&attempts)
106	}
107	
108	func UpdateRunAttempt(ctx context.Context, attempt *ActionRunAttempt, cols ...string) error {
109		if slices.Contains(cols, "status") && attempt.Started.IsZero() && attempt.Status.IsRunning() {
110			attempt.Started = timeutil.TimeStampNow()
111			cols = append(cols, "started")
112		}
113	
114		sess := db.GetEngine(ctx).ID(attempt.ID)
115		if len(cols) > 0 {
116			sess.Cols(cols...)
117		}
118		if _, err := sess.Update(attempt); err != nil {
119			return err
120		}
121	
122		// Only status/timing changes on an attempt need to update the latest run.
123		if len(cols) > 0 && !slices.Contains(cols, "status") && !slices.Contains(cols, "started") && !slices.Contains(cols, "stopped") {
124			return nil
125		}
126	
127		run, err := GetRunByRepoAndID(ctx, attempt.RepoID, attempt.RunID)
128		if err != nil {
129			return err
130		}
131		if run.LatestAttemptID != attempt.ID {
132			log.Warn("run %d cannot be updated by an old attempt %d", run.LatestAttemptID, attempt.ID)
133			return nil
134		}
135	
136		run.Status = attempt.Status
137		run.Started = attempt.Started
138		run.Stopped = attempt.Stopped
139		return UpdateRun(ctx, run, "status", "started", "stopped")
140	}
