28	// ActionRunner represents runner machines
29	//
30	// It can be:
31	//  1. global runner, OwnerID is 0 and RepoID is 0
32	//  2. org/user level runner, OwnerID is org/user ID and RepoID is 0
33	//  3. repo level runner, OwnerID is 0 and RepoID is repo ID
34	//
35	// Please note that it's not acceptable to have both OwnerID and RepoID to be non-zero,
36	// or it will be complicated to find runners belonging to a specific owner.
37	// For example, conditions like `OwnerID = 1` will also return runner {OwnerID: 1, RepoID: 1},
38	// but it's a repo level runner, not an org/user level runner.
39	// To avoid this, make it clear with {OwnerID: 0, RepoID: 1} for repo level runners.
40	type ActionRunner struct {
41		ID          int64
42		UUID        string                 `xorm:"CHAR(36) UNIQUE"`
43		Name        string                 `xorm:"VARCHAR(255)"`
44		Version     string                 `xorm:"VARCHAR(64)"`
45		OwnerID     int64                  `xorm:"index"`
46		Owner       *user_model.User       `xorm:"-"`
47		RepoID      int64                  `xorm:"index"`
48		Repo        *repo_model.Repository `xorm:"-"`
49		Description string                 `xorm:"TEXT"`
50		Base        int                    // 0 native 1 docker 2 virtual machine
51		RepoRange   string                 // glob match which repositories could use this runner
52	
53		Token     string `xorm:"-"`
54		TokenHash string `xorm:"UNIQUE"` // sha256 of token
55		TokenSalt string
56		// TokenLastEight string `xorm:"token_last_eight"` // it's unnecessary because we don't find runners by token
57	
58		LastOnline timeutil.TimeStamp `xorm:"index"`
59		LastActive timeutil.TimeStamp `xorm:"index"`
60	
61		// Store labels defined in state file (default: .runner file) of `act_runner`
62		AgentLabels []string `xorm:"TEXT"`
63		// Store if this is a runner that only ever get one single job assigned
64		Ephemeral bool `xorm:"ephemeral NOT NULL DEFAULT false"`
65		// Store if this runner is disabled and should not pick up new jobs
66		IsDisabled bool `xorm:"is_disabled NOT NULL DEFAULT false"`
67		// Store if this runner supports the StatusCancelling flow
68		HasCancellingSupport bool `xorm:"has_cancelling_support NOT NULL DEFAULT false"`
69	
70		Created timeutil.TimeStamp `xorm:"created"`
71		Updated timeutil.TimeStamp `xorm:"updated"`
72		Deleted timeutil.TimeStamp `xorm:"deleted"`
73	}
74	
75	const (
76		RunnerOfflineTime = time.Minute
77		RunnerIdleTime    = 10 * time.Second
78		// RunnerHeartbeatInterval is how often last_online is persisted on poll.
79		// Must stay well below RunnerOfflineTime so runners don't flap to offline.
80		RunnerHeartbeatInterval = 30 * time.Second
81		// RunnerActiveInterval is how often last_active is persisted while a runner
82		// streams task updates and logs. Must stay well below RunnerIdleTime so a
83		// busy runner keeps showing ACTIVE without a DB write on every RPC.
84		RunnerActiveInterval = 5 * time.Second
85	)
86	
87	// ShouldPersistLastOnline reports whether last_online is stale enough to be
88	// worth writing back. Avoids a DB write on every runner poll.
89	func ShouldPersistLastOnline(last timeutil.TimeStamp, now time.Time) bool {
90		return now.Sub(last.AsTime()) >= RunnerHeartbeatInterval
91	}
92	
93	// ShouldPersistLastActive reports whether last_active is stale enough to be
94	// worth writing back. Avoids a DB write on every UpdateTask/UpdateLog RPC while
95	// a runner is actively streaming logs.
96	func ShouldPersistLastActive(last timeutil.TimeStamp, now time.Time) bool {
97		return now.Sub(last.AsTime()) >= RunnerActiveInterval
98	}
99	
100	// BelongsToOwnerName before calling, should guarantee that all attributes are loaded
101	func (r *ActionRunner) BelongsToOwnerName() string {
102		if r.RepoID != 0 {
103			return r.Repo.FullName()
104		}
105		if r.OwnerID != 0 {
106			return r.Owner.Name
107		}
108		return ""
109	}
110	
111	func (r *ActionRunner) BelongsToOwnerType() types.OwnerType {
112		if r.RepoID != 0 {
113			return types.OwnerTypeRepository
114		}
115		if r.OwnerID != 0 {
116			switch r.Owner.Type {
117			case user_model.UserTypeOrganization:
118				return types.OwnerTypeOrganization
119			case user_model.UserTypeIndividual:
120				return types.OwnerTypeIndividual
121			}
122		}
123		return types.OwnerTypeSystemGlobal
124	}
