153	// EditableInContext checks if the runner is editable by the "context" owner/repo
154	// ownerID == 0 and repoID == 0 means "admin" context, any runner including global runners could be edited
155	// ownerID == 0 and repoID != 0 means "repo" context, any runner belonging to the given repo could be edited
156	// ownerID != 0 and repoID == 0 means "owner(org/user)" context, any runner belonging to the given user/org could be edited
157	// ownerID != 0 and repoID != 0 means "owner" OR "repo" context, legacy behavior, but we should forbid using it
158	func (r *ActionRunner) EditableInContext(ownerID, repoID int64) bool {
159		if ownerID != 0 && repoID != 0 {
160			setting.PanicInDevOrTesting("ownerID and repoID should not be both set")
161		}
162		if ownerID == 0 && repoID == 0 {
163			return true
164		}
165		if ownerID > 0 && r.OwnerID == ownerID {
166			return true
167		}
168		return repoID > 0 && r.RepoID == repoID
169	}
