174			var user user_model.User
175			has, err := db.GetEngine(ctx).ID(r.OwnerID).Get(&user)
176			if err != nil {
177				return err
178			}
179			if has {
180				r.Owner = &user
181			}
182		}
183		if r.RepoID > 0 {
184			var repo repo_model.Repository
185			has, err := db.GetEngine(ctx).ID(r.RepoID).Get(&repo)
186			if err != nil {
187				return err
188			}
189			if has {
190				r.Repo = &repo
191			}
192		}
193		return nil
194	}
