294	// GetRunnerByUUID returns a runner via uuid
295	func GetRunnerByUUID(ctx context.Context, uuid string) (*ActionRunner, error) {
296		var runner ActionRunner
297		has, err := db.GetEngine(ctx).Where("uuid=?", uuid).Get(&runner)
298		if err != nil {
299			return nil, err
300		} else if !has {
301			return nil, fmt.Errorf("runner with uuid %s: %w", uuid, util.ErrNotExist)
302		}
303		return &runner, nil
304	}
305	
306	// GetRunnerByID returns a runner via id
307	func GetRunnerByID(ctx context.Context, id int64) (*ActionRunner, error) {
308		var runner ActionRunner
309		has, err := db.GetEngine(ctx).Where("id=?", id).Get(&runner)
310		if err != nil {
311			return nil, err
312		} else if !has {
313			return nil, fmt.Errorf("runner with id %d: %w", id, util.ErrNotExist)
314		}
315		return &runner, nil
316	}
