318	// UpdateRunner updates runner's information.
319	func UpdateRunner(ctx context.Context, r *ActionRunner, cols ...string) error {
320		e := db.GetEngine(ctx)
321		r.Name = util.EllipsisDisplayString(r.Name, 255)
322		var err error
323		if len(cols) == 0 {
324			_, err = e.ID(r.ID).AllCols().Update(r)
325		} else {
326			_, err = e.ID(r.ID).Cols(cols...).Update(r)
327		}
328		return err
329	}
330	
331	func SetRunnerDisabled(ctx context.Context, runner *ActionRunner, isDisabled bool) error {
332		if runner.IsDisabled == isDisabled {
333			return nil
334		}
335	
336		return db.WithTx(ctx, func(ctx context.Context) error {
337			runner.IsDisabled = isDisabled
338			if err := UpdateRunner(ctx, runner, "is_disabled"); err != nil {
339				return err
340			}
341			return IncreaseTaskVersion(ctx, runner.OwnerID, runner.RepoID)
342		})
343	}
344	
345	// DeleteRunner deletes a runner by given ID.
346	func DeleteRunner(ctx context.Context, id int64) error {
347		if _, err := GetRunnerByID(ctx, id); err != nil {
348			return err
349		}
350	
351		_, err := db.DeleteByID[ActionRunner](ctx, id)
352		return err
353	}
354	
355	// DeleteEphemeralRunner deletes a ephemeral runner by given ID.
356	func DeleteEphemeralRunner(ctx context.Context, id int64) error {
357		runner, err := GetRunnerByID(ctx, id)
358		if err != nil {
359			if errors.Is(err, util.ErrNotExist) {
360				return nil
361			}
362			return err
363		}
364		if !runner.Ephemeral {
365			return nil
366		}
367	
368		_, err = db.DeleteByID[ActionRunner](ctx, id)
369		return err
370	}
371	
372	// CreateRunner creates new runner.
373	func CreateRunner(ctx context.Context, t *ActionRunner) error {
374		if t.OwnerID != 0 && t.RepoID != 0 {
375			// It's trying to create a runner that belongs to a repository, but OwnerID has been set accidentally.
376			// Remove OwnerID to avoid confusion; it's not worth returning an error here.
377			t.OwnerID = 0
378		}
379		t.Name = util.EllipsisDisplayString(t.Name, 255)
380		return db.Insert(ctx, t)
381	}
382	
383	func CountRunnersWithoutBelongingOwner(ctx context.Context) (int64, error) {
384		// Only affect action runners were a owner ID is set, as actions runners
385		// could also be created on a repository.
386		return db.GetEngine(ctx).Table("action_runner").
387			Join("LEFT", "`user`", "`action_runner`.owner_id = `user`.id").
388			Where("`action_runner`.owner_id != ?", 0).
389			And(builder.IsNull{"`user`.id"}).
390			Count(new(ActionRunner))
391	}
392	
393	func FixRunnersWithoutBelongingOwner(ctx context.Context) (int64, error) {
394		subQuery := builder.Select("`action_runner`.id").
395			From("`action_runner`").
396			Join("LEFT", "`user`", "`action_runner`.owner_id = `user`.id").
397			Where(builder.Neq{"`action_runner`.owner_id": 0}).
398			And(builder.IsNull{"`user`.id"})
399		b := builder.Delete(builder.In("id", subQuery)).From("`action_runner`")
400		res, err := db.GetEngine(ctx).Exec(b)
401		if err != nil {
402			return 0, err
403		}
404		return res.RowsAffected()
405	}
406	
407	func CountRunnersWithoutBelongingRepo(ctx context.Context) (int64, error) {
408		return db.GetEngine(ctx).Table("action_runner").
409			Join("LEFT", "`repository`", "`action_runner`.repo_id = `repository`.id").
410			Where("`action_runner`.repo_id != ?", 0).
411			And(builder.IsNull{"`repository`.id"}).
412			Count(new(ActionRunner))
413	}
414	
415	func FixRunnersWithoutBelongingRepo(ctx context.Context) (int64, error) {
416		subQuery := builder.Select("`action_runner`.id").
417			From("`action_runner`").
418			Join("LEFT", "`repository`", "`action_runner`.repo_id = `repository`.id").
419			Where(builder.Neq{"`action_runner`.repo_id": 0}).
420			And(builder.IsNull{"`repository`.id"})
421		b := builder.Delete(builder.In("id", subQuery)).From("`action_runner`")
422		res, err := db.GetEngine(ctx).Exec(b)
423		if err != nil {
424			return 0, err
425		}
426		return res.RowsAffected()
427	}
428	
429	func CountWrongRepoLevelRunners(ctx context.Context) (int64, error) {
430		var result int64
431		_, err := db.GetEngine(ctx).SQL("SELECT count(`id`) FROM `action_runner` WHERE `repo_id` > 0 AND `owner_id` > 0").Get(&result)
432		return result, err
433	}
434	
435	func UpdateWrongRepoLevelRunners(ctx context.Context) (int64, error) {
436		result, err := db.GetEngine(ctx).Exec("UPDATE `action_runner` SET `owner_id` = 0 WHERE `repo_id` > 0 AND `owner_id` > 0")
437		if err != nil {
438			return 0, err
439		}
440		return result.RowsAffected()
