21	
22		"connectrpc.com/connect"
23		gouuid "github.com/google/uuid"
24		"google.golang.org/grpc/codes"
25		"google.golang.org/grpc/status"
26		"google.golang.org/protobuf/proto"
27	)
28	
29	func NewRunnerServiceHandler() (string, http.Handler) {
30		return runnerv1connect.NewRunnerServiceHandler(
31			&Service{},
32			connect.WithCompressMinBytes(1024),
33			withRunner,
34		)
35	}
36	
37	var _ runnerv1connect.RunnerServiceClient = (*Service)(nil)
38	
39	type Service struct{}
40	
41	// Register for new runner.
42	func (s *Service) Register(
43		ctx context.Context,
44		req *connect.Request[runnerv1.RegisterRequest],
45	) (*connect.Response[runnerv1.RegisterResponse], error) {
46		if req.Msg.Token == "" || req.Msg.Name == "" {
47			return nil, errors.New("missing runner token, name")
48		}
49	
50		runnerToken, err := actions_model.GetRunnerToken(ctx, req.Msg.Token)
51		if err != nil {
52			return nil, errors.New("runner registration token not found")
53		}
54	
55		if !runnerToken.IsActive {
56			return nil, errors.New("runner registration token has been invalidated, please use the latest one")
57		}
58	
59		if runnerToken.OwnerID > 0 {
60			if _, err := user_model.GetUserByID(ctx, runnerToken.OwnerID); err != nil {
61				return nil, errors.New("owner of the token not found")
62			}
63		}
64	
65		if runnerToken.RepoID > 0 {
66			if _, err := repo_model.GetRepositoryByID(ctx, runnerToken.RepoID); err != nil {
67				return nil, errors.New("repository of the token not found")
68			}
69		}
70	
71		labels := req.Msg.Labels
72		hasCancellingSupport := slices.Contains(req.Msg.GetCapabilities(), runnerCapabilityCancelling)
73	
74		// create new runner
75		name := util.EllipsisDisplayString(req.Msg.Name, 255)
76		runner := &actions_model.ActionRunner{
77			UUID:                 gouuid.New().String(),
78			Name:                 name,
79			OwnerID:              runnerToken.OwnerID,
80			RepoID:               runnerToken.RepoID,
81			Version:              req.Msg.Version,
82			AgentLabels:          labels,
83			Ephemeral:            req.Msg.Ephemeral,
84			HasCancellingSupport: hasCancellingSupport,
85		}
86		runner.GenerateAndFillToken()
87	
88		// create new runner
89		if err := actions_model.CreateRunner(ctx, runner); err != nil {
90			return nil, errors.New("can't create new runner")
91		}
92	
93		// update token status
94		runnerToken.IsActive = true
95		if err := actions_model.UpdateRunnerToken(ctx, runnerToken, "is_active"); err != nil {
96			return nil, errors.New("can't update runner token status")
97		}
98	
99		res := connect.NewResponse(&runnerv1.RegisterResponse{
100			Runner: &runnerv1.Runner{
101				Id:        runner.ID,
102				Uuid:      runner.UUID,
103				Token:     runner.Token,
104				Name:      runner.Name,
105				Version:   runner.Version,
106				Labels:    runner.AgentLabels,
107				Ephemeral: runner.Ephemeral,
108			},
109		})
110	
111		return res, nil
112	}
113	
114	// runnerCapabilityCancelling is the wire string the runner advertises in its
115	// capabilities list to indicate it understands the transitional cancelling
116	// state and will run post-step cleanup before finalizing the task.
117	const runnerCapabilityCancelling = "cancelling"
118	
119	type declareRequest interface {
120		proto.Message
121		GetVersion() string
122		GetLabels() []string
123		GetCapabilities() []string
124	}
125	
126	func applyDeclareRequestToRunner(runner *actions_model.ActionRunner, req declareRequest) []string {
127		runner.AgentLabels = req.GetLabels()
128		runner.Version = req.GetVersion()
129	
130		cols := []string{"agent_labels", "version"}
131		hasCancellingSupport := slices.Contains(req.GetCapabilities(), runnerCapabilityCancelling)
132		if runner.HasCancellingSupport != hasCancellingSupport {
133			runner.HasCancellingSupport = hasCancellingSupport
134			cols = append(cols, "has_cancelling_support")
135		}
136	
137		return cols
138	}
139	
140	func (s *Service) Declare(
141		ctx context.Context,
142		req *connect.Request[runnerv1.DeclareRequest],
143	) (*connect.Response[runnerv1.DeclareResponse], error) {
144		runner := GetRunner(ctx)
145		if err := actions_model.UpdateRunner(ctx, runner, applyDeclareRequestToRunner(runner, req.Msg)...); err != nil {
146			return nil, status.Errorf(codes.Internal, "update runner: %v", err)
147		}
148	
149		resp := connect.NewResponse(&runnerv1.DeclareResponse{
150			Runner: &runnerv1.Runner{
151				Id:      runner.ID,
152				Uuid:    runner.UUID,
153				Token:   runner.Token,
154				Name:    runner.Name,
155				Version: runner.Version,
156				Labels:  runner.AgentLabels,
157			},
158		})
159		// Capabilities are communicated via headers to avoid a hard dependency on a proto bump.
160		// Older runners ignore unknown headers; newer runners can use this for feature negotiation.
161		resp.Header().Set("X-Gitea-Actions-Capabilities", actions_model.RunnerCapabilities())
162		return resp, nil
163	}
164	
165	// FetchTask assigns a task to the runner
166	func (s *Service) FetchTask(
167		ctx context.Context,
168		req *connect.Request[runnerv1.FetchTaskRequest],
169	) (*connect.Response[runnerv1.FetchTaskResponse], error) {
170		runner := GetRunner(ctx)
171	
172		var task *runnerv1.Task
173		tasksVersion := req.Msg.TasksVersion // task version from runner
174		latestVersion, err := actions_model.GetTasksVersionByScope(ctx, runner.OwnerID, runner.RepoID)
175		if err != nil {
176			return nil, status.Errorf(codes.Internal, "query tasks version failed: %v", err)
177		} else if latestVersion == 0 {
178			if err := actions_model.IncreaseTaskVersion(ctx, runner.OwnerID, runner.RepoID); err != nil {
179				return nil, status.Errorf(codes.Internal, "fail to increase task version: %v", err)
180			}
181			// if we don't increase the value of `latestVersion` here,
182			// the response of FetchTask will return tasksVersion as zero.
183			// and the runner will treat it as an old version of Gitea.
184			latestVersion++
185		}
186	
187		if tasksVersion != latestVersion {
188			// Re-load runner from DB so task assignment uses current IsDisabled state
189			// (avoids race where disable commits while this request still has stale runner).
190			freshRunner, err := actions_model.GetRunnerByUUID(ctx, runner.UUID)
191			if err != nil {
192				return nil, status.Errorf(codes.Internal, "get runner: %v", err)
193			}
194			// if the task version in request is not equal to the version in db,
195			// it means there may still be some tasks that haven't been assigned.
196			// try to pick a task for the runner that send the request.
197			if t, ok, throttled, err := actions_service.TryPickTask(ctx, freshRunner); err != nil {
198				log.Error("pick task failed: %v", err)
199				return nil, status.Errorf(codes.Internal, "pick task: %v", err)
200			} else if throttled {
201				// Concurrency limit reached: don't advance the runner's tasks version,
202				// so it retries on its next poll instead of sleeping until the next bump.
203				latestVersion = tasksVersion
204				//  A steady stream here means MAX_CONCURRENT_TASK_PICKS is too low for the fleet.
205				log.Debug("task pick throttled for runner %q (id %d); it will retry on its next poll", freshRunner.Name, freshRunner.ID)
206			} else if ok {
207				task = t
208			}
209		}
210		res := connect.NewResponse(&runnerv1.FetchTaskResponse{
211			Task:         task,
212			TasksVersion: latestVersion,
213		})
214		return res, nil
215	}
216	
217	// UpdateTask updates the task status.
218	func (s *Service) UpdateTask(
219		ctx context.Context,
220		req *connect.Request[runnerv1.UpdateTaskRequest],
221	) (*connect.Response[runnerv1.UpdateTaskResponse], error) {
222		runner := GetRunner(ctx)
223	
224		task, err := actions_model.UpdateTaskByState(ctx, runner.ID, req.Msg.State)
225		if err != nil {
226			return nil, status.Errorf(codes.Internal, "update task: %v", err)
227		}
228	
229		for k, v := range req.Msg.Outputs {
230			if len(k) > 255 {
231				log.Warn("Ignore the output of task %d because the key is too long: %q", task.ID, k)
232				continue
233			}
234			// The value can be a maximum of 1 MB
235			if l := len(v); l > 1024*1024 {
236				log.Warn("Ignore the output %q of task %d because the value is too long: %v", k, task.ID, l)
237				continue
238			}
239			// There's another limitation on GitHub that the total of all outputs in a workflow run can be a maximum of 50 MB.
240			// We don't check the total size here because it's not easy to do, and it doesn't really worth it.
241			// See https://docs.github.com/en/actions/using-jobs/defining-outputs-for-jobs
242	
243			if err := actions_model.InsertTaskOutputIfNotExist(ctx, task.ID, k, v); err != nil {
244				log.Warn("Failed to insert the output %q of task %d: %v", k, task.ID, err)
245				// It's ok not to return errors, the runner will resend the outputs.
246			}
247		}
248		sentOutputs, err := actions_model.FindTaskOutputKeyByTaskID(ctx, task.ID)
249		if err != nil {
250			log.Warn("Failed to find the sent outputs of task %d: %v", task.ID, err)
251			// It's not to return errors, it can be handled when the runner resends sent outputs.
252		}
253	
254		if err := task.LoadJob(ctx); err != nil {
255			return nil, status.Errorf(codes.Internal, "load job: %v", err)
256		}
257		if err := task.Job.LoadAttributes(ctx); err != nil {
258			return nil, status.Errorf(codes.Internal, "load run: %v", err)
259		}
260	
261		actions_service.CreateCommitStatusForRunJobs(ctx, task.Job.Run, task.Job)
262	
263		if task.Status.IsDone() {
264			actions_service.NotifyWorkflowJobStatusUpdateWithTask(ctx, task.Job, task)
265		}
266	
267		if req.Msg.State.Result != runnerv1.Result_RESULT_UNSPECIFIED {
268			if err := actions_service.EmitJobsIfReadyByRun(task.Job.RunID); err != nil {
269				log.Error("Emit ready jobs of run %d: %v", task.Job.RunID, err)
270			}
271			if task.Job.Run.Status.IsDone() {
272				actions_service.NotifyWorkflowRunStatusUpdateWithReload(ctx, task.Job.RepoID, task.Job.RunID)
273			}
274		}
275	
276		return connect.NewResponse(&runnerv1.UpdateTaskResponse{
277			State: &runnerv1.TaskState{
278				Id:     req.Msg.State.Id,
279				Result: task.Status.AsResult(),
280			},
281			SentOutputs: sentOutputs,
282		}), nil
283	}
284	
285	// UpdateLog uploads log of the task.
286	func (s *Service) UpdateLog(
287		ctx context.Context,
288		req *connect.Request[runnerv1.UpdateLogRequest],
289	) (*connect.Response[runnerv1.UpdateLogResponse], error) {
290		runner := GetRunner(ctx)
291	
292		res := connect.NewResponse(&runnerv1.UpdateLogResponse{})
293	
294		task, err := actions_model.GetTaskByID(ctx, req.Msg.TaskId)
295		if err != nil {
296			return nil, status.Errorf(codes.Internal, "get task: %v", err)
297		} else if runner.ID != task.RunnerID {
298			return nil, status.Errorf(codes.Internal, "invalid runner for task")
299		}
300		ack := task.LogLength
301	
302		// Trim rows the runner already had acked.
303		var rows []*runnerv1.LogRow
304		if req.Msg.Index <= ack && int64(len(req.Msg.Rows))+req.Msg.Index > ack {
305			rows = req.Msg.Rows[ack-req.Msg.Index:]
306		}
307	
308		// Ack a re-sent finalize idempotently. Appending new rows past the seal errors.
309		if task.LogInStorage {
310			if len(rows) > 0 {
311				return nil, status.Errorf(codes.AlreadyExists, "log file has been archived")
312			}
313			res.Msg.AckIndex = ack
314			return res, nil
315		}
316	
317		// Bail unless we have new rows or a NoMore to finalize. Even with
318		// NoMore, bail when the runner has outrun the server — archiving a
319		// log with a gap is worse than asking it to retry.
320		if len(rows) == 0 && (!req.Msg.NoMore || req.Msg.Index > ack) {
321			res.Msg.AckIndex = ack
322			return res, nil
323		}
324	
325		// WriteLogs is called even with no rows: with offset==0 it bootstraps
326		// an empty DBFS file so TransferLogs below has something to read when
327		// the runner finalizes a task that produced no log output.
328		ns, err := actions.WriteLogs(ctx, task.LogFilename, task.LogSize, rows)
329		if err != nil {
330			return nil, status.Errorf(codes.Internal, "unable to append logs to dbfs file: %v", err)
331		}
332		task.LogLength += int64(len(rows))
333		for _, n := range ns {
334			task.LogIndexes = append(task.LogIndexes, task.LogSize)
335			task.LogSize += int64(n)
336		}
337	
338		res.Msg.AckIndex = task.LogLength
339	
340		var remove func()
341		if req.Msg.NoMore {
342			task.LogInStorage = true
343			remove, err = actions.TransferLogs(ctx, task.LogFilename)
344			if err != nil {
345				return nil, status.Errorf(codes.Internal, "transfer logs: %v", err)
346			}
347		}
348	
349		if err := actions_model.UpdateTask(ctx, task, "log_indexes", "log_length", "log_size", "log_in_storage"); err != nil {
350			return nil, status.Errorf(codes.Internal, "update task: %v", err)
351		}
352		if remove != nil {
353			remove()
354		}
355	
356		return res, nil
357	}
