211	// FindRunnerOptions
212	// ownerID == 0 and repoID == 0 means any runner including global runners
213	// repoID != 0 and WithAvailable == false means any runner for the given repo
214	// repoID != 0 and WithAvailable == true means any runner for the given repo, parent user/org, and global runners
215	// ownerID != 0 and repoID == 0 and WithAvailable == false means any runner for the given user/org
216	// ownerID != 0 and repoID == 0 and WithAvailable == true means any runner for the given user/org and global runners
217	type FindRunnerOptions struct {
218		db.ListOptions
219		IDs           []int64
220		RepoID        int64
221		OwnerID       int64 // it will be ignored if RepoID is set
222		Sort          string
223		Filter        string
224		IsOnline      optional.Option[bool]
225		IsDisabled    optional.Option[bool]
226		WithAvailable bool // not only runners belong to, but also runners can be used
227	}
228	
229	func (opts FindRunnerOptions) ToConds() builder.Cond {
230		cond := builder.NewCond()
231	
232		if len(opts.IDs) > 0 {
233			if len(opts.IDs) == 1 {
234				cond = cond.And(builder.Eq{"id": opts.IDs[0]})
235			} else {
236				cond = cond.And(builder.In("id", opts.IDs))
237			}
238		}
239	
240		if opts.RepoID > 0 {
241			c := builder.NewCond().And(builder.Eq{"repo_id": opts.RepoID})
242			if opts.WithAvailable {
243				c = c.Or(builder.Eq{"owner_id": builder.Select("owner_id").From("repository").Where(builder.Eq{"id": opts.RepoID})})
244				c = c.Or(builder.Eq{"repo_id": 0, "owner_id": 0})
245			}
246			cond = cond.And(c)
247		} else if opts.OwnerID > 0 { // OwnerID is ignored if RepoID is set
248			c := builder.NewCond().And(builder.Eq{"owner_id": opts.OwnerID})
249			if opts.WithAvailable {
250				c = c.Or(builder.Eq{"repo_id": 0, "owner_id": 0})
251			}
252			cond = cond.And(c)
253		}
254	
255		if opts.Filter != "" {
256			cond = cond.And(builder.Like{"name", opts.Filter})
257		}
258	
259		if opts.IsOnline.Has() {
260			if opts.IsOnline.Value() {
261				cond = cond.And(builder.Gt{"last_online": time.Now().Add(-RunnerOfflineTime).Unix()})
262			} else {
263				cond = cond.And(builder.Lte{"last_online": time.Now().Add(-RunnerOfflineTime).Unix()})
264			}
265		}
266	
267		if opts.IsDisabled.Has() {
268			cond = cond.And(builder.Eq{"is_disabled": opts.IsDisabled.Value()})
269		}
270		return cond
271	}
272	
273	func (opts FindRunnerOptions) ToOrders() string {
274		// A unique tiebreaker (id) is appended so that runners sharing the same
275		// last_online or name keep a deterministic order across paginated queries,
276		// otherwise the same runner may appear on more than one page.
277		switch opts.Sort {
278		case "online":
279			return "last_online DESC, id ASC"
280		case "offline":
281			return "last_online ASC, id ASC"
282		case "alphabetically":
283			return "name ASC, id ASC"
284		case "reversealphabetically":
285			return "name DESC, id ASC"
286		case "newest":
287			return "id DESC"
288		case "oldest":
289			return "id ASC"
290		}
291		return "last_online DESC, id ASC"
292	}
