331	func SetRunnerDisabled(ctx context.Context, runner *ActionRunner, isDisabled bool) error {
332		if runner.IsDisabled == isDisabled {
333			return nil
334		}
335	
336		return db.WithTx(ctx, func(ctx context.Context) error {
337			runner.IsDisabled = isDisabled
338			if err := UpdateRunner(ctx, runner, "is_disabled"); err != nil {
339				return err
340			}
341			return IncreaseTaskVersion(ctx, runner.OwnerID, runner.RepoID)
342		})
343	}
