393	func FixRunnersWithoutBelongingOwner(ctx context.Context) (int64, error) {
394		subQuery := builder.Select("`action_runner`.id").
395			From("`action_runner`").
396			Join("LEFT", "`user`", "`action_runner`.owner_id = `user`.id").
397			Where(builder.Neq{"`action_runner`.owner_id": 0}).
398			And(builder.IsNull{"`user`.id"})
399		b := builder.Delete(builder.In("id", subQuery)).From("`action_runner`")
400		res, err := db.GetEngine(ctx).Exec(b)
401		if err != nil {
402			return 0, err
403		}
404		return res.RowsAffected()
405	}
