140	func (s *Service) Declare(
141		ctx context.Context,
142		req *connect.Request[runnerv1.DeclareRequest],
143	) (*connect.Response[runnerv1.DeclareResponse], error) {
144		runner := GetRunner(ctx)
145		if err := actions_model.UpdateRunner(ctx, runner, applyDeclareRequestToRunner(runner, req.Msg)...); err != nil {
146			return nil, status.Errorf(codes.Internal, "update runner: %v", err)
147		}
148	
149		resp := connect.NewResponse(&runnerv1.DeclareResponse{
150			Runner: &runnerv1.Runner{
151				Id:      runner.ID,
152				Uuid:    runner.UUID,
153				Token:   runner.Token,
154				Name:    runner.Name,
155				Version: runner.Version,
156				Labels:  runner.AgentLabels,
157			},
158		})
159		// Capabilities are communicated via headers to avoid a hard dependency on a proto bump.
160		// Older runners ignore unknown headers; newer runners can use this for feature negotiation.
161		resp.Header().Set("X-Gitea-Actions-Capabilities", actions_model.RunnerCapabilities())
162		return resp, nil
163	}
