4	package runner
5	
6	import (
7		"context"
8		"crypto/subtle"
9		"errors"
10		"strings"
11		"time"
12	
13		actions_model "gitea.dev/models/actions"
14		auth_model "gitea.dev/models/auth"
15		"gitea.dev/modules/log"
16		"gitea.dev/modules/timeutil"
17		"gitea.dev/modules/util"
18	
19		"connectrpc.com/connect"
20		"google.golang.org/grpc/codes"
21		"google.golang.org/grpc/status"
22	)
23	
24	const (
25		uuidHeaderKey  = "x-runner-uuid"
26		tokenHeaderKey = "x-runner-token"
27	)
28	
29	var withRunner = connect.WithInterceptors(connect.UnaryInterceptorFunc(func(unaryFunc connect.UnaryFunc) connect.UnaryFunc {
30		return func(ctx context.Context, request connect.AnyRequest) (connect.AnyResponse, error) {
31			methodName := getMethodName(request)
32			if methodName == "Register" {
33				return unaryFunc(ctx, request)
34			}
35			uuid := request.Header().Get(uuidHeaderKey)
36			token := request.Header().Get(tokenHeaderKey)
37	
38			runner, err := actions_model.GetRunnerByUUID(ctx, uuid)
39			if err != nil {
40				if errors.Is(err, util.ErrNotExist) {
41					return nil, status.Error(codes.Unauthenticated, "unregistered runner")
42				}
43				return nil, status.Error(codes.Internal, err.Error())
44			}
45			if subtle.ConstantTimeCompare([]byte(runner.TokenHash), []byte(auth_model.HashToken(token, runner.TokenSalt))) != 1 {
46				return nil, status.Error(codes.Unauthenticated, "unregistered runner")
47			}
48	
49			now := time.Now()
50			cols := make([]string, 0, 2)
51			// Debounce last_active too: while a runner streams logs, UpdateLog fires
52			// many times per second and writing on each is a major source of DB load.
53			// Persist only when stale enough to affect the active/idle status.
54			if (methodName == "UpdateTask" || methodName == "UpdateLog") &&
55				actions_model.ShouldPersistLastActive(runner.LastActive, now) {
56				runner.LastActive = timeutil.TimeStamp(now.Unix())
57				cols = append(cols, "last_active")
58			}
59			// Debounce last_online: writing on every poll is a major source of DB load
60			// with many runners. Persist only when stale enough to affect offline status.
61			if actions_model.ShouldPersistLastOnline(runner.LastOnline, now) {
62				runner.LastOnline = timeutil.TimeStamp(now.Unix())
63				cols = append(cols, "last_online")
64			}
65			if len(cols) > 0 {
66				if err := actions_model.UpdateRunner(ctx, runner, cols...); err != nil {
67					log.Error("can't update runner status: %v", err)
68				}
69			}
70	
71			ctx = context.WithValue(ctx, runnerCtxKey{}, runner)
72			return unaryFunc(ctx, request)
73		}
74	}))
75	
76	func getMethodName(req connect.AnyRequest) string {
77		splits := strings.Split(req.Spec().Procedure, "/")
78		if len(splits) > 0 {
79			return splits[len(splits)-1]
80		}
81		return ""
82	}
83	
84	type runnerCtxKey struct{}
85	
86	func GetRunner(ctx context.Context) *actions_model.ActionRunner {
87		if v := ctx.Value(runnerCtxKey{}); v != nil {
88			if r, ok := v.(*actions_model.ActionRunner); ok {
89				return r
90			}
91		}
92		return nil
93	}
