9		"fmt"
10		"sync"
11		"time"
12	
13		runnerv1 "gitea.dev/actions-proto-go/runner/v1"
14		actions_model "gitea.dev/models/actions"
15		"gitea.dev/models/db"
16		secret_model "gitea.dev/models/secret"
17		"gitea.dev/modules/graceful"
18		"gitea.dev/modules/log"
19		"gitea.dev/modules/setting"
20	
21		"google.golang.org/protobuf/types/known/structpb"
22	)
23	
24	var (
25		taskPickSem     chan struct{}
26		taskPickSemOnce sync.Once
27	)
28	
29	func taskPickLimiter() chan struct{} {
30		taskPickSemOnce.Do(func() {
31			taskPickSem = make(chan struct{}, setting.Actions.MaxConcurrentTaskPicks)
32		})
33		return taskPickSem
34	}
35	
36	// TryPickTask attempts to assign a task to the runner, bounding the number of
37	// concurrent assignment transactions to avoid a thundering herd when many
38	// runners poll at once. When the concurrency limit is reached it returns
39	// throttled=true without touching the DB, so the caller can let the runner
40	// retry on its next poll instead of advancing its tasks version.
41	func TryPickTask(ctx context.Context, runner *actions_model.ActionRunner) (task *runnerv1.Task, ok, throttled bool, err error) {
42		sem := taskPickLimiter()
43		select {
44		case sem <- struct{}{}:
45			defer func() { <-sem }()
46		default:
47			return nil, false, true, nil
48		}
49		task, ok, err = PickTask(ctx, runner)
50		return task, ok, false, err
51	}
52	
53	// releaseTaskForRunnerCleanup releases a claimed task using a fresh, bounded context. The request context
54	// is typically already canceled when we reach the release paths below, and a DB transaction on a canceled
55	// context fails immediately, which would strand the claimed job in running state.
56	func releaseTaskForRunnerCleanup(t *actions_model.ActionTask) {
57		ctx, cancel := context.WithTimeout(graceful.GetManager().ShutdownContext(), 10*time.Second)
58		defer cancel()
59		if relErr := actions_model.ReleaseTaskForRunner(ctx, t); relErr != nil {
60			log.Error("ReleaseTaskForRunner [task_id: %d]: %v", t.ID, relErr)
61		}
62	}
63	
64	func PickTask(ctx context.Context, runner *actions_model.ActionRunner) (*runnerv1.Task, bool, error) {
65		var (
66			task       *runnerv1.Task
67			job        *actions_model.ActionRunJob
68			actionTask *actions_model.ActionTask
69		)
70	
71		if runner.IsDisabled {
72			return nil, false, nil
73		}
74	
75		if runner.Ephemeral {
76			var task actions_model.ActionTask
77			has, err := db.GetEngine(ctx).Where("runner_id = ?", runner.ID).Get(&task)
78			// Let the runner retry the request, do not allow to proceed
79			if err != nil {
80				return nil, false, err
81			}
82			if has {
83				if task.Status.In(actions_model.StatusWaiting, actions_model.StatusRunning, actions_model.StatusBlocked, actions_model.StatusCancelling) {
84					return nil, false, nil
85				}
86				// task has been finished, remove it
87				_, err = db.DeleteByID[actions_model.ActionRunner](ctx, runner.ID)
88				if err != nil {
89					return nil, false, err
90				}
91				return nil, false, errors.New("runner has been removed")
92			}
93		}
94	
95		t, ok, err := actions_model.CreateTaskForRunner(ctx, runner)
96		if err != nil {
97			return nil, false, fmt.Errorf("CreateTaskForRunner: %w", err)
98		}
99		if !ok {
100			return nil, false, nil
101		}
102	
103		task, job, err = buildRunnerTask(ctx, t)
104		if err != nil {
105			// The job was already claimed but assembling its payload failed; release the
106			// claim so the job returns to the waiting queue instead of being stranded in
107			// running state with no runner ever executing it.
108			releaseTaskForRunnerCleanup(t)
109			return nil, false, err
110		}
111		actionTask = t
112	
113		CreateCommitStatusForRunJobs(ctx, job.Run, job)
114		NotifyWorkflowJobStatusUpdateWithTask(ctx, job, actionTask)
115		// job.Run is loaded inside the transaction before UpdateRunJob sets run.Started,
116		// so Started is zero only on the very first pick-up of that run.
117		if job.Run.Started.IsZero() {
118			NotifyWorkflowRunStatusUpdateWithReload(ctx, job.RepoID, job.RunID)
119		}
120	
121		// The job is claimed and its payload assembled, but if the request context was cancelled meanwhile, response can no longer reach the runner.
122		// Release the claim so another runner can pick the job up.
123		if err := ctx.Err(); err != nil {
124			releaseTaskForRunnerCleanup(t)
125			return nil, false, err
126		}
127	
128		return task, true, nil
129	}
130	
131	// buildRunnerTask assembles the runner-facing task payload for an already-claimed
132	// task. All operations are read-only; on error the caller releases the claim.
133	func buildRunnerTask(ctx context.Context, t *actions_model.ActionTask) (*runnerv1.Task, *actions_model.ActionRunJob, error) {
134		if err := t.LoadAttributes(ctx); err != nil {
135			return nil, nil, fmt.Errorf("task LoadAttributes: %w", err)
136		}
137		job := t.Job
138	
139		secrets, err := secret_model.GetSecretsOfTask(ctx, t)
140		if err != nil {
141			return nil, nil, fmt.Errorf("GetSecretsOfTask: %w", err)
142		}
143	
144		vars, err := actions_model.GetVariablesOfRun(ctx, t.Job.Run)
145		if err != nil {
146			return nil, nil, fmt.Errorf("GetVariablesOfRun: %w", err)
147		}
148	
149		needs, err := findTaskNeeds(ctx, job)
150		if err != nil {
151			return nil, nil, fmt.Errorf("findTaskNeeds: %w", err)
152		}
153	
154		taskContext, err := generateTaskContext(ctx, t)
155		if err != nil {
156			return nil, nil, fmt.Errorf("generateTaskContext: %w", err)
157		}
158	
159		return &runnerv1.Task{
160			Id:              t.ID,
161			WorkflowPayload: t.Job.WorkflowPayload,
162			Context:         taskContext,
163			Secrets:         secrets,
164			Vars:            vars,
165			Needs:           needs,
166		}, job, nil
167	}
168	
169	func generateTaskContext(ctx context.Context, t *actions_model.ActionTask) (*structpb.Struct, error) {
170		giteaRuntimeToken, err := CreateAuthorizationToken(t.ID, t.Job.RunID, t.JobID)
171		if err != nil {
172			return nil, err
173		}
174	
175		gitCtx := GenerateGiteaContext(ctx, t.Job.Run, nil, t.Job)
176		gitCtx["token"] = t.Token
177		gitCtx["gitea_runtime_token"] = giteaRuntimeToken
178	
179		return structpb.NewStruct(gitCtx)
180	}
181	
182	func findTaskNeeds(ctx context.Context, taskJob *actions_model.ActionRunJob) (map[string]*runnerv1.TaskNeed, error) {
183		taskNeeds, err := FindTaskNeeds(ctx, taskJob)
184		if err != nil {
185			return nil, err
186		}
187		ret := make(map[string]*runnerv1.TaskNeed, len(taskNeeds))
188		for jobID, taskNeed := range taskNeeds {
189			ret[jobID] = &runnerv1.TaskNeed{
190				Outputs: taskNeed.Outputs,
191				Result:  runnerv1.Result(taskNeed.Result),
192			}
193		}
194		return ret, nil
195	}
