4	package actions
5	
6	import (
7		"context"
8		"errors"
9		"fmt"
10	
11		actions_model "gitea.dev/models/actions"
12		"gitea.dev/models/db"
13		"gitea.dev/modules/container"
14		"gitea.dev/modules/graceful"
15		"gitea.dev/modules/log"
16		"gitea.dev/modules/queue"
17		"gitea.dev/modules/setting"
18		"gitea.dev/modules/util"
19	
20		"xorm.io/builder"
21	)
22	
23	var jobEmitterQueue *queue.WorkerPoolQueue[*jobUpdate]
24	
25	type jobUpdate struct {
26		RunID int64
27	}
28	
29	func EmitJobsIfReadyByRun(runID int64) error {
30		err := jobEmitterQueue.Push(&jobUpdate{
31			RunID: runID,
32		})
33		if errors.Is(err, queue.ErrAlreadyInQueue) {
34			return nil
35		}
36		return err
37	}
38	
39	func EmitJobsIfReadyByJobs(jobs []*actions_model.ActionRunJob) {
40		checkedRuns := make(container.Set[int64])
41		for _, job := range jobs {
42			if !job.Status.IsDone() || checkedRuns.Contains(job.RunID) {
43				continue
44			}
45			if err := EmitJobsIfReadyByRun(job.RunID); err != nil {
46				log.Error("Check jobs of run %d: %v", job.RunID, err)
47			}
48			checkedRuns.Add(job.RunID)
49		}
50	}
51	
52	func jobEmitterQueueHandler(items ...*jobUpdate) []*jobUpdate {
53		ctx := graceful.GetManager().ShutdownContext()
54		var ret []*jobUpdate
55		for _, update := range items {
56			if err := checkJobsByRunID(ctx, update.RunID); err != nil {
57				log.Error("check run %d: %v", update.RunID, err)
58				ret = append(ret, update)
59			}
60		}
61		return ret
62	}
63	
64	func checkJobsByRunID(ctx context.Context, runID int64) error {
65		run, exist, err := db.GetByID[actions_model.ActionRun](ctx, runID)
66		if !exist {
67			return fmt.Errorf("run %d does not exist", runID)
68		}
69		if err != nil {
70			return fmt.Errorf("get action run: %w", err)
71		}
72		var result jobsCheckResult
73		if err := db.WithTx(ctx, func(ctx context.Context) error {
74			// check jobs of the current run
75			r, err := checkJobsOfCurrentRunAttempt(ctx, run)
76			if err != nil {
77				return err
78			}
79			result.merge(r)
80	
81			r, err = checkRunConcurrency(ctx, run)
82			if err != nil {
83				return err
84			}
85			result.merge(r)
86			return nil
87		}); err != nil {
88			return err
89		}
90		// Re-emit AFTER the transaction commits; doing this inside WithTx would deadlock under
91		// immediate-mode queues (the inline handler reopens checkJobsByRunID and asks for a
92		// nested writer transaction while the outer one is still open).
93		emitted := make(container.Set[int64])
94		for _, rid := range result.RunIDsToReEmit {
95			if !emitted.Add(rid) {
96				continue
97			}
98			if err := EmitJobsIfReadyByRun(rid); err != nil {
99				log.Error("re-emit run %d after caller expansion: %v", rid, err)
100			}
101		}
102		NotifyWorkflowJobsAndRunsStatusUpdate(ctx, result.CancelledJobs)
103		EmitJobsIfReadyByJobs(result.CancelledJobs)
104		if err := createCommitStatusesForJobsByRun(ctx, result.Jobs); err != nil {
105			return err
106		}
107		NotifyWorkflowJobsStatusUpdate(ctx, result.UpdatedJobs...)
108		runJobs := make(map[int64][]*actions_model.ActionRunJob)
109		for _, job := range result.Jobs {
110			runJobs[job.RunID] = append(runJobs[job.RunID], job)
111		}
112		runUpdatedJobs := make(map[int64][]*actions_model.ActionRunJob)
113		for _, uj := range result.UpdatedJobs {
114			runUpdatedJobs[uj.RunID] = append(runUpdatedJobs[uj.RunID], uj)
115		}
116		for runID, js := range runJobs {
117			if len(runUpdatedJobs[runID]) == 0 {
118				continue
119			}
120			runUpdated := true
121			for _, job := range js {
122				if !job.Status.IsDone() {
123					runUpdated = false
124					break
125				}
126			}
127			if runUpdated {
128				NotifyWorkflowRunStatusUpdateWithReload(ctx, js[0].RepoID, js[0].RunID)
129			}
130		}
131		return nil
132	}
133	
134	func createCommitStatusesForJobsByRun(ctx context.Context, jobs []*actions_model.ActionRunJob) error {
135		runJobs := make(map[int64][]*actions_model.ActionRunJob)
136		for _, job := range jobs {
137			runJobs[job.RunID] = append(runJobs[job.RunID], job)
138		}
139	
140		for jobRunID, jobList := range runJobs {
141			run, err := actions_model.GetRunByRepoAndID(ctx, jobList[0].RepoID, jobRunID)
142			if err != nil {
143				return fmt.Errorf("get action run %d: %w", jobRunID, err)
144			}
145			CreateCommitStatusForRunJobs(ctx, run, jobList...)
146		}
147		return nil
148	}
149	
150	// findBlockedRunIDByConcurrency finds a blocked concurrent run in a repo and returns 0 when there is no blocked run.
151	func findBlockedRunIDByConcurrency(ctx context.Context, repoID int64, concurrencyGroup string) (int64, error) {
152		if concurrencyGroup == "" {
153			return 0, nil
154		}
155		cAttempts, cJobs, err := actions_model.GetConcurrentRunAttemptsAndJobs(ctx, repoID, concurrencyGroup, []actions_model.Status{actions_model.StatusBlocked})
156		if err != nil {
157			return 0, fmt.Errorf("find concurrent runs and jobs: %w", err)
158		}
159	
160		if len(cAttempts) > 0 {
161			return cAttempts[0].RunID, nil
162		}
163		if len(cJobs) > 0 {
164			return cJobs[0].RunID, nil
165		}
166	
167		return 0, nil
168	}
169	
170	func checkBlockedConcurrentRun(ctx context.Context, repoID, runID int64) (*jobsCheckResult, error) {
171		concurrentRun, err := actions_model.GetRunByRepoAndID(ctx, repoID, runID)
172		if err != nil {
173			return nil, fmt.Errorf("get run %d: %w", runID, err)
174		}
175		if concurrentRun.NeedApproval {
176			return &jobsCheckResult{}, nil
177		}
178	
179		return checkJobsOfCurrentRunAttempt(ctx, concurrentRun)
180	}
181	
182	// checkRunConcurrency rechecks runs blocked by concurrency that may become unblocked after the current run releases a workflow-level or job-level concurrency group.
183	// RunIDsToReEmit propagates from inner checkJobsOfCurrentRunAttempt calls; see that function's doc.
184	func checkRunConcurrency(ctx context.Context, run *actions_model.ActionRun) (*jobsCheckResult, error) {
185		result := &jobsCheckResult{}
186		checkedConcurrencyGroup := make(container.Set[string])
187	
188		collect := func(concurrencyGroup string) error {
189			concurrentRunID, err := findBlockedRunIDByConcurrency(ctx, run.RepoID, concurrencyGroup)
190			if err != nil {
191				return fmt.Errorf("find blocked run by concurrency: %w", err)
192			}
193			if concurrentRunID > 0 {
194				r, err := checkBlockedConcurrentRun(ctx, run.RepoID, concurrentRunID)
195				if err != nil {
196					return err
197				}
198				result.merge(r)
199			}
200			checkedConcurrencyGroup.Add(concurrencyGroup)
201			return nil
202		}
203	
204		// check run (workflow-level) concurrency
205		runConcurrencyGroup, _, err := run.GetEffectiveConcurrency(ctx)
206		if err != nil {
207			return nil, fmt.Errorf("GetEffectiveConcurrency: %w", err)
208		}
209		if runConcurrencyGroup != "" {
210			if err := collect(runConcurrencyGroup); err != nil {
211				return nil, err
212			}
213		}
214	
215		// check job concurrency
216		runJobs, err := actions_model.GetLatestAttemptJobsByRepoAndRunID(ctx, run.RepoID, run.ID)
217		if err != nil {
218			return nil, fmt.Errorf("find run %d jobs: %w", run.ID, err)
219		}
220		for _, job := range runJobs {
221			if !job.Status.IsDone() {
222				continue
223			}
224			if job.ConcurrencyGroup == "" || checkedConcurrencyGroup.Contains(job.ConcurrencyGroup) {
225				continue
226			}
227			if err := collect(job.ConcurrencyGroup); err != nil {
228				return nil, err
229			}
230		}
231		return result, nil
232	}
233	
234	// checkJobsOfCurrentRunAttempt resolves blocked jobs of the run's latest attempt.
235	func checkJobsOfCurrentRunAttempt(ctx context.Context, run *actions_model.ActionRun) (*jobsCheckResult, error) {
236		jobs, err := actions_model.GetRunJobsByRunAndAttemptID(ctx, run.ID, run.LatestAttemptID)
237		if err != nil {
238			return nil, err
239		}
240		result := &jobsCheckResult{Jobs: jobs}
241	
242		var attempt *actions_model.ActionRunAttempt
243		if run.LatestAttemptID > 0 {
244			attempt, err = actions_model.GetRunAttemptByRepoAndID(ctx, run.RepoID, run.LatestAttemptID)
245			if err != nil {
246				return nil, err
247			}
248		}
249	
250		// The resolver below only considers needs and job-level concurrency, so a run blocked
251		// solely by run-level concurrency would have its jobs unblocked here. checkRunConcurrency
252		// re-evaluates when the holding run finishes.
253		if run.Status.IsBlocked() && attempt != nil {
254			shouldBlock, err := shouldBlockRunByConcurrency(ctx, attempt)
255			if err != nil {
256				return nil, fmt.Errorf("shouldBlockRunByConcurrency: %w", err)
257			}
258			if shouldBlock {
259				return result, nil
260			}
261		}
262		vars, err := actions_model.GetVariablesOfRun(ctx, run)
263		if err != nil {
264			return nil, err
265		}
266		resolver := newJobStatusResolver(jobs, vars)
267	
268		expandedAnyCaller := false
269		if err = db.WithTx(ctx, func(ctx context.Context) error {
270			for _, job := range jobs {
271				job.Run = run
272			}
273	
274			updates := resolver.Resolve(ctx)
275			for _, job := range jobs {
276				status, ok := updates[job.ID]
277				if !ok {
278					continue
279				}
280	
281				if job.IsReusableCaller {
282					switch status {
283					case actions_model.StatusWaiting:
284						if err := expandReusableWorkflowCaller(ctx, run, attempt, job, vars); err != nil {
285							return fmt.Errorf("trigger caller-ready %d: %w", job.ID, err)
286						}
287						// expandReusableWorkflowCaller inserts children as Blocked. They need a follow-up resolver pass.
288						expandedAnyCaller = true
289					case actions_model.StatusSkipped:
290						job.Status = actions_model.StatusSkipped
291						if _, err := actions_model.UpdateRunJob(ctx, job, nil, "status"); err != nil {
292							return err
293						}
294					}
295					continue
296				}
297	
298				// Non-caller: standard status update.
299				job.Status = status
300				if n, err := actions_model.UpdateRunJob(ctx, job, builder.Eq{"status": actions_model.StatusBlocked}, "status"); err != nil {
301					return err
302				} else if n != 1 {
303					return fmt.Errorf("no affected for updating blocked job %v", job.ID)
304				}
305				result.UpdatedJobs = append(result.UpdatedJobs, job)
306			}
307			return nil
308		}); err != nil {
309			return nil, err
310		}
311	
312		if expandedAnyCaller {
313			result.RunIDsToReEmit = append(result.RunIDsToReEmit, run.ID)
314		}
315		result.CancelledJobs = resolver.cancelledJobs
316		return result, nil
317	}
318	
319	type jobStatusResolver struct {
320		statuses      map[int64]actions_model.Status
321		needs         map[int64][]int64
322		jobMap        map[int64]*actions_model.ActionRunJob
323		vars          map[string]string
324		cancelledJobs []*actions_model.ActionRunJob
325	}
326	
327	func newJobStatusResolver(jobs actions_model.ActionJobList, vars map[string]string) *jobStatusResolver {
328		// Scope-aware: needs are resolved within the same ParentJobID scope so the same
329		// JobID in different reusable workflow calls does not cross-link.
330		scopedIDToJobs := make(map[int64]map[string][]*actions_model.ActionRunJob)
331		jobMap := make(map[int64]*actions_model.ActionRunJob)
332		for _, job := range jobs {
333			scope := scopedIDToJobs[job.ParentJobID]
334			if scope == nil {
335				scope = make(map[string][]*actions_model.ActionRunJob)
336				scopedIDToJobs[job.ParentJobID] = scope
337			}
338			scope[job.JobID] = append(scope[job.JobID], job)
339			jobMap[job.ID] = job
340		}
341	
342		statuses := make(map[int64]actions_model.Status, len(jobs))
343		needs := make(map[int64][]int64, len(jobs))
344		for _, job := range jobs {
345			statuses[job.ID] = job.Status
346			scope := scopedIDToJobs[job.ParentJobID]
347			for _, need := range job.Needs {
348				for _, v := range scope[need] {
349					needs[job.ID] = append(needs[job.ID], v.ID)
350				}
351			}
352		}
353		return &jobStatusResolver{
354			statuses: statuses,
355			needs:    needs,
356			jobMap:   jobMap,
357			vars:     vars,
358		}
359	}
360	
361	func (r *jobStatusResolver) Resolve(ctx context.Context) map[int64]actions_model.Status {
362		ret := map[int64]actions_model.Status{}
363		for i := 0; i < len(r.statuses); i++ {
364			updated := r.resolve(ctx)
365			if len(updated) == 0 {
366				return ret
367			}
368			for k, v := range updated {
369				ret[k] = v
370				r.statuses[k] = v
371			}
372		}
373		return ret
374	}
375	
376	func (r *jobStatusResolver) resolveCheckNeeds(id int64) (allDone, allSucceed bool) {
377		allDone, allSucceed = true, true
378		for _, need := range r.needs[id] {
379			needStatus := r.statuses[need]
380			if !needStatus.IsDone() {
381				allDone = false
382			}
383			// A failed need with continue-on-error:true is treated as success, matching AggregateJobStatus,
384			// so a downstream job with an implicit `success()` is not skipped.
385			if needJob := r.jobMap[need]; needJob != nil && needJob.ContinueOnError && needStatus == actions_model.StatusFailure {
386				continue
387			}
388			if needStatus.In(actions_model.StatusFailure, actions_model.StatusCancelled, actions_model.StatusSkipped) {
389				allSucceed = false
390			}
391		}
392		return allDone, allSucceed
393	}
394	
395	func (r *jobStatusResolver) resolve(ctx context.Context) map[int64]actions_model.Status {
396		ret := map[int64]actions_model.Status{}
397		for id, status := range r.statuses {
398			actionRunJob := r.jobMap[id]
399			if status != actions_model.StatusBlocked {
400				continue
401			}
402			// A child of a caller cannot start until the caller has become "ready" (children inserted, CallPayload populated).
403			if actionRunJob.ParentJobID > 0 {
404				if parent, ok := r.jobMap[actionRunJob.ParentJobID]; ok && !parent.IsExpanded {
405					continue
406				}
407			}
408			allDone, allSucceed := r.resolveCheckNeeds(id)
409			if !allDone {
410				continue
411			}
412	
413			// update concurrency and check whether the job can run now
414			err := updateConcurrencyEvaluationForJobWithNeeds(ctx, actionRunJob, r.vars)
415			if err != nil {
416				// The err can be caused by different cases: database error, or syntax error, or the needed jobs haven't completed
417				// At the moment there is no way to distinguish them.
418				// TODO: if workflow or concurrency expression has syntax error, there should be a user error message, need to show it to end users
419				log.Debug("updateConcurrencyEvaluationForJobWithNeeds failed, this job will stay blocked: job: %d, err: %v", id, err)
420				continue
421			}
422	
423			shouldStartJob, err := evaluateJobIf(ctx, actionRunJob.Run, nil, actionRunJob, r.vars, allSucceed)
424			if err != nil {
425				// TODO: surface deterministic expression errors to users by failing the job with a message.
426				log.Error("evaluateJobIf failed, job will stay blocked: job: %d, err: %v", id, err)
427				continue
428			}
429	
430			newStatus := util.Iif(shouldStartJob, actions_model.StatusWaiting, actions_model.StatusSkipped)
431			if newStatus == actions_model.StatusWaiting {
432				var cancelledJobs []*actions_model.ActionRunJob
433				newStatus, cancelledJobs, err = PrepareToStartJobWithConcurrency(ctx, actionRunJob)
434				if err != nil {
435					log.Error("ShouldBlockJobByConcurrency failed, this job will stay blocked: job: %d, err: %v", id, err)
436				} else {
437					r.cancelledJobs = append(r.cancelledJobs, cancelledJobs...)
438				}
439			}
440	
441			if newStatus != actions_model.StatusBlocked {
442				ret[id] = newStatus
443			}
444		}
445		return ret
446	}
447	
448	func updateConcurrencyEvaluationForJobWithNeeds(ctx context.Context, actionRunJob *actions_model.ActionRunJob, vars map[string]string) error {
449		if setting.IsInTesting && actionRunJob.RepoID == 0 {
450			return nil // for testing purpose only, no repo, no evaluation
451		}
452	
453		// Legacy jobs (created before migration v331) have RunAttemptID=0 and no attempt record.
454		var attempt *actions_model.ActionRunAttempt
455		if actionRunJob.RunAttemptID > 0 {
456			var err error
457			attempt, err = actions_model.GetRunAttemptByRepoAndID(ctx, actionRunJob.RepoID, actionRunJob.RunAttemptID)
458			if err != nil {
459				return fmt.Errorf("GetRunAttemptByRepoAndID: %w", err)
460			}
461		}
462		if err := EvaluateJobConcurrencyFillModel(ctx, actionRunJob.Run, attempt, actionRunJob, vars, nil); err != nil {
463			return fmt.Errorf("evaluate job concurrency: %w", err)
464		}
465	
466		if _, err := actions_model.UpdateRunJob(ctx, actionRunJob, nil, "concurrency_group", "concurrency_cancel", "is_concurrency_evaluated"); err != nil {
467			return fmt.Errorf("update run job: %w", err)
468		}
469		return nil
470	}
471	
472	// jobsCheckResult bundles the output of the per-run job-check helpers.
473	type jobsCheckResult struct {
474		// Jobs are all jobs of the run's latest attempt that were inspected.
475		Jobs []*actions_model.ActionRunJob
476		// UpdatedJobs are jobs whose status was transitioned out of Blocked in this pass.
477		UpdatedJobs []*actions_model.ActionRunJob
478		// CancelledJobs are jobs cancelled by job-level concurrency while preparing to start.
479		CancelledJobs []*actions_model.ActionRunJob
480		// RunIDsToReEmit are runs whose newly expanded reusable workflow callers need another resolver pass.
481		RunIDsToReEmit []int64
482	}
483	
484	// merge appends another result's contents into r in place.
485	func (r *jobsCheckResult) merge(other *jobsCheckResult) {
486		r.Jobs = append(r.Jobs, other.Jobs...)
487		r.UpdatedJobs = append(r.UpdatedJobs, other.UpdatedJobs...)
488		r.CancelledJobs = append(r.CancelledJobs, other.CancelledJobs...)
489		r.RunIDsToReEmit = append(r.RunIDsToReEmit, other.RunIDsToReEmit...)
490	}
