17	// EvaluateRunConcurrencyFillModel evaluates the expressions in a run-level (workflow) concurrency,
18	// and fills the run attempt model with the evaluated `concurrency.group` and `concurrency.cancel-in-progress` values.
19	// Workflow-level concurrency doesn't depend on the job outputs, so it can always be evaluated if there is no syntax error.
20	// See https://docs.github.com/en/actions/reference/workflows-and-actions/workflow-syntax#concurrency
21	func EvaluateRunConcurrencyFillModel(ctx context.Context, run *actions_model.ActionRun, attempt *actions_model.ActionRunAttempt, wfRawConcurrency *act_model.RawConcurrency, vars map[string]string, inputs map[string]any) error {
22		if err := run.LoadAttributes(ctx); err != nil {
23			return fmt.Errorf("run LoadAttributes: %w", err)
24		}
25	
26		actionsRunCtx := GenerateGiteaContext(ctx, run, attempt, nil)
27		jobResults := map[string]*jobparser.JobResult{"": {}}
28		if inputs == nil {
29			var err error
30			inputs, err = getWorkflowDispatchInputsFromRun(run)
31			if err != nil {
32				return fmt.Errorf("get inputs: %w", err)
33			}
34		}
35	
36		var err error
37		attempt.ConcurrencyGroup, attempt.ConcurrencyCancel, err = jobparser.EvaluateConcurrency(wfRawConcurrency, "", nil, actionsRunCtx, jobResults, vars, inputs)
38		if err != nil {
39			return fmt.Errorf("evaluate concurrency: %w", err)
40		}
41		return nil
42	}
43	
44	// EvaluateJobConcurrencyFillModel evaluates the expressions in a job-level concurrency,
45	// and fills the job's model fields with `concurrency.group` and `concurrency.cancel-in-progress`.
46	// Job-level concurrency may depend on other job's outputs (via `needs`): `concurrency.group: my-group-${{ needs.job1.outputs.out1 }}`
47	// If the needed jobs haven't been executed yet, this evaluation will also fail.
48	// See https://docs.github.com/en/actions/reference/workflows-and-actions/workflow-syntax#jobsjob_idconcurrency
49	func EvaluateJobConcurrencyFillModel(ctx context.Context, run *actions_model.ActionRun, attempt *actions_model.ActionRunAttempt, actionRunJob *actions_model.ActionRunJob, vars map[string]string, inputs map[string]any) error {
50		if err := actionRunJob.LoadAttributes(ctx); err != nil {
51			return fmt.Errorf("job LoadAttributes: %w", err)
52		}
53	
54		var rawConcurrency act_model.RawConcurrency
55		if err := yaml.Unmarshal([]byte(actionRunJob.RawConcurrency), &rawConcurrency); err != nil {
56			return fmt.Errorf("unmarshal raw concurrency: %w", err)
57		}
58	
59		actionsJobCtx := GenerateGiteaContext(ctx, run, attempt, actionRunJob)
60	
61		jobResults, err := findJobNeedsAndFillJobResults(ctx, actionRunJob)
62		if err != nil {
63			return fmt.Errorf("find job needs and fill job results: %w", err)
64		}
65	
66		if inputs == nil {
67			var err error
68			inputs, err = getInputsForJob(ctx, run, actionRunJob)
69			if err != nil {
70				return fmt.Errorf("get inputs: %w", err)
71			}
72		}
73	
74		workflowJob, err := actionRunJob.ParseJob()
75		if err != nil {
76			return fmt.Errorf("load job %d: %w", actionRunJob.ID, err)
77		}
78	
79		actionRunJob.ConcurrencyGroup, actionRunJob.ConcurrencyCancel, err = jobparser.EvaluateConcurrency(&rawConcurrency, actionRunJob.JobID, workflowJob, actionsJobCtx, jobResults, vars, inputs)
80		if err != nil {
81			return fmt.Errorf("evaluate concurrency: %w", err)
82		}
83		actionRunJob.IsConcurrencyEvaluated = true
84		return nil
85	}
