29	func EmitJobsIfReadyByRun(runID int64) error {
30		err := jobEmitterQueue.Push(&jobUpdate{
31			RunID: runID,
32		})
33		if errors.Is(err, queue.ErrAlreadyInQueue) {
34			return nil
35		}
36		return err
37	}
