62	func shouldBlockJobByConcurrency(ctx context.Context, job *actions_model.ActionRunJob) (bool, error) {
63		if job.RawConcurrency != "" && !job.IsConcurrencyEvaluated {
64			// when the job depends on other jobs, we cannot evaluate its concurrency, so it should be blocked and will be evaluated again when its dependencies are done
65			return true, nil
66		}
67	
68		if job.ConcurrencyGroup == "" || job.ConcurrencyCancel {
69			return false, nil
70		}
71	
72		attempts, jobs, err := actions_model.GetConcurrentRunAttemptsAndJobs(ctx, job.RepoID, job.ConcurrencyGroup, []actions_model.Status{actions_model.StatusRunning, actions_model.StatusCancelling})
73		if err != nil {
74			return false, fmt.Errorf("GetConcurrentRunAttemptsAndJobs: %w", err)
75		}
76	
77		return len(attempts) > 0 || len(jobs) > 0, nil
78	}
79	
80	// PrepareToStartJobWithConcurrency prepares a job to start by its evaluated concurrency group and cancelling previous jobs if necessary.
81	// It returns the new status of the job (either StatusBlocked or StatusWaiting), any cancelled jobs, and any error encountered during the process.
82	func PrepareToStartJobWithConcurrency(ctx context.Context, job *actions_model.ActionRunJob) (actions_model.Status, []*actions_model.ActionRunJob, error) {
83		shouldBlock, err := shouldBlockJobByConcurrency(ctx, job)
84		if err != nil {
85			return actions_model.StatusBlocked, nil, err
86		}
87	
88		// even if the current job is blocked, we still need to cancel previous "waiting/blocked" jobs in the same concurrency group
89		jobs, err := actions_model.CancelPreviousJobsByJobConcurrency(ctx, job)
90		if err != nil {
91			return actions_model.StatusBlocked, nil, fmt.Errorf("CancelPreviousJobsByJobConcurrency: %w", err)
92		}
93	
94		return util.Iif(shouldBlock, actions_model.StatusBlocked, actions_model.StatusWaiting), jobs, nil
95	}
96	
97	func shouldBlockRunByConcurrency(ctx context.Context, attempt *actions_model.ActionRunAttempt) (bool, error) {
98		if attempt.ConcurrencyGroup == "" || attempt.ConcurrencyCancel {
99			return false, nil
100		}
101	
102		attempts, jobs, err := actions_model.GetConcurrentRunAttemptsAndJobs(ctx, attempt.RepoID, attempt.ConcurrencyGroup, []actions_model.Status{actions_model.StatusRunning, actions_model.StatusCancelling})
103		if err != nil {
104			return false, fmt.Errorf("find concurrent runs and jobs: %w", err)
105		}
106	
107		return len(attempts) > 0 || len(jobs) > 0, nil
108	}
109	
110	// PrepareToStartRunWithConcurrency prepares a run attempt to start by its evaluated concurrency group and cancelling previous jobs if necessary.
111	// It returns the new status of the run attempt (either StatusBlocked or StatusWaiting), any cancelled jobs, and any error encountered during the process.
112	func PrepareToStartRunWithConcurrency(ctx context.Context, attempt *actions_model.ActionRunAttempt) (actions_model.Status, []*actions_model.ActionRunJob, error) {
113		shouldBlock, err := shouldBlockRunByConcurrency(ctx, attempt)
114		if err != nil {
115			return actions_model.StatusBlocked, nil, err
116		}
117	
118		// even if the current run is blocked, we still need to cancel previous "waiting/blocked" jobs in the same concurrency group
119		jobs, err := actions_model.CancelPreviousJobsByRunConcurrency(ctx, attempt)
120		if err != nil {
121			return actions_model.StatusBlocked, nil, fmt.Errorf("CancelPreviousJobsByRunConcurrency: %w", err)
122		}
123	
124		return util.Iif(shouldBlock, actions_model.StatusBlocked, actions_model.StatusWaiting), jobs, nil
125	}
126	
127	func stopTasks(ctx context.Context, opts actions_model.FindTaskOptions) error {
128		tasks, err := db.Find[actions_model.ActionTask](ctx, opts)
129		if err != nil {
130			return fmt.Errorf("find tasks: %w", err)
131		}
132	
133		jobs := make([]*actions_model.ActionRunJob, 0, len(tasks))
134		for _, task := range tasks {
135			if err := db.WithTx(ctx, func(ctx context.Context) error {
136				stopStatus := actions_model.StatusFailure
137				if task.Status == actions_model.StatusCancelling {
138					stopStatus = actions_model.StatusCancelled
139				}
140				if err := actions_model.StopTask(ctx, task.ID, stopStatus); err != nil {
141					return err
142				}
143				if err := task.LoadJob(ctx); err != nil {
144					return err
145				}
146				jobs = append(jobs, task.Job)
147				return nil
148			}); err != nil {
149				log.Warn("Cannot stop task %v: %v", task.ID, err)
150				continue
151			}
152	
153			remove, err := actions.TransferLogs(ctx, task.LogFilename)
154			if err != nil {
155				log.Warn("Cannot transfer logs of task %v: %v", task.ID, err)
156				continue
157			}
158			task.LogInStorage = true
159			if err := actions_model.UpdateTask(ctx, task, "log_in_storage"); err != nil {
160				log.Warn("Cannot update task %v: %v", task.ID, err)
161				continue
162			}
163			remove()
164		}
165	
166		NotifyWorkflowJobsAndRunsStatusUpdate(ctx, jobs)
167		EmitJobsIfReadyByJobs(jobs)
168	
169		return nil
170	}
171	
172	// CancelAbandonedJobs cancels jobs that have not been picked by any runner for a long time
173	func CancelAbandonedJobs(ctx context.Context) error {
174		abandonedJobs, err := db.Find[actions_model.ActionRunJob](ctx, actions_model.FindRunJobOptions{
175			Statuses:      []actions_model.Status{actions_model.StatusWaiting, actions_model.StatusBlocked},
176			UpdatedBefore: timeutil.TimeStampNow().AddDuration(-setting.Actions.AbandonedJobTimeout),
177		})
178		if err != nil {
179			log.Warn("find abandoned jobs: %v", err)
180			return err
181		}
182	
183		updatedJobs, err := actions_model.CancelJobs(ctx, abandonedJobs)
184		if err != nil {
185			log.Warn("cancel abandoned jobs: %v", err)
186		}
187	
188		NotifyWorkflowJobsAndRunsStatusUpdate(ctx, updatedJobs)
189		EmitJobsIfReadyByJobs(updatedJobs)
190	
191		return nil
192	}
