111	func (input *notifyInput) Notify(ctx context.Context) {
112		log.Trace("execute %v for event %v whose doer is %v", getMethod(ctx), input.Event, input.Doer.Name)
113	
114		if err := notify(ctx, input); err != nil {
115			log.Error("an error occurred while executing the %s actions method: %v", getMethod(ctx), err)
