119	func notify(ctx context.Context, input *notifyInput) error {
120		shouldDetectSchedules := input.Event == webhook_module.HookEventPush && input.Ref.BranchName() == input.Repo.DefaultBranch
121		if input.Doer.IsGiteaActions() {
122			// avoiding triggering cyclically, for example:
123			// a comment of an issue will trigger the runner to add a new comment as reply,
124			// and the new comment will trigger the runner again.
125			log.Debug("ignore executing %v for event %v whose doer is %v", getMethod(ctx), input.Event, input.Doer.Name)
126	
127			// we should update schedule tasks in this case, because
128			//   1. schedule tasks cannot be triggered by other events, so cyclic triggering will not occur
129			//   2. some schedule tasks may update the repo periodically, so the refs of schedule tasks need to be updated
130			if shouldDetectSchedules {
131				return DetectAndHandleSchedules(ctx, input.Repo)
132			}
133	
134			return nil
135		}
136		if input.Repo.IsEmpty || input.Repo.IsArchived {
137			return nil
138		}
139		if unit_model.TypeActions.UnitGlobalDisabled() {
140			if err := CleanRepoScheduleTasks(ctx, input.Repo); err != nil {
141				log.Error("CleanRepoScheduleTasks: %v", err)
142			}
143			return nil
144		}
145		if err := input.Repo.LoadUnits(ctx); err != nil {
146			return fmt.Errorf("repo.LoadUnits: %w", err)
147		} else if !input.Repo.UnitEnabled(ctx, unit_model.TypeActions) {
148			return nil
149		}
150	
151		gitRepo, err := gitrepo.OpenRepository(context.Background(), input.Repo)
152		if err != nil {
153			return fmt.Errorf("git.OpenRepository: %w", err)
154		}
155		defer gitRepo.Close()
156	
157		ref := input.Ref
158		if ref.BranchName() != input.Repo.DefaultBranch && actions_module.IsDefaultBranchWorkflow(input.Event) {
159			if ref != "" {
160				log.Warn("Event %q should only trigger workflows on the default branch, but its ref is %q. Will fall back to the default branch",
161					input.Event, ref)
162			}
163			ref = git.RefNameFromBranch(input.Repo.DefaultBranch)
164		}
165		if ref == "" {
166			log.Warn("Ref of event %q is empty, will fall back to the default branch", input.Event)
167			ref = git.RefNameFromBranch(input.Repo.DefaultBranch)
168		}
169	
170		commitID, err := gitRepo.GetRefCommitID(ref.String())
171		if err != nil {
172			return fmt.Errorf("gitRepo.GetRefCommitID: %w", err)
173		}
174	
175		// Get the commit object for the ref
176		commit, err := gitRepo.GetCommit(commitID)
177		if err != nil {
178			return fmt.Errorf("gitRepo.GetCommit: %w", err)
179		}
180	
181		if skipWorkflows(ctx, input, commit) {
182			return nil
183		}
184	
185		var detectedWorkflows []*actions_module.DetectedWorkflow
186		var filteredWorkflows []*actions_module.DetectedWorkflow
187		actionsConfig := input.Repo.MustGetUnit(ctx, unit_model.TypeActions).ActionsConfig()
188		workflows, schedules, filtered, err := actions_module.DetectWorkflows(gitRepo, commit,
189			input.Event,
190			input.Payload,
191			shouldDetectSchedules,
192		)
193		if err != nil {
194			return fmt.Errorf("DetectWorkflows: %w", err)
195		}
196	
197		log.Trace("repo %s with commit %s event %s find %d workflows and %d schedules",
198			input.Repo.RelativePath(),
199			commit.ID,
200			input.Event,
201			len(workflows),
202			len(schedules),
203		)
204	
205		for _, wf := range workflows {
206			if actionsConfig.IsWorkflowDisabled(wf.EntryName) {
207				log.Trace("repo %s has disable workflows %s", input.Repo.RelativePath(), wf.EntryName)
208				continue
209			}
210	
211			if wf.TriggerEvent.Name != actions_module.GithubEventPullRequestTarget {
212				detectedWorkflows = append(detectedWorkflows, wf)
213			}
214		}
215	
216		for _, wf := range filtered {
217			if actionsConfig.IsWorkflowDisabled(wf.EntryName) {
218				log.Trace("repo %s has disable workflows %s", input.Repo.RelativePath(), wf.EntryName)
219				continue
220			}
221	
222			if wf.TriggerEvent.Name != actions_module.GithubEventPullRequestTarget {
223				filteredWorkflows = append(filteredWorkflows, wf)
224			}
225		}
226	
227		if input.PullRequest != nil {
228			// detect pull_request_target workflows
229			baseRef := git.BranchPrefix + input.PullRequest.BaseBranch
230			baseCommit, err := gitRepo.GetCommit(baseRef)
231			if err != nil {
232				return fmt.Errorf("gitRepo.GetCommit: %w", err)
233			}
234			baseWorkflows, _, baseFiltered, err := actions_module.DetectWorkflows(gitRepo, baseCommit, input.Event, input.Payload, false)
235			if err != nil {
236				return fmt.Errorf("DetectWorkflows: %w", err)
237			}
238			if len(baseWorkflows) == 0 {
239				log.Trace("repo %s with commit %s couldn't find pull_request_target workflows", input.Repo.RelativePath(), baseCommit.ID)
240			} else {
241				for _, wf := range baseWorkflows {
242					if actionsConfig.IsWorkflowDisabled(wf.EntryName) {
243						log.Trace("repo %s has disable workflows %s", input.Repo.RelativePath(), wf.EntryName)
244						continue
245					}
246					if wf.TriggerEvent.Name == actions_module.GithubEventPullRequestTarget {
247						detectedWorkflows = append(detectedWorkflows, wf)
248					}
249				}
250			}
251			for _, wf := range baseFiltered {
252				if actionsConfig.IsWorkflowDisabled(wf.EntryName) {
253					log.Trace("repo %s has disable workflows %s", input.Repo.RelativePath(), wf.EntryName)
254					continue
255				}
256				if wf.TriggerEvent.Name == actions_module.GithubEventPullRequestTarget {
257					filteredWorkflows = append(filteredWorkflows, wf)
258				}
259			}
260		}
261	
262		if shouldDetectSchedules {
263			if err := handleSchedules(ctx, schedules, commit, input, ref); err != nil {
264				return err
265			}
266		}
267	
268		if err := handleWorkflows(ctx, detectedWorkflows, commit, input, ref); err != nil {
269			return err
270		}
271	
272		handleFilteredWorkflows(ctx, input, filteredWorkflows)
273	
274		return detectAndHandleScopedWorkflows(ctx, input, ref, gitRepo, commit)
275	}
276	
277	func skipWorkflows(ctx context.Context, input *notifyInput, commit *git.Commit) bool {
278		// skip workflow runs with a configured skip-ci string in commit message or pr title if the event is push or pull_request(_sync)
279		// https://docs.github.com/en/actions/managing-workflow-runs/skipping-workflow-runs
280		skipWorkflowEvents := []webhook_module.HookEventType{
281			webhook_module.HookEventPush,
282			webhook_module.HookEventPullRequest,
283			webhook_module.HookEventPullRequestSync,
284		}
285		if slices.Contains(skipWorkflowEvents, input.Event) {
286			for _, s := range setting.Actions.SkipWorkflowStrings {
287				if input.PullRequest != nil && strings.Contains(input.PullRequest.Issue.Title, s) {
288					log.Debug("repo %s: skipped run for pr %v because of %s string", input.Repo.RelativePath(), input.PullRequest.Issue.ID, s)
289					return true
290				}
291				if strings.Contains(commit.MessageRaw, s) {
292					log.Debug("repo %s with commit %s: skipped run because of %s string", input.Repo.RelativePath(), commit.ID, s)
293					return true
294				}
295			}
296		}
297		if input.Event == webhook_module.HookEventWorkflowRun {
298			wrun, ok := input.Payload.(*api.WorkflowRunPayload)
299			for i := 0; i < 5 && ok && wrun.WorkflowRun != nil; i++ {
300				if wrun.WorkflowRun.Event != "workflow_run" {
301					return false
302				}
303				r, err := actions_model.GetRunByRepoAndID(ctx, input.Repo.ID, wrun.WorkflowRun.ID)
304				if err != nil {
305					log.Error("GetRunByRepoAndID: %v", err)
306					return true
307				}
308				wrun, err = r.GetWorkflowRunEventPayload()
309				if err != nil {
310					log.Error("GetWorkflowRunEventPayload: %v", err)
311					return true
312				}
313			}
314			// skip workflow runs events exceeding the maximum of 5 recursive events
315			log.Debug("repo %s: skipped workflow_run because of recursive event of 5", input.Repo.RelativePath())
316			return true
317		}
318		return false
319	}
320	
321	func handleWorkflows(
322		ctx context.Context,
323		detectedWorkflows []*actions_module.DetectedWorkflow,
324		commit *git.Commit,
325		input *notifyInput,
326		ref git.RefName,
327	) error {
328		if len(detectedWorkflows) == 0 {
329			log.Trace("repo %s with commit %s couldn't find workflows", input.Repo.RelativePath(), commit.ID)
330			return nil
331		}
332	
333		p, err := json.Marshal(input.Payload)
334		if err != nil {
335			return fmt.Errorf("json.Marshal: %w", err)
336		}
337	
338		isForkPullRequest := isForkPullRequestInput(input)
339	
340		for _, dwf := range detectedWorkflows {
341			// repo-level run: the workflow content is this repo at this commit
342			if err := buildApproveAndInsertRun(ctx, input, ref, commit, string(p), isForkPullRequest, dwf, input.Repo.ID, commit.ID.String(), false); err != nil {
343				log.Error("repo %s: %v", input.Repo.RelativePath(), err)
344				continue
345			}
346		}
347		return nil
348	}
349	
350	// buildApproveAndInsertRun assembles an ActionRun for a detected workflow, runs the
351	// fork-PR approval gate, and inserts it. Repo-level and scoped runs share this path so
352	// run construction and the approval flow have a single implementation that can't drift.
353	// workflowRepoID/workflowCommitSHA point at the repo+commit the workflow content comes
354	// from (the repo itself for repo-level runs, the source repo for scoped runs).
355	func buildApproveAndInsertRun(
356		ctx context.Context,
357		input *notifyInput,
358		ref git.RefName,
359		commit *git.Commit,
360		payload string,
361		isForkPullRequest bool,
362		dwf *actions_module.DetectedWorkflow,
363		workflowRepoID int64,
364		workflowCommitSHA string,
365		isScopedRun bool,
366	) error {
367		run := &actions_model.ActionRun{
368			Title:             commit.MessageTitle(),
369			RepoID:            input.Repo.ID,
370			Repo:              input.Repo,
371			OwnerID:           input.Repo.OwnerID,
372			WorkflowID:        dwf.EntryName,
373			TriggerUserID:     input.Doer.ID,
374			TriggerUser:       input.Doer,
375			Ref:               ref.String(),
376			CommitSHA:         commit.ID.String(),
377			IsForkPullRequest: isForkPullRequest,
378			Event:             input.Event,
379			EventPayload:      payload,
380			TriggerEvent:      dwf.TriggerEvent.Name,
381			Status:            actions_model.StatusWaiting,
382			WorkflowRepoID:    workflowRepoID,
383			WorkflowCommitSHA: workflowCommitSHA,
384			IsScopedRun:       isScopedRun,
385		}
386	
387		need, err := ifNeedApproval(ctx, run, input.Repo, input.Doer)
388		if err != nil {
389			return fmt.Errorf("check if need approval for user %d: %w", input.Doer.ID, err)
390		}
391		run.NeedApproval = need
392	
393		if err := PrepareRunAndInsert(ctx, dwf.Content, run, nil); err != nil {
394			return fmt.Errorf("PrepareRunAndInsert: %w", err)
395		}
396		return nil
397	}
398	
399	// handleFilteredWorkflows posts a skipped commit status for each filtered-out workflow whose context is a required status check;
400	// a non-required one posts nothing, so it cannot leak into a pull request.
401	func handleFilteredWorkflows(ctx context.Context, input *notifyInput, filteredWorkflows []*actions_module.DetectedWorkflow) {
402		if len(filteredWorkflows) == 0 {
403			return
404		}
405		requiredGlobs, err := getAllRequiredStatusContextGlobs(ctx, input.Repo)
406		if err != nil {
407			log.Error("repo %s: required status contexts: %v", input.Repo.RelativePath(), err)
408			return
409		}
410		if len(requiredGlobs) == 0 {
411			return
412		}
413		for _, dwf := range filteredWorkflows {
414			if err := CreateSkippedCommitStatusForFilteredWorkflow(ctx, input.Repo, input.Event, dwf.TriggerEvent.Name, dwf.EntryName, dwf.Content, input.Payload, "", requiredGlobs); err != nil {
415				log.Error("repo %s: skipped commit status for workflow %s: %v", input.Repo.RelativePath(), dwf.EntryName, err)
416				continue
417			}
418		}
419	}
