430	
431		permission, _ := access_model.GetDoerRepoPermission(ctx, rel.Repo, doer)
432	
433		newNotifyInput(rel.Repo, doer, webhook_module.HookEventRelease).
434			WithRef(git.RefNameFromTag(rel.TagName).String()).
435			WithPayload(&api.ReleasePayload{
436				Action:     action,
437				Release:    convert.ToAPIRelease(ctx, rel.Repo, rel),
438				Repository: convert.ToRepo(ctx, rel.Repo, permission),
