35	type methodCtxKeyType struct{}
36	
37	var methodCtxKey methodCtxKeyType
38	
39	// withMethod sets the notification method that this context currently executes.
40	// Used for debugging/ troubleshooting purposes.
41	func withMethod(ctx context.Context, method string) context.Context {
42		// don't overwrite
43		if v := ctx.Value(methodCtxKey); v != nil {
44			if _, ok := v.(string); ok {
45				return ctx
46			}
47		}
48		return context.WithValue(ctx, methodCtxKey, method)
49	}
50	
51	// getMethod gets the notification method that this context currently executes.
52	// Default: "notify"
53	// Used for debugging/ troubleshooting purposes.
54	func getMethod(ctx context.Context) string {
55		if v := ctx.Value(methodCtxKey); v != nil {
56			if s, ok := v.(string); ok {
57				return s
58			}
59		}
60		return "notify"
