83	func newNotifyInputForSchedules(repo *repo_model.Repository) *notifyInput {
84		// the doer here will be ignored as we force using action user when handling schedules
85		return newNotifyInput(repo, user_model.NewActionsUser(), webhook_module.HookEventSchedule)
86	}
