103	func (input *notifyInput) WithPullRequest(pr *issues_model.PullRequest) *notifyInput {
104		input.PullRequest = pr
105		if input.Ref == "" {
106			input.Ref = git.RefName(pr.GetGitHeadRefName())
107		}
108		return input
