467	func ifNeedApproval(ctx context.Context, run *actions_model.ActionRun, repo *repo_model.Repository, user *user_model.User) (bool, error) {
468		canWrite := func(ctx context.Context, repo *repo_model.Repository, user *user_model.User) (bool, error) {
469			perm, err := access_model.GetDoerRepoPermission(ctx, repo, user)
470			if err != nil {
471				return false, err
472			}
473			return perm.CanWrite(unit_model.TypeActions), nil
474		}
475		return ifNeedApprovalWith(ctx, run, repo, user, canWrite, issues_model.HasMergedPullRequestInRepo)
476	}
477	
478	func ifNeedApprovalWith(
479		ctx context.Context,
480		run *actions_model.ActionRun,
481		repo *repo_model.Repository,
482		user *user_model.User,
483		canWriteActions func(context.Context, *repo_model.Repository, *user_model.User) (bool, error),
484		hasMergedPR func(context.Context, int64, int64) (bool, error),
485	) (bool, error) {
486		// 1. don't need approval if it's not a fork PR
487		// 2. don't need approval if the event is `pull_request_target` since the workflow will run in the context of base branch
488		// 		see https://docs.github.com/en/actions/managing-workflow-runs/approving-workflow-runs-from-public-forks#about-workflow-runs-from-public-forks
489		if !run.IsForkPullRequest || run.TriggerEvent == actions_module.GithubEventPullRequestTarget {
490			return false, nil
491		}
492	
493		// always need approval if the user is restricted
494		if user.IsRestricted {
495			log.Trace("need approval because user %d is restricted", user.ID)
496			return true, nil
497		}
498	
499		// don't need approval if the user can write
500		if ok, err := canWriteActions(ctx, repo, user); err != nil {
501			return false, fmt.Errorf("GetDoerRepoPermission: %w", err)
502		} else if ok {
503			log.Trace("do not need approval because user %d can write", user.ID)
504			return false, nil
505		}
506	
507		// trust the user only after a merged PR — matching GitHub Actions. Approving one
508		// fork PR's run must not implicitly trust later fork PRs that replace the workflow.
509		if merged, err := hasMergedPR(ctx, repo.ID, user.ID); err != nil {
510			return false, fmt.Errorf("HasMergedPullRequestInRepo: %w", err)
511		} else if merged {
512			log.Trace("do not need approval because user %d has a merged pull request in repo %d", user.ID, repo.ID)
513			return false, nil
514		}
515	
516		// otherwise, need approval
517		log.Trace("need approval because user %d has no merged pull request in repo %d", user.ID, repo.ID)
518		return true, nil
519	}
