521	func handleSchedules(
522		ctx context.Context,
523		detectedWorkflows []*actions_module.DetectedWorkflow,
524		commit *git.Commit,
525		input *notifyInput,
526		ref git.RefName,
527	) error {
528		if ref.BranchName() != input.Repo.DefaultBranch {
529			log.Trace("commit branch is not default branch in repo")
530			return nil
531		}
532	
533		if count, err := db.Count[actions_model.ActionSchedule](ctx, actions_model.FindScheduleOptions{RepoID: input.Repo.ID}); err != nil {
534			log.Error("CountSchedules: %v", err)
535			return err
536		} else if count > 0 {
537			if err := CleanRepoScheduleTasks(ctx, input.Repo); err != nil {
538				log.Error("CleanRepoScheduleTasks: %v", err)
539			}
540		}
541	
542		if len(detectedWorkflows) == 0 {
543			log.Trace("repo %s with commit %s couldn't find schedules", input.Repo.RelativePath(), commit.ID)
544			return nil
545		}
546	
547		p, err := json.Marshal(input.Payload)
548		if err != nil {
549			return fmt.Errorf("json.Marshal: %w", err)
550		}
551	
552		crons := make([]*actions_model.ActionSchedule, 0, len(detectedWorkflows))
553		for _, dwf := range detectedWorkflows {
554			// Check cron job condition. Only working in default branch
555			workflow, err := model.ReadWorkflow(bytes.NewReader(dwf.Content))
556			if err != nil {
557				log.Error("ReadWorkflow: %v", err)
558				continue
559			}
560			schedules := workflow.OnSchedule()
561			if len(schedules) == 0 {
562				log.Warn("no schedule event")
563				continue
564			}
565	
566			run := &actions_model.ActionSchedule{
567				Title:         commit.MessageTitle(),
568				RepoID:        input.Repo.ID,
569				Repo:          input.Repo,
570				OwnerID:       input.Repo.OwnerID,
571				WorkflowID:    dwf.EntryName,
572				TriggerUserID: user_model.ActionsUserID,
573				TriggerUser:   user_model.NewActionsUser(),
574				Ref:           ref.String(),
575				CommitSHA:     commit.ID.String(),
576				Event:         input.Event,
577				EventPayload:  string(p),
578				Specs:         schedules,
579				Content:       dwf.Content,
580			}
581	
582			crons = append(crons, run)
583		}
584	
585		return actions_model.CreateScheduleTask(ctx, crons)
586	}
