621	// isForkPullRequestInput reports whether the run should be treated as a fork pull request.
622	func isForkPullRequestInput(input *notifyInput) bool {
623		pr := input.PullRequest
624		if pr == nil {
625			return false
626		}
627		switch pr.Flow {
628		case issues_model.PullRequestFlowGithub:
629			return pr.IsFromFork()
630		case issues_model.PullRequestFlowAGit:
631			// There is no fork concept in agit flow, anyone with read permission can push refs/for/<target-branch>/<topic-branch> to the repo.
632			// So we can treat it as a fork pull request because it may be from an untrusted user
633			return true
634		default:
635			// unknown flow, assume it's a fork pull request to be safe
636			return true
637		}
638	}
