640	// detectAndHandleScopedWorkflows detects scoped workflows registered for the consuming repo
641	func detectAndHandleScopedWorkflows(
642		ctx context.Context,
643		input *notifyInput,
644		ref git.RefName,
645		consumerGitRepo *git.Repository,
646		consumerCommit *git.Commit,
647	) error {
648		// TODO: support workflow_run and schedule
649		if input.Event == webhook_module.HookEventWorkflowRun || input.Event == webhook_module.HookEventSchedule {
650			return nil
651		}
652	
653		sources, err := actions_model.GetEffectiveScopedWorkflowSources(ctx, input.Repo.OwnerID)
654		if err != nil {
655			return fmt.Errorf("GetEffectiveScopedWorkflowSources: %w", err)
656		}
657		if len(sources) == 0 {
658			return nil
659		}
660	
661		p, err := json.Marshal(input.Payload)
662		if err != nil {
663			return fmt.Errorf("json.Marshal: %w", err)
664		}
665		isForkPullRequest := isForkPullRequestInput(input)
666		actionsConfig := input.Repo.MustGetUnit(ctx, unit_model.TypeActions).ActionsConfig()
667	
668		// A filtered-out scoped workflow only posts a skipped status when its context is a required check.
669		requiredGlobs, err := getAllRequiredStatusContextGlobs(ctx, input.Repo)
670		if err != nil {
671			log.Error("scoped workflows: required status contexts for %s: %v", input.Repo.RelativePath(), err)
672		}
673	
674		// The same source repo may be registered at both the owner and instance level; dedup
675		// the IDs and batch-load them in one query instead of one round-trip per source.
676		seen := make(container.Set[int64], len(sources))
677		for _, source := range sources {
678			seen.Add(source.SourceRepoID)
679		}
680		sourceRepoIDs := seen.Values()
681	
682		sourceRepos, err := repo_model.GetRepositoriesMapByIDs(ctx, sourceRepoIDs)
683		if err != nil {
684			return fmt.Errorf("GetRepositoriesMapByIDs: %w", err)
685		}
686	
687		for _, sourceRepoID := range sourceRepoIDs {
688			sourceRepo := sourceRepos[sourceRepoID]
689			if sourceRepo == nil {
690				// don't abort the other effective sources for this event
691				log.Error("scoped workflows: source repo %d for consumer %s not found", sourceRepoID, input.Repo.RelativePath())
692				continue
693			}
694			if sourceRepo.IsEmpty {
695				continue
696			}
697	
698			sourceCommitSHA, detected, filtered, err := detectScopedWorkflowsForSource(ctx, input, consumerGitRepo, consumerCommit, sourceRepo)
699			if err != nil {
700				log.Error("scoped workflows: source %d for consumer %s: %v", sourceRepoID, input.Repo.RelativePath(), err)
701				continue
702			}
703	
704			for _, dwf := range detected {
705				// A consuming repo can opt out of a non-required scoped workflow.
706				// A required workflow (marked required at any effective level) can never be opted out.
707				if actions_model.ScopedWorkflowOptedOut(actionsConfig, sources, sourceRepo.ID, dwf.EntryName) {
708					continue
709				}
710	
711				if err := buildApproveAndInsertRun(ctx, input, ref, consumerCommit, string(p), isForkPullRequest, dwf, sourceRepo.ID, sourceCommitSHA, true); err != nil {
712					log.Error("scoped workflows: source %s workflow %s: %v", sourceRepo.RelativePath(), dwf.EntryName, err)
713					continue
714				}
715			}
716	
717			// A filtered-out scoped workflow posts a skipped commit status for its required-check contexts.
718			if len(filtered) > 0 && len(requiredGlobs) > 0 {
719				scopedPrefix := actions_model.ScopedStatusContextPrefix(ctx, sourceRepo.ID)
720				for _, dwf := range filtered {
721					if actions_model.ScopedWorkflowOptedOut(actionsConfig, sources, sourceRepo.ID, dwf.EntryName) {
722						continue
723					}
724					if err := CreateSkippedCommitStatusForFilteredWorkflow(ctx, input.Repo, input.Event, dwf.TriggerEvent.Name, dwf.EntryName, dwf.Content, input.Payload, scopedPrefix, requiredGlobs); err != nil {
725						log.Error("scoped workflows: skipped commit status for source %s workflow %s: %v", sourceRepo.RelativePath(), dwf.EntryName, err)
726						continue
727					}
728				}
729			}
730		}
731	
732		return nil
733	}
734	
735	// detectScopedWorkflowsForSource detects the scoped workflows from the source repo at its default branch.
736	// detected are the workflows to run; filtered matched the event but were excluded by a branch/paths
737	// filter, and later post a skipped commit status only for a required-check context.
738	func detectScopedWorkflowsForSource(
739		ctx context.Context,
740		input *notifyInput,
741		consumerGitRepo *git.Repository,
742		consumerCommit *git.Commit,
743		sourceRepo *repo_model.Repository,
744	) (sourceCommitSHA string, detected, filtered []*actions_module.DetectedWorkflow, err error) {
745		// scoped workflow content is always taken from the source repo's default branch; the parse is cached per (source, default-branch SHA) and reused across consuming repos/events
746		sourceCommitSHA, parsed, err := LoadParsedScopedWorkflows(ctx, sourceRepo)
747		if err != nil {
748			return "", nil, nil, err
749		}
750		detected, filtered = actions_module.MatchScopedWorkflows(parsed, consumerGitRepo, consumerCommit, input.Event, input.Payload)
751		return sourceCommitSHA, detected, filtered, nil
752	}
