181	// execRerunPlan executes the rerun plan built by buildRerunPlan.
182	// It loads run variables, constructs the new ActionRunAttempt and evaluates run-level concurrency (all outside the transaction to keep the tx short).
183	// Inside a single database transaction it then inserts the new attempt, clones all template jobs, evaluates job-level concurrency for rerun jobs,
184	// and updates the run's latest_attempt_id.
185	// Jobs not in the rerun set are cloned as pass-through: their status is preserved and SourceTaskID points to the original task so the UI can still display their results.
186	// The attempt's final status is derived only from the rerun jobs, not the pass-through jobs.
187	// Notifications and commit statuses are sent after the transaction commits.
188	func execRerunPlan(ctx context.Context, plan *rerunPlan) (*actions_model.ActionRunAttempt, error) {
189		vars, err := actions_model.GetVariablesOfRun(ctx, plan.run)
190		if err != nil {
191			return nil, fmt.Errorf("get run %d variables: %w", plan.run.ID, err)
192		}
193	
194		newAttempt := &actions_model.ActionRunAttempt{
195			RepoID:        plan.run.RepoID,
196			RunID:         plan.run.ID,
197			Attempt:       plan.templateAttempt.Attempt + 1,
198			TriggerUserID: plan.triggerUser.ID,
199			Status:        actions_model.StatusWaiting,
200		}
201	
202		if plan.run.RawConcurrency != "" {
203			var rawConcurrency model.RawConcurrency
204			if err := yaml.Unmarshal([]byte(plan.run.RawConcurrency), &rawConcurrency); err != nil {
205				return nil, fmt.Errorf("unmarshal raw concurrency: %w", err)
206			}
207			if err := EvaluateRunConcurrencyFillModel(ctx, plan.run, newAttempt, &rawConcurrency, vars, nil); err != nil {
208				return nil, err
209			}
210		}
211	
212		var newJobs, newJobsToRerun actions_model.ActionJobList
213		var cancelledConcurrencyJobs []*actions_model.ActionRunJob
214		var hasWaitingCallerJobs bool
215	
216		err = db.WithTx(ctx, func(ctx context.Context) error {
217			newAttemptStatus, jobsToCancel, err := PrepareToStartRunWithConcurrency(ctx, newAttempt)
218			if err != nil {
219				return err
220			}
221			cancelledConcurrencyJobs = append(cancelledConcurrencyJobs, jobsToCancel...)
222			newAttempt.Status = newAttemptStatus
223			shouldBlock := newAttemptStatus == actions_model.StatusBlocked
224	
225			if err := db.Insert(ctx, newAttempt); err != nil {
226				if _, getErr := actions_model.GetRunAttemptByRunIDAndAttemptNum(ctx, plan.run.ID, newAttempt.Attempt); getErr == nil {
227					return util.NewAlreadyExistErrorf("workflow run attempt %d for run %d already exists", newAttempt.Attempt, plan.run.ID)
228				}
229				return err
230			}
231	
232			plan.run.LatestAttemptID = newAttempt.ID
233			if err := actions_model.UpdateRun(ctx, plan.run, "latest_attempt_id"); err != nil {
234				return err
235			}
236	
237			hasWaitingJobs := false
238			newJobs = make(actions_model.ActionJobList, 0, len(plan.templateJobs))
239			newJobsToRerun = make(actions_model.ActionJobList, 0, len(plan.rerunAttemptJobIDs))
240	
241			// templateIDToNewID maps each template-attempt job's DB ID to its newly-inserted clone's DB ID
242			templateIDToNewID := make(map[int64]int64, len(plan.templateJobs))
243	
244			for _, templateJob := range plan.templateJobs {
245				// descendants of a reset reusable caller are not cloned at all, the caller will re-insert them
246				if plan.skipCloneTemplateJobIDs.Contains(templateJob.ID) {
247					continue
248				}
249	
250				newJob := cloneRunJobForAttempt(templateJob, newAttempt)
251	
252				// Remap ParentJobID from template attempts's DB ID -> new attempt's DB ID.
253				if templateJob.ParentJobID != 0 {
254					newParentID, ok := templateIDToNewID[templateJob.ParentJobID]
255					if !ok {
256						return fmt.Errorf("clone order violation: parent job %d not yet cloned for child %d",
257							templateJob.ParentJobID, templateJob.ID)
258					}
259					newJob.ParentJobID = newParentID
260				}
261	
262				if plan.rerunAttemptJobIDs.Contains(templateJob.AttemptJobID) {
263					shouldBlockJob := shouldBlock || plan.hasRerunDependency(templateJob)
264	
265					newJob.Status = util.Iif(shouldBlockJob, actions_model.StatusBlocked, actions_model.StatusWaiting)
266					newJob.TaskID = 0
267					newJob.SourceTaskID = 0
268					newJob.Started = 0
269					newJob.Stopped = 0
270					newJob.ConcurrencyGroup = ""
271					newJob.ConcurrencyCancel = false
272					newJob.IsConcurrencyEvaluated = false
273	
274					if templateJob.IsReusableCaller {
275						newJob.IsExpanded = false
276						newJob.CallPayload = ""
277					}
278	
279					if newJob.RawConcurrency != "" && !shouldBlockJob {
280						if err := EvaluateJobConcurrencyFillModel(ctx, plan.run, newAttempt, newJob, vars, nil); err != nil {
281							return fmt.Errorf("evaluate job concurrency: %w", err)
282						}
283						newJob.Status, jobsToCancel, err = PrepareToStartJobWithConcurrency(ctx, newJob)
284						if err != nil {
285							return fmt.Errorf("prepare to start job with concurrency: %w", err)
286						}
287						cancelledConcurrencyJobs = append(cancelledConcurrencyJobs, jobsToCancel...)
288					}
289	
290					newJobsToRerun = append(newJobsToRerun, newJob)
291				} else {
292					newJob.TaskID = 0
293					newJob.SourceTaskID = templateJob.EffectiveTaskID()
294	
295					isAncestor := plan.ancestorAttemptJobIDs.Contains(templateJob.AttemptJobID)
296					newJob.Started = util.Iif(isAncestor, 0, templateJob.Started)
297					newJob.Stopped = util.Iif(isAncestor, 0, templateJob.Stopped)
298				}
299	
300				if err := db.Insert(ctx, newJob); err != nil {
301					return err
302				}
303				templateIDToNewID[templateJob.ID] = newJob.ID
304	
305				// expand reusable caller
306				if newJob.IsReusableCaller && newJob.Status == actions_model.StatusWaiting && !newJob.IsExpanded {
307					if err := expandReusableWorkflowCaller(ctx, plan.run, newAttempt, newJob, vars); err != nil {
308						return fmt.Errorf("inline trigger caller %d ready: %w", newJob.ID, err)
309					}
310					// refresh the caller status
311					if err := actions_model.RefreshReusableCallerStatus(ctx, newJob); err != nil {
312						return fmt.Errorf("refresh caller %d status: %w", newJob.ID, err)
313					}
314					hasWaitingCallerJobs = true
315				}
316	
317				// A reusable caller is never dispatched to a runner, so it must not drive the task-version bump.
318				hasWaitingJobs = hasWaitingJobs || (newJob.Status == actions_model.StatusWaiting && !newJob.IsReusableCaller)
319				newJobs = append(newJobs, newJob)
320			}
321	
322			// Refresh each ancestor's status from its now-fresh children.
323			// `newJobs` is appended top-down (caller before its children), so we walk it in reverse to refresh the deepest ancestor first.
324			for _, ancestor := range slices.Backward(newJobs) {
325				if !ancestor.IsReusableCaller || !plan.ancestorAttemptJobIDs.Contains(ancestor.AttemptJobID) {
326					continue
327				}
328				if err := actions_model.RefreshReusableCallerStatus(ctx, ancestor); err != nil {
329					return fmt.Errorf("refresh ancestor caller %d status: %w", ancestor.ID, err)
330				}
331			}
332	
333			newAttempt.Status = actions_model.AggregateJobStatus(newJobsToRerun)
334			if err := actions_model.UpdateRunAttempt(ctx, newAttempt, "status"); err != nil {
335				return err
336			}
337	
338			if hasWaitingJobs {
339				if err := actions_model.IncreaseTaskVersion(ctx, plan.run.OwnerID, plan.run.RepoID); err != nil {
340					return err
341				}
342			}
343	
344			return nil
345		})
346		if err != nil {
347			return nil, err
348		}
349	
350		if err := plan.run.LoadAttributes(ctx); err != nil {
351			return nil, err
352		}
353	
354		NotifyWorkflowJobsAndRunsStatusUpdate(ctx, cancelledConcurrencyJobs)
355		EmitJobsIfReadyByJobs(cancelledConcurrencyJobs)
356	
357		CreateCommitStatusForRunJobs(ctx, plan.run, newJobs...)
358		NotifyWorkflowJobsAndRunsStatusUpdate(ctx, newJobsToRerun)
359	
360		// Post-commit kick for expanded callers: let job_emitter resolve its child jobs
361		if hasWaitingCallerJobs {
362			if err := EmitJobsIfReadyByRun(plan.run.ID); err != nil {
363				log.Error("emit run %d after rerun: %v", plan.run.ID, err)
364			}
365		}
366	
367		return newAttempt, nil
368	}
369	
370	// expandRerunJobIDs computes rerunAttemptJobIDs and ancestorAttemptJobIDs from the user-selected jobsToRerun.
371	func (p *rerunPlan) expandRerunJobIDs(jobsToRerun []*actions_model.ActionRunJob) error {
372		// Empty jobsToRerun: rerun the whole latest attempt
373		if len(jobsToRerun) == 0 {
374			all := make(container.Set[int64], len(p.templateJobs))
375			for _, job := range p.templateJobs {
376				all.Add(job.AttemptJobID)
377			}
378			p.rerunAttemptJobIDs = all
379			p.ancestorAttemptJobIDs = make(container.Set[int64])
380			return nil
381		}
382	
383		byID := make(map[int64]*actions_model.ActionRunJob, len(p.templateJobs))
384		byAttemptJobID := make(map[int64]*actions_model.ActionRunJob, len(p.templateJobs))
385		for _, job := range p.templateJobs {
386			byID[job.ID] = job
387			byAttemptJobID[job.AttemptJobID] = job
388		}
389	
390		for _, job := range jobsToRerun {
391			if _, ok := byID[job.ID]; !ok {
392				return util.NewInvalidArgumentErrorf("job %q does not exist in the latest attempt", job.JobID)
393			}
394		}
395	
396		rerunSet := make(container.Set[int64])
397		ancestorSet := make(container.Set[int64])
398		queue := make([]*actions_model.ActionRunJob, 0, len(jobsToRerun))
399	
400		for _, job := range jobsToRerun {
401			j := byID[job.ID]
402			rerunSet.Add(j.AttemptJobID)
403			queue = append(queue, j)
404		}
405	
406		for len(queue) > 0 {
407			cur := queue[0]
408			queue = queue[1:]
409	
410			// same-scope downstream: siblings whose Needs reference cur.JobID join the rerun set
411			for _, candidate := range p.templateJobs {
412				if candidate.ParentJobID != cur.ParentJobID {
413					continue
414				}
415				if rerunSet.Contains(candidate.AttemptJobID) || ancestorSet.Contains(candidate.AttemptJobID) {
416					continue
417				}
418				if !slices.Contains(candidate.Needs, cur.JobID) {
419					continue
420				}
421				rerunSet.Add(candidate.AttemptJobID)
422				queue = append(queue, candidate)
423			}
424	
425			// escalate to parent caller as an ancestor so its own siblings get checked next round
426			if cur.ParentJobID == 0 {
427				continue
428			}
429			parent, ok := byID[cur.ParentJobID]
430			if !ok {
431				continue
432			}
433			if rerunSet.Contains(parent.AttemptJobID) || ancestorSet.Contains(parent.AttemptJobID) {
434				continue
435			}
436			ancestorSet.Add(parent.AttemptJobID)
437			queue = append(queue, parent)
438		}
439	
440		// remove entries whose parent-caller chain already has a rerunSet member
441		for atID := range ancestorSet {
442			cur := byAttemptJobID[atID]
443			for cur.ParentJobID != 0 {
444				parent, ok := byID[cur.ParentJobID]
445				if !ok {
446					break
447				}
448				if rerunSet.Contains(parent.AttemptJobID) {
449					delete(ancestorSet, atID)
450					break
451				}
452				cur = parent
453			}
454		}
455	
456		p.rerunAttemptJobIDs = rerunSet
457		p.ancestorAttemptJobIDs = ancestorSet
458		return nil
459	}
460	
461	// hasRerunDependency reports whether `job` has a needs-reference that points to a job which is itself being rerun (in rerunAttemptJobIDs)
462	// or is an ancestor caller whose subtree is being rerun (in ancestorAttemptJobIDs).
463	// Either case means `job` should start in Blocked status.
464	func (p *rerunPlan) hasRerunDependency(job *actions_model.ActionRunJob) bool {
465		if len(job.Needs) == 0 {
466			return false
467		}
468		needSet := container.SetOf(job.Needs...)
469		for _, sibling := range p.templateJobs {
470			if sibling.ParentJobID != job.ParentJobID {
471				continue
472			}
473			if !needSet.Contains(sibling.JobID) {
474				continue
475			}
476			if p.rerunAttemptJobIDs.Contains(sibling.AttemptJobID) || p.ancestorAttemptJobIDs.Contains(sibling.AttemptJobID) {
477				return true
478			}
479		}
480		return false
481	}
482	
483	// collectResetCallerDescendants walks p.templateJobs and returns the DB IDs of every transitive descendant of any reusable caller whose AttemptJobID is in p.rerunAttemptJobIDs.
484	// These descendants must NOT be cloned by execRerunPlan: the reset caller will re-insert them with template-matched AttemptJobIDs.
485	func (p *rerunPlan) collectResetCallerDescendants() container.Set[int64] {
486		out := make(container.Set[int64])
487		for _, tj := range p.templateJobs {
488			if !tj.IsReusableCaller || !p.rerunAttemptJobIDs.Contains(tj.AttemptJobID) {
489				continue
490			}
491			// If this caller's row ID is already in `out`, it means an outer caller has already covered its whole subtree.
492			// Skip the redundant walk.
493			if out.Contains(tj.ID) {
494				continue
495			}
496			for _, child := range actions_model.CollectAllDescendantJobs(tj, p.templateJobs) {
497				out.Add(child.ID)
498			}
499		}
500		return out
501	}
502	
503	func cloneRunJobForAttempt(templateJob *actions_model.ActionRunJob, attempt *actions_model.ActionRunAttempt) *actions_model.ActionRunJob {
504		return &actions_model.ActionRunJob{
505			RunID:                  templateJob.RunID,
506			RunAttemptID:           attempt.ID,
507			RepoID:                 templateJob.RepoID,
508			OwnerID:                templateJob.OwnerID,
509			CommitSHA:              templateJob.CommitSHA,
510			IsForkPullRequest:      templateJob.IsForkPullRequest,
511			Name:                   templateJob.Name,
512			Attempt:                attempt.Attempt,
513			WorkflowPayload:        slices.Clone(templateJob.WorkflowPayload),
514			JobID:                  templateJob.JobID,
515			AttemptJobID:           templateJob.AttemptJobID,
516			Needs:                  slices.Clone(templateJob.Needs),
517			RunsOn:                 slices.Clone(templateJob.RunsOn),
518			ContinueOnError:        templateJob.ContinueOnError,
519			Status:                 templateJob.Status,
520			RawConcurrency:         templateJob.RawConcurrency,
521			IsConcurrencyEvaluated: templateJob.IsConcurrencyEvaluated,
522			ConcurrencyGroup:       templateJob.ConcurrencyGroup,
523			ConcurrencyCancel:      templateJob.ConcurrencyCancel,
524			TokenPermissions:       templateJob.TokenPermissions,
525	
526			// reusable workflow fields
527			IsReusableCaller:        templateJob.IsReusableCaller,
528			CallUses:                templateJob.CallUses,
529			ReusableWorkflowContent: slices.Clone(templateJob.ReusableWorkflowContent),
530			CallSecrets:             templateJob.CallSecrets,
531			CallPayload:             templateJob.CallPayload,
532			IsExpanded:              templateJob.IsExpanded,
533			ParentJobID:             templateJob.ParentJobID, // remapped by execRerunPlan
534			WorkflowSourceRepoID:    templateJob.WorkflowSourceRepoID,
535			WorkflowSourceCommitSHA: templateJob.WorkflowSourceCommitSHA,
536		}
537	}
538	
539	// createOriginalAttemptForLegacyRun creates a real attempt=1 for a legacy run and updates the existing legacy jobs and artifacts in place
540	// so the original execution becomes attempt-aware before the rerun plan is built and all subsequent logic can use real attempts.
541	// Tasks are not modified: they reference jobs by JobID, so updating jobs implicitly carries the new attempt linkage.
542	func createOriginalAttemptForLegacyRun(ctx context.Context, run *actions_model.ActionRun) error {
543		return db.WithTx(ctx, func(ctx context.Context) error {
544			jobs, err := actions_model.GetRunJobsByRunAndAttemptID(ctx, run.ID, 0)
545			if err != nil {
546				return fmt.Errorf("load legacy run jobs: %w", err)
547			}
548			if len(jobs) == 0 {
549				return fmt.Errorf("run %d has no jobs", run.ID)
550			}
551	
552			originalAttempt := &actions_model.ActionRunAttempt{
553				RepoID:        run.RepoID,
554				RunID:         run.ID,
555				Attempt:       1,
556				TriggerUserID: run.TriggerUserID,
557	
558				// Legacy concurrency fields on ActionRun are intentionally NOT backfilled onto this original attempt.
559				// They only matter while a run is actively being scheduled, and backfilling them for completed legacy runs
560				// would add migration/runtime cost without changing any future concurrency behavior.
561	
562				Status:  run.Status,
563				Created: run.Created,
564				Started: run.Started,
565				Stopped: run.Stopped,
566			}
567	
568			// Use NoAutoTime so xorm does not overwrite Created with the current time on insert.
569			if _, err := db.GetEngine(ctx).NoAutoTime().Insert(originalAttempt); err != nil {
570				if _, getErr := actions_model.GetRunAttemptByRunIDAndAttemptNum(ctx, run.ID, originalAttempt.Attempt); getErr == nil {
571					return util.NewAlreadyExistErrorf("workflow run attempt %d for run %d already exists", originalAttempt.Attempt, run.ID)
572				}
573				return err
574			}
575	
576			// backfill attempt related fields for jobs
577			for i, job := range jobs {
578				job.RunAttemptID = originalAttempt.ID
579				job.Attempt = originalAttempt.Attempt
580				job.AttemptJobID = int64(i + 1)
581				if _, err := db.GetEngine(ctx).ID(job.ID).Cols("run_attempt_id", "attempt", "attempt_job_id").Update(job); err != nil {
582					return fmt.Errorf("backfill legacy run jobs: %w", err)
583				}
584			}
585	
586			// backfill "run_attempt_id" field for artifacts
587			if _, err := db.GetEngine(ctx).
588				Where("run_id=? AND run_attempt_id=0", run.ID).
589				Cols("run_attempt_id").
590				Update(&actions_model.ActionArtifact{RunAttemptID: originalAttempt.ID}); err != nil {
591				return fmt.Errorf("backfill legacy artifacts: %w", err)
592			}
593	
594			// update "latest_attempt_id" for the run
595			run.LatestAttemptID = originalAttempt.ID
596			return actions_model.UpdateRun(ctx, run, "latest_attempt_id")
597		})
598	}
