25	// GetFailedJobsForRerun returns the failed or cancelled jobs in a run.
26	func GetFailedJobsForRerun(allJobs []*actions_model.ActionRunJob) []*actions_model.ActionRunJob {
27		var jobsToRerun []*actions_model.ActionRunJob
28	
29		for _, job := range allJobs {
30			if job.Status == actions_model.StatusFailure || job.Status == actions_model.StatusCancelled {
31				jobsToRerun = append(jobsToRerun, job)
32			}
33		}
34	
35		return jobsToRerun
36	}
