38	// RerunWorkflowRunJobs reruns the given jobs of a workflow run.
39	// An empty jobsToRerun means rerunning the whole run. Otherwise jobsToRerun contains only the user-requested target jobs;
40	// downstream dependent jobs are expanded internally while building the rerun plan.
41	//
42	// The three stages below (legacy backfill, plan build, plan exec) deliberately run in separate DB transactions
43	// rather than one big outer transaction:
44	//   - execRerunPlan performs slow work (loading variables, YAML unmarshal, concurrency expression evaluation)
45	//     before opening its own transaction, so the tx stays focused on inserts/updates.
46	//     (Exception: reusable workflow caller expansion runs inside the tx, see expandReusableWorkflowCaller's doc.)
47	//   - The legacy backfill is idempotent-friendly: if it succeeds but a later stage fails, a subsequent rerun
48	//     will observe run.LatestAttemptID != 0 and skip the backfill, continuing naturally. No data corruption
49	//     or stuck state results from partial progress.
50	//
51	// Fast validations that can catch failures early (workflow disabled, run not done, etc.) are therefore
52	// pushed into validateRerun so we rarely enter createOriginalAttemptForLegacyRun only to fail afterwards.
53	func RerunWorkflowRunJobs(ctx context.Context, repo *repo_model.Repository, run *actions_model.ActionRun, triggerUser *user_model.User, jobsToRerun []*actions_model.ActionRunJob) (*actions_model.ActionRunAttempt, error) {
54		if err := validateRerun(ctx, run, repo, triggerUser, jobsToRerun); err != nil {
55			return nil, err
56		}
57	
58		if run.LatestAttemptID == 0 {
59			if err := createOriginalAttemptForLegacyRun(ctx, run); err != nil {
60				return nil, fmt.Errorf("create attempt for legacy run: %w", err)
61			}
62		}
63	
64		plan, err := buildRerunPlan(ctx, run, triggerUser, jobsToRerun)
65		if err != nil {
66			return nil, err
67		}
68		return execRerunPlan(ctx, plan)
69	}
