370	// expandRerunJobIDs computes rerunAttemptJobIDs and ancestorAttemptJobIDs from the user-selected jobsToRerun.
371	func (p *rerunPlan) expandRerunJobIDs(jobsToRerun []*actions_model.ActionRunJob) error {
372		// Empty jobsToRerun: rerun the whole latest attempt
373		if len(jobsToRerun) == 0 {
374			all := make(container.Set[int64], len(p.templateJobs))
375			for _, job := range p.templateJobs {
376				all.Add(job.AttemptJobID)
377			}
378			p.rerunAttemptJobIDs = all
379			p.ancestorAttemptJobIDs = make(container.Set[int64])
380			return nil
381		}
382	
383		byID := make(map[int64]*actions_model.ActionRunJob, len(p.templateJobs))
384		byAttemptJobID := make(map[int64]*actions_model.ActionRunJob, len(p.templateJobs))
385		for _, job := range p.templateJobs {
386			byID[job.ID] = job
387			byAttemptJobID[job.AttemptJobID] = job
388		}
389	
390		for _, job := range jobsToRerun {
391			if _, ok := byID[job.ID]; !ok {
392				return util.NewInvalidArgumentErrorf("job %q does not exist in the latest attempt", job.JobID)
393			}
394		}
395	
396		rerunSet := make(container.Set[int64])
397		ancestorSet := make(container.Set[int64])
398		queue := make([]*actions_model.ActionRunJob, 0, len(jobsToRerun))
399	
400		for _, job := range jobsToRerun {
401			j := byID[job.ID]
402			rerunSet.Add(j.AttemptJobID)
403			queue = append(queue, j)
404		}
405	
406		for len(queue) > 0 {
407			cur := queue[0]
408			queue = queue[1:]
409	
410			// same-scope downstream: siblings whose Needs reference cur.JobID join the rerun set
411			for _, candidate := range p.templateJobs {
412				if candidate.ParentJobID != cur.ParentJobID {
413					continue
414				}
415				if rerunSet.Contains(candidate.AttemptJobID) || ancestorSet.Contains(candidate.AttemptJobID) {
416					continue
417				}
418				if !slices.Contains(candidate.Needs, cur.JobID) {
419					continue
420				}
421				rerunSet.Add(candidate.AttemptJobID)
422				queue = append(queue, candidate)
423			}
424	
425			// escalate to parent caller as an ancestor so its own siblings get checked next round
426			if cur.ParentJobID == 0 {
427				continue
428			}
429			parent, ok := byID[cur.ParentJobID]
430			if !ok {
431				continue
432			}
433			if rerunSet.Contains(parent.AttemptJobID) || ancestorSet.Contains(parent.AttemptJobID) {
434				continue
435			}
436			ancestorSet.Add(parent.AttemptJobID)
437			queue = append(queue, parent)
438		}
439	
440		// remove entries whose parent-caller chain already has a rerunSet member
441		for atID := range ancestorSet {
442			cur := byAttemptJobID[atID]
443			for cur.ParentJobID != 0 {
444				parent, ok := byID[cur.ParentJobID]
445				if !ok {
446					break
447				}
448				if rerunSet.Contains(parent.AttemptJobID) {
449					delete(ancestorSet, atID)
450					break
451				}
452				cur = parent
453			}
454		}
455	
456		p.rerunAttemptJobIDs = rerunSet
457		p.ancestorAttemptJobIDs = ancestorSet
458		return nil
459	}
460	
461	// hasRerunDependency reports whether `job` has a needs-reference that points to a job which is itself being rerun (in rerunAttemptJobIDs)
462	// or is an ancestor caller whose subtree is being rerun (in ancestorAttemptJobIDs).
463	// Either case means `job` should start in Blocked status.
464	func (p *rerunPlan) hasRerunDependency(job *actions_model.ActionRunJob) bool {
465		if len(job.Needs) == 0 {
466			return false
467		}
468		needSet := container.SetOf(job.Needs...)
469		for _, sibling := range p.templateJobs {
470			if sibling.ParentJobID != job.ParentJobID {
471				continue
472			}
473			if !needSet.Contains(sibling.JobID) {
474				continue
475			}
476			if p.rerunAttemptJobIDs.Contains(sibling.AttemptJobID) || p.ancestorAttemptJobIDs.Contains(sibling.AttemptJobID) {
477				return true
478			}
479		}
480		return false
481	}
482	
483	// collectResetCallerDescendants walks p.templateJobs and returns the DB IDs of every transitive descendant of any reusable caller whose AttemptJobID is in p.rerunAttemptJobIDs.
484	// These descendants must NOT be cloned by execRerunPlan: the reset caller will re-insert them with template-matched AttemptJobIDs.
485	func (p *rerunPlan) collectResetCallerDescendants() container.Set[int64] {
486		out := make(container.Set[int64])
487		for _, tj := range p.templateJobs {
488			if !tj.IsReusableCaller || !p.rerunAttemptJobIDs.Contains(tj.AttemptJobID) {
489				continue
490			}
491			// If this caller's row ID is already in `out`, it means an outer caller has already covered its whole subtree.
492			// Skip the redundant walk.
493			if out.Contains(tj.ID) {
494				continue
495			}
496			for _, child := range actions_model.CollectAllDescendantJobs(tj, p.templateJobs) {
497				out.Add(child.ID)
498			}
499		}
500		return out
501	}
