52	func (specs SpecList) LoadRepos(ctx context.Context) error {
53		repoIDs := specs.GetRepoIDs()
54		repos, err := repo_model.GetRepositoriesMapByIDs(ctx, repoIDs)
55		if err != nil {
56			return err
57		}
58		for _, spec := range specs {
59			spec.Repo = repos[spec.RepoID]
60		}
61		return nil
62	}
