30	// MaxReusableCallLevels caps how deep a reusable workflow can nest:
31	// a top-level caller may have at most MaxReusableCallLevels nested callers below it.
32	const MaxReusableCallLevels = 9
33	
34	// loadReusableWorkflowSource resolves the workflow file referenced by a caller's `uses:` and returns its raw bytes,
35	// along with the (repo_id, commit_sha) the file was loaded from.
36	func loadReusableWorkflowSource(ctx context.Context, run *actions_model.ActionRun, caller *actions_model.ActionRunJob, ref *jobparser.UsesRef) (content []byte, sourceRepoID int64, sourceCommitSHA string, err error) {
37		if err := run.LoadAttributes(ctx); err != nil {
38			return nil, 0, "", err
39		}
40	
41		switch ref.Kind {
42		case jobparser.UsesKindLocalSameRepo:
43			// `./` is resolved against the workflow file containing the `uses:` - i.e. the caller's own source repo + commit.
44			callerRepo, err := repo_model.GetRepositoryByID(ctx, caller.WorkflowSourceRepoID)
45			if err != nil {
46				return nil, 0, "", fmt.Errorf("look up caller source repo %d: %w", caller.WorkflowSourceRepoID, err)
47			}
48			bytes, resolvedSHA, err := readWorkflowFromRepo(ctx, callerRepo, caller.WorkflowSourceCommitSHA, ref.Path)
49			if err != nil {
50				return nil, 0, "", err
51			}
52			return bytes, callerRepo.ID, resolvedSHA, nil
53	
54		case jobparser.UsesKindLocalCrossRepo:
55			repo, err := repo_model.GetRepositoryByOwnerAndName(ctx, ref.Owner, ref.Repo)
56			if err != nil {
57				return nil, 0, "", fmt.Errorf("look up cross-repo workflow source %q: %w", ref.Owner+"/"+ref.Repo, err)
58			}
59			ok, err := access_model.CanReadWorkflowCrossRepo(ctx, repo, run)
60			if err != nil {
61				return nil, 0, "", err
62			}
63			if !ok {
64				if run.IsScopedRun {
65					// A scoped workflow's cross-repo "uses:" is resolved with the consuming repo's read permission,
66					// so the referenced repo must be readable by every consumer. Make that explicit in the failure.
67					return nil, 0, "", fmt.Errorf("no permission to read reusable workflow %s/%s: a scoped workflow's cross-repo \"uses:\" is resolved with the consuming repository %q read permission", ref.Owner, ref.Repo, run.Repo.RelativePath())
68				}
69				return nil, 0, "", fmt.Errorf("no permission to read reusable workflow from %s/%s", ref.Owner, ref.Repo)
70			}
71			bytes, resolvedSHA, err := readWorkflowFromRepo(ctx, repo, ref.Ref, ref.Path)
72			if err != nil {
73				return nil, 0, "", err
74			}
75			return bytes, repo.ID, resolvedSHA, nil
76		}
77		return nil, 0, "", fmt.Errorf("unsupported uses kind %d", ref.Kind)
78	}
79	
80	// readWorkflowFromRepo loads a workflow file from `repo` at `refOrSHA` and returns its content plus the resolved commit SHA.
81	func readWorkflowFromRepo(ctx context.Context, repo *repo_model.Repository, refOrSHA, path string) ([]byte, string, error) {
82		gitRepo, err := gitrepo.OpenRepository(ctx, repo)
83		if err != nil {
84			return nil, "", fmt.Errorf("open repo %s: %w", repo.FullName(), err)
85		}
86		defer gitRepo.Close()
87	
88		commit, err := gitRepo.GetCommit(refOrSHA)
89		if err != nil {
90			return nil, "", fmt.Errorf("get commit %q in %s: %w", refOrSHA, repo.FullName(), err)
91		}
92		str, err := commit.GetFileContent(path, 1024*1024)
93		if err != nil {
94			return nil, "", fmt.Errorf("read %s@%s:%s: %w", repo.FullName(), refOrSHA, path, err)
95		}
96		return []byte(str), commit.ID.String(), nil
97	}
98	
99	// checkCallerChain walks `caller`'s ancestor chain (via ParentJobID) and:
100	//   - rejects cycles (caller.CallUses appearing in any ancestor's CallUses)
101	//   - enforces MaxReusableCallLevels on the number of ancestors above `caller`
102	//
103	// Cycle detection is intentionally *syntactic* (string equality on CallUses), not semantic.
104	// So `owner/repo/lib.yml@v1` and `owner/repo/lib.yml@refs/heads/v1` resolving to the same commit are NOT treated as the same node.
105	// Going semantic (Owner, Repo, Path, ResolvedSHA tuples) would require extra git reads.
106	func checkCallerChain(ctx context.Context, caller *actions_model.ActionRunJob) error {
107		if caller.ParentJobID == 0 {
108			return nil // top-level caller: depth 0, no ancestors to walk
109		}
110	
111		visited := make(container.Set[string])
112		visited.Add(caller.CallUses)
113	
114		depth := 0
115		current := caller
116		for current.ParentJobID != 0 {
117			next, err := actions_model.GetRunJobByRunAndID(ctx, current.RunID, current.ParentJobID)
118			if err != nil {
119				return fmt.Errorf("walk caller chain: %w", err)
120			}
121			current = next
122			depth++
123			if depth > MaxReusableCallLevels {
124				return fmt.Errorf("reusable workflow call exceeds the maximum nesting level of %d at %q", MaxReusableCallLevels, caller.CallUses)
125			}
126			if current.IsReusableCaller && current.CallUses != "" {
127				if visited.Contains(current.CallUses) {
128					return fmt.Errorf("reusable workflow call cycle detected: %q", current.CallUses)
129				}
130				visited.Add(current.CallUses)
131			}
132		}
133		return nil
134	}
135	
136	// expandReusableWorkflowCaller loads and parses the target reusable workflow and inserts the caller's direct child jobs.
137	// It expands only ONE level: a child that is itself a reusable caller is inserted Blocked and expanded later by a subsequent resolver pass.
138	// It does NOT schedule a follow-up resolver pass; the caller of this function is responsible for emitting.
139	//
140	// All call sites (PrepareRunAndInsert, execRerunPlan, checkJobsOfCurrentRunAttempt, ApproveRuns) invoke this inside their enclosing write transaction,
141	// because the caller row update and the child-row inserts must commit atomically.
142	// Be aware this is not cheap inside a tx: it does a git read, YAML parsing, and `${{ }}` expression evaluation.
143	// None of the call sites is hot: each caller is expanded once per attempt.
144	func expandReusableWorkflowCaller(ctx context.Context, run *actions_model.ActionRun, attempt *actions_model.ActionRunAttempt, caller *actions_model.ActionRunJob, vars map[string]string) error {
145		// Already expanded by an earlier call, skip
146		if caller.IsExpanded {
147			return nil
148		}
149	
150		// 1. Cycle + depth check via the ParentJobID chain.
151		if err := checkCallerChain(ctx, caller); err != nil {
152			return err
153		}
154	
155		// 2. Parse the caller's own job (Uses, With, RawSecrets) from its WorkflowPayload.
156		parsedJob, err := caller.ParseJob()
157		if err != nil {
158			return fmt.Errorf("parse caller job %d: %w", caller.ID, err)
159		}
160	
161		// 3. Resolve `uses` and load called-workflow source.
162		ref, err := ResolveUses(ctx, parsedJob.Uses)
163		if err != nil {
164			return fmt.Errorf("resolve uses %q: %w", parsedJob.Uses, err)
165		}
166		content, contentSourceRepoID, contentSourceCommitSHA, err := loadReusableWorkflowSource(ctx, run, caller, ref)
167		if err != nil {
168			return err
169		}
170	
171		// 4. Parse the called workflow's spec (used by both secret validation and input evaluation).
172		wcSpec, err := jobparser.ParseWorkflowCallSpec(content)
173		if err != nil {
174			return fmt.Errorf("parse called workflow spec: %w", err)
175		}
176	
177		// 5. Resolve caller's `secrets:` and validate it against the callee's schema.
178		inherit, secretsMap, err := jobparser.ParseCallerSecrets(parsedJob.RawSecrets)
179		if err != nil {
180			return fmt.Errorf("caller secrets %q: %w", caller.JobID, err)
181		}
182		// Under `secrets: inherit` the caller forwards all of its own secrets verbatim and does NOT name them individually,
183		// so required-secret presence cannot be verified at expansion time and a missing required secret will surface at job runtime.
184		// This matches GitHub Actions' behavior.
185		if !inherit {
186			if err := jobparser.ValidateCallerSecrets(wcSpec, secretsMap); err != nil {
187				return fmt.Errorf("caller %q secrets: %w", caller.JobID, err)
188			}
189		}
190		switch {
191		case inherit:
192			caller.CallSecrets = jobparser.SecretsInherit
193		case len(secretsMap) > 0:
194			mapBytes, err := json.Marshal(secretsMap)
195			if err != nil {
196				return fmt.Errorf("marshal caller secret map: %w", err)
197			}
198			caller.CallSecrets = string(mapBytes)
199		}
200		caller.ReusableWorkflowContent = content
201	
202		// 6. Evaluate caller's `with:`, then match against the callee schema.
203		workflowCallInputs := map[string]any{}
204		if len(wcSpec.Inputs) > 0 {
205			jobResults, err := findJobNeedsAndFillJobResults(ctx, caller)
206			if err != nil {
207				return fmt.Errorf("find caller needs: %w", err)
208			}
209			parentInputs, err := getInputsForJob(ctx, run, caller)
210			if err != nil {
211				return err
212			}
213			callerGitCtx := GenerateGiteaContext(ctx, run, attempt, caller)
214			evaluated, err := jobparser.EvaluateCallerWith(
215				caller.JobID, parsedJob,
216				callerGitCtx, jobResults, vars, parentInputs,
217			)
218			if err != nil {
219				return fmt.Errorf("evaluate caller with: %w", err)
220			}
221			workflowCallInputs, err = jobparser.MatchCallerInputsAgainstSpec(wcSpec, evaluated)
222			if err != nil {
223				return fmt.Errorf("caller %q inputs: %w", caller.JobID, err)
224			}
225		}
226	
227		// 7. Build CallPayload (persisted in step 9).
228		callPayload, err := (&api.WorkflowCallPayload{
229			Workflow:   run.WorkflowID,
230			Ref:        run.Ref,
231			Repository: convert.ToRepo(ctx, run.Repo, access_model.Permission{AccessMode: perm_model.AccessModeNone}),
232			Sender:     convert.ToUserWithAccessMode(ctx, run.TriggerUser, perm_model.AccessModeNone),
233			Inputs:     workflowCallInputs,
234		}).JSONPayload()
235		if err != nil {
236			return fmt.Errorf("build call payload: %w", err)
237		}
238	
239		// 8. Insert direct children of this caller.
240		existingChildren, err := actions_model.GetDirectChildJobsByParent(ctx, caller)
241		if err != nil {
242			return fmt.Errorf("get existing children of caller %d: %w", caller.ID, err)
243		}
244		if len(existingChildren) > 0 {
245			// Should not happen - child jobs cannot be expanded before the caller gets ready
246			return fmt.Errorf("invariant violation: caller %d has %d pre-existing children", caller.ID, len(existingChildren))
247		}
248		if err := insertCallerChildren(ctx, run, attempt, caller, content, contentSourceRepoID, contentSourceCommitSHA, vars, workflowCallInputs); err != nil {
249			return err
250		}
251	
252		// 9. Update caller-related cols.
253		caller.CallPayload = string(callPayload)
254		caller.IsExpanded = true
255		n, err := actions_model.UpdateRunJob(ctx, caller,
256			builder.Eq{"is_expanded": false},
257			"call_secrets", "reusable_workflow_content", "call_payload", "is_expanded")
258		if err != nil {
259			return fmt.Errorf("commit caller %d expansion: %w", caller.ID, err)
260		}
261		if n == 0 {
262			return fmt.Errorf("caller %d already expanded by another writer", caller.ID)
263		}
264		return nil
265	}
266	
267	// insertCallerChildren parses the called workflow with the caller's resolved inputs and inserts each parsed job.
268	func insertCallerChildren(ctx context.Context, run *actions_model.ActionRun, attempt *actions_model.ActionRunAttempt, caller *actions_model.ActionRunJob, content []byte, sourceRepoID int64, sourceCommitSHA string, vars map[string]string, inputs map[string]any) error {
269		// Parse the called workflow with the caller's `inputs`
270		gitCtx := GenerateGiteaContext(ctx, run, attempt, nil)
271		if event, ok := gitCtx["event"].(map[string]any); ok {
272			event["inputs"] = inputs
273		}
274		gitCtx["event_name"] = "workflow_call"
275	
276		childWorkflows, err := jobparser.Parse(content,
277			jobparser.WithVars(vars),
278			jobparser.WithGitContext(gitCtx.ToGitHubContext()),
279			jobparser.WithInputs(inputs),
280		)
281		if err != nil {
282			return fmt.Errorf("parse called workflow for caller %d: %w", caller.ID, err)
283		}
284		if len(childWorkflows) == 0 {
285			return fmt.Errorf("called workflow for caller %d (uses %q) has no jobs", caller.ID, caller.CallUses)
286		}
287	
288		priorChildren, err := actions_model.GetPriorAttemptChildrenByParent(ctx, run.ID, attempt.ID, caller.AttemptJobID)
289		if err != nil {
290			return fmt.Errorf("lookup prior-attempt children of caller %d: %w", caller.ID, err)
291		}
292	
293		for _, sw := range childWorkflows {
294			jobID, parsedChild := sw.Job()
295			if parsedChild == nil {
296				continue
297			}
298			needs := parsedChild.Needs()
299			if err := sw.SetJob(jobID, parsedChild.EraseNeeds()); err != nil {
300				return err
301			}
302			payload, err := sw.Marshal()
303			if err != nil {
304				return fmt.Errorf("marshal child %q under caller %d: %w", jobID, caller.ID, err)
305			}
306	
307			parsedChild.Name = util.EllipsisDisplayString(parsedChild.Name, 255)
308	
309			// AttemptJobID: prefer a prior-attempt match by (JobID, Name) and fall back to a fresh allocator value for newly-appearing logical jobs.
310			// The two-level key disambiguates matrix instances (same JobID, different Names) and distinct jobs that legally share the same Name (different JobIDs).
311			var attemptJobID int64
312			if priorChild, ok := priorChildren[jobID][parsedChild.Name]; ok {
313				attemptJobID = priorChild.AttemptJobID
314			} else {
315				attemptJobID, err = actions_model.GetNextAttemptJobID(ctx, run.ID)
316				if err != nil {
317					return fmt.Errorf("alloc attempt_job_id for child %q: %w", jobID, err)
318				}
319			}
320			child := &actions_model.ActionRunJob{
321				RunID:                   run.ID,
322				RunAttemptID:            attempt.ID,
323				RepoID:                  run.RepoID,
324				OwnerID:                 run.OwnerID,
325				CommitSHA:               run.CommitSHA,
326				IsForkPullRequest:       run.IsForkPullRequest,
327				Name:                    parsedChild.Name,
328				Attempt:                 attempt.Attempt,
329				WorkflowPayload:         payload,
330				JobID:                   jobID,
331				AttemptJobID:            attemptJobID,
332				Needs:                   needs,
333				RunsOn:                  parsedChild.RunsOn(),
334				ContinueOnError:         parsedChild.GetContinueOnError(),
335				Status:                  actions_model.StatusBlocked,
336				ParentJobID:             caller.ID,
337				WorkflowSourceRepoID:    sourceRepoID,
338				WorkflowSourceCommitSHA: sourceCommitSHA,
339			}
340			if perms := ExtractJobPermissionsFromWorkflow(sw, parsedChild); perms != nil {
341				child.TokenPermissions = perms
342			}
343			if parsedChild.Uses != "" {
344				child.IsReusableCaller = true
345				child.CallUses = parsedChild.Uses
346			}
347			if err := db.Insert(ctx, child); err != nil {
348				return fmt.Errorf("insert child %q under caller %d: %w", jobID, caller.ID, err)
349			}
350		}
351		return nil
352	}
353	
354	// ResolveUses normalizes and parses a reusable workflow `uses:` value.
355	// It first rewrites an absolute URL pointing to this instance into the cross-repo form (rejecting external URLs),
356	// then validates the syntax via jobparser.ParseUses.
357	func ResolveUses(ctx context.Context, uses string) (*jobparser.UsesRef, error) {
358		// Rewrite a local-instance URL to the equivalent cross-repo form "owner/repo/.gitea/workflows/file.yml@ref".
359		if strings.HasPrefix(uses, "http://") || strings.HasPrefix(uses, "https://") {
360			// ParseGiteaSiteURL returns nil for URLs that do not belong to this instance.
361			gsu := httplib.ParseGiteaSiteURL(ctx, uses)
362			if gsu == nil {
363				return nil, fmt.Errorf("unsupported reusable workflow URL %q: an absolute URL must point to this Gitea instance (%s)", uses, setting.AppURL)
364			}
365			// RoutePath is the instance-relative path (AppSubURL already stripped), e.g. "/owner/repo/.gitea/workflows/file.yml@ref".
366			uses = strings.TrimPrefix(gsu.RoutePath, "/")
367		}
368		ref, err := jobparser.ParseUses(uses)
369		if err != nil {
370			return nil, err
371		}
372		// jobparser only validates syntax; enforce the (instance-configurable) directory allowlist here.
373		if !actions_module.IsWorkflowOrScopedWorkflow(ref.Path) {
374			return nil, fmt.Errorf(`"uses:" path %q must be under a configured workflow directory (WORKFLOW_DIRS or SCOPED_WORKFLOW_DIRS)`, ref.Path)
375		}
376		return ref, nil
377	}
378

