29	// GenerateGiteaContext generate the gitea context without token and gitea_runtime_token.
30	// attempt and job can be nil when generating a context for parsing workflow-level expressions.
31	//
32	// The run_attempt value is resolved with the following precedence:
33	//  1. attempt.Attempt - the explicit attempt argument, or run.GetLatestAttempt() as a fallback
34	//  2. job.Attempt - only used when neither an explicit nor latest attempt is available
35	//  3. "1" - when none of the above apply (first-run parse time, before the first attempt exists)
36	func GenerateGiteaContext(ctx context.Context, run *actions_model.ActionRun, attempt *actions_model.ActionRunAttempt, job *actions_model.ActionRunJob) GiteaContext {
37		event := map[string]any{}
38		_ = json.Unmarshal([]byte(run.EventPayload), &event)
39	
40		baseRef := ""
41		headRef := ""
42		ref := run.Ref
43		sha := run.CommitSHA
44		if pullPayload, err := run.GetPullRequestEventPayload(); err == nil && pullPayload.PullRequest != nil && pullPayload.PullRequest.Base != nil && pullPayload.PullRequest.Head != nil {
45			baseRef = pullPayload.PullRequest.Base.Ref
46			headRef = pullPayload.PullRequest.Head.Ref
47	
48			// if the TriggerEvent is pull_request_target, ref and sha need to be set according to the base of pull request
49			// In GitHub's documentation, ref should be the branch or tag that triggered workflow. But when the TriggerEvent is pull_request_target,
50			// the ref will be the base branch.
51			if run.TriggerEvent == actions_module.GithubEventPullRequestTarget {
52				ref = git.BranchPrefix + pullPayload.PullRequest.Base.Name
53				sha = pullPayload.PullRequest.Base.Sha
54			}
55		}
56	
57		refName := git.RefName(ref)
58	
59		gitContext := GiteaContext{
60			// standard contexts, see https://docs.github.com/en/actions/learn-github-actions/contexts#github-context
61			"action":            "",                                       // string, The name of the action currently running, or the id of a step. GitHub removes special characters, and uses the name __run when the current step runs a script without an id. If you use the same action more than once in the same job, the name will include a suffix with the sequence number with underscore before it. For example, the first script you run will have the name __run, and the second script will be named __run_2. Similarly, the second invocation of actions/checkout will be actionscheckout2.
62			"action_path":       "",                                       // string, The path where an action is located. This property is only supported in composite actions. You can use this path to access files located in the same repository as the action.
63			"action_ref":        "",                                       // string, For a step executing an action, this is the ref of the action being executed. For example, v2.
64			"action_repository": "",                                       // string, For a step executing an action, this is the owner and repository name of the action. For example, actions/checkout.
65			"action_status":     "",                                       // string, For a composite action, the current result of the composite action.
66			"actor":             run.TriggerUser.Name,                     // string, The username of the user that triggered the initial workflow run. If the workflow run is a re-run, this value may differ from github.triggering_actor. Any workflow re-runs will use the privileges of github.actor, even if the actor initiating the re-run (github.triggering_actor) has different privileges.
67			"api_url":           setting.AppURL + "api/v1",                // string, The URL of the GitHub REST API.
68			"base_ref":          baseRef,                                  // string, The base_ref or target branch of the pull request in a workflow run. This property is only available when the event that triggers a workflow run is either pull_request or pull_request_target.
69			"env":               "",                                       // string, Path on the runner to the file that sets environment variables from workflow commands. This file is unique to the current step and is a different file for each step in a job. For more information, see "Workflow commands for GitHub Actions."
70			"event":             event,                                    // object, The full event webhook payload. You can access individual properties of the event using this context. This object is identical to the webhook payload of the event that triggered the workflow run, and is different for each event. The webhooks for each GitHub Actions event is linked in "Events that trigger workflows." For example, for a workflow run triggered by the push event, this object contains the contents of the push webhook payload.
71			"event_name":        run.TriggerEvent,                         // string, The name of the event that triggered the workflow run.
72			"event_path":        "",                                       // string, The path to the file on the runner that contains the full event webhook payload.
73			"graphql_url":       "",                                       // string, The URL of the GitHub GraphQL API.
74			"head_ref":          headRef,                                  // string, The head_ref or source branch of the pull request in a workflow run. This property is only available when the event that triggers a workflow run is either pull_request or pull_request_target.
75			"job":               "",                                       // string, The job_id of the current job.
76			"ref":               ref,                                      // string, The fully-formed ref of the branch or tag that triggered the workflow run. For workflows triggered by push, this is the branch or tag ref that was pushed. For workflows triggered by pull_request, this is the pull request merge branch. For workflows triggered by release, this is the release tag created. For other triggers, this is the branch or tag ref that triggered the workflow run. This is only set if a branch or tag is available for the event type. The ref given is fully-formed, meaning that for branches the format is refs/heads/<branch_name>, for pull requests it is refs/pull/<pr_number>/merge, and for tags it is refs/tags/<tag_name>. For example, refs/heads/feature-branch-1.
77			"ref_name":          refName.ShortName(),                      // string, The short ref name of the branch or tag that triggered the workflow run. This value matches the branch or tag name shown on GitHub. For example, feature-branch-1.
78			"ref_protected":     false,                                    // boolean, true if branch protections are configured for the ref that triggered the workflow run.
79			"ref_type":          string(refName.RefType()),                // string, The type of ref that triggered the workflow run. Valid values are branch or tag.
80			"path":              "",                                       // string, Path on the runner to the file that sets system PATH variables from workflow commands. This file is unique to the current step and is a different file for each step in a job. For more information, see "Workflow commands for GitHub Actions."
81			"repository":        run.Repo.OwnerName + "/" + run.Repo.Name, // string, The owner and repository name. For example, Codertocat/Hello-World.
82			"repository_owner":  run.Repo.OwnerName,                       // string, The repository owner's name. For example, Codertocat.
83			"repositoryUrl":     run.Repo.HTMLURL(),                       // string, The Git URL to the repository. For example, git://github.com/codertocat/hello-world.git.
84			"retention_days":    "",                                       // string, The number of days that workflow run logs and artifacts are kept.
85			"run_id":            strconv.FormatInt(run.ID, 10),            // string, A unique number for each workflow run within a repository. This number does not change if you re-run the workflow run.
86			"run_number":        strconv.FormatInt(run.Index, 10),         // string, A unique number for each run of a particular workflow in a repository. This number begins at 1 for the workflow's first run, and increments with each new run. This number does not change if you re-run the workflow run.
87			"run_attempt":       "",                                       // string, A unique number for each attempt of a particular workflow run in a repository. This number begins at 1 for the workflow run's first attempt, and increments with each re-run.
88			"secret_source":     "Actions",                                // string, The source of a secret used in a workflow. Possible values are None, Actions, Dependabot, or Codespaces.
89			"server_url":        setting.AppURL,                           // string, The URL of the GitHub server. For example: https://github.com.
90			"sha":               sha,                                      // string, The commit SHA that triggered the workflow. The value of this commit SHA depends on the event that triggered the workflow. For more information, see "Events that trigger workflows." For example, ffac537e6cbbf934b08745a378932722df287a53.
91			"triggering_actor":  "",                                       // string, The username of the user that initiated the workflow run. If the workflow run is a re-run, this value may differ from github.actor. Any workflow re-runs will use the privileges of github.actor, even if the actor initiating the re-run (github.triggering_actor) has different privileges.
92			"workflow":          run.WorkflowID,                           // string, The name of the workflow. If the workflow file doesn't specify a name, the value of this property is the full path of the workflow file in the repository.
93			"workspace":         "",                                       // string, The default working directory on the runner for steps, and the default location of your repository when using the checkout action.
94	
95			// additional contexts
96			"gitea_default_actions_url": setting.Actions.DefaultActionsURL.URL(),
97		}
98	
99		if job != nil {
100			gitContext["job"] = job.JobID
101			gitContext["run_attempt"] = strconv.FormatInt(job.Attempt, 10)
102	
103			if job.ParentJobID > 0 {
104				// Inject the caller's resolved workflow_call inputs into gitea.event.inputs.
105				// The rest of gitea.event stays as the caller's actual trigger event (push/pull_request/etc.)
106				// to match GitHub's semantics (see https://docs.github.com/en/actions/reference/workflows-and-actions/reusing-workflow-configurations#github-context).
107				// FIXME: If the run is triggered by "workflow_dispatch", the original inputs of "workflow_dispatch" will be overridden.
108				// If necessary, the caller can send these values to the called workflow via `with:`.
109				caller, err := actions_model.GetRunJobByRunAndID(ctx, job.RunID, job.ParentJobID)
110				if err != nil {
111					log.Error("GenerateGiteaContext: load caller job %d of job %d: %v", job.ParentJobID, job.ID, err)
112				} else if caller.CallPayload != "" {
113					var cp api.WorkflowCallPayload
114					if err := json.Unmarshal([]byte(caller.CallPayload), &cp); err != nil {
115						log.Error("GenerateGiteaContext: decode CallPayload of caller %d: %v", caller.ID, err)
116					} else if cp.Inputs != nil {
117						event["inputs"] = cp.Inputs
118					}
119				}
120	
121				// Override gitea.event_name to "workflow_call", so that the runner-side `getEvaluatorInputs` can get inputs from event["inputs"].
122				// https://gitea.com/gitea/runner/src/commit/0b9f251b6abb30d5f292a49cfe0c611f7c26d857/act/runner/expression.go#L509
123				// FIXME: The trade-off is that `${{ gitea.event_name }}` inside a reusable workflow's child job reads "workflow_call"
124				// instead of the caller's real trigger event name (push/pull_request/etc.) This is a small deviation from GitHub spec.
125				gitContext["event_name"] = "workflow_call"
126			}
127		}
128	
129		if attempt == nil {
130			if latestAttempt, has, err := run.GetLatestAttempt(ctx); err == nil && has {
131				attempt = latestAttempt
132			}
133		}
134	
135		if attempt != nil {
136			gitContext["run_attempt"] = strconv.FormatInt(attempt.Attempt, 10)
137			if err := attempt.LoadAttributes(ctx); err == nil {
138				gitContext["triggering_actor"] = attempt.TriggerUser.Name
139			}
140		}
141	
142		// Fallback for first-run parse time: no job, no attempt (LatestAttemptID==0). github.run_attempt
143		// is 1-based per the documented contract, so emit "1" rather than leaving it empty.
144		if gitContext["run_attempt"] == "" {
145			gitContext["run_attempt"] = "1"
146		}
147	
148		return gitContext
149	}
