855	// checkRunRerunAllowed checks whether a rerun is permitted for the given run,
856	// writing the appropriate JSON error to ctx and returning false when it is not.
857	func checkRunRerunAllowed(ctx *context_module.Context, run *actions_model.ActionRun) bool {
858		if !run.Status.IsDone() {
859			ctx.JSONError(ctx.Locale.Tr("actions.runs.not_done"))
860			return false
861		}
862		cfgUnit := ctx.Repo.Repository.MustGetUnit(ctx, unit.TypeActions)
863		cfg := cfgUnit.ActionsConfig()
864		disabled := cfg.IsWorkflowDisabled(run.WorkflowID)
865		if run.IsScopedRun {
866			optedOut, err := actions_model.IsScopedWorkflowOptedOut(ctx, cfg, ctx.Repo.Repository.OwnerID, run.WorkflowRepoID, run.WorkflowID)
867			if err != nil {
868				ctx.ServerError("IsScopedWorkflowOptedOut", err)
869				return false
870			}
871			disabled = optedOut
872		}
873		if disabled {
874			ctx.JSONError(ctx.Locale.Tr("actions.workflow.disabled"))
875			return false
876		}
877		return true
878	}
