16	func getWorkflowDispatchInputsFromRun(run *actions_model.ActionRun) (map[string]any, error) {
17		if run.Event != "workflow_dispatch" {
18			return map[string]any{}, nil
19		}
20		var payload api.WorkflowDispatchPayload
21		if err := json.Unmarshal([]byte(run.EventPayload), &payload); err != nil {
22			return nil, err
