27	// getInputsForJob returns the `inputs.*` top-level expression context for a job's evaluation.
28	//   - For top-level jobs, it falls back to the run's dispatch inputs (empty for non-dispatch events)
29	//   - For reusable workflow children (and nested callers), this is the direct parent caller's CallPayload.Inputs
30	func getInputsForJob(ctx context.Context, run *actions_model.ActionRun, job *actions_model.ActionRunJob) (map[string]any, error) {
31		if job.ParentJobID == 0 {
32			return getWorkflowDispatchInputsFromRun(run)
33		}
34	
35		caller, err := actions_model.GetRunJobByRunAndID(ctx, run.ID, job.ParentJobID)
36		if err != nil {
37			return nil, fmt.Errorf("load caller job %d: %w", job.ParentJobID, err)
38		}
39		if caller.CallPayload == "" {
40			// should not happen - a child job cannot reach this point if its caller's CallPayload hasn't been evaluated
41			return map[string]any{}, nil
42		}
43		var p api.WorkflowCallPayload
44		if err := json.Unmarshal([]byte(caller.CallPayload), &p); err != nil {
45			return nil, fmt.Errorf("decode caller %d payload: %w", caller.ID, err)
46		}
47		if p.Inputs == nil {
48			return map[string]any{}, nil
49		}
50		return p.Inputs, nil
51	}
