27	
28	func EnableOrDisableWorkflow(ctx *context.APIContext, workflowID string, isEnable bool) error {
29		workflow, err := convert.GetActionWorkflow(ctx, ctx.Repo.GitRepo, ctx.Repo.Repository, workflowID)
30		if err != nil {
31			return err
32		}
33	
34		cfgUnit := ctx.Repo.Repository.MustGetUnit(ctx, unit.TypeActions)
35		cfg := cfgUnit.ActionsConfig()
36	
37		if isEnable {
38			cfg.EnableWorkflow(workflow.ID)
39		} else {
40			cfg.DisableWorkflow(workflow.ID)
41		}
42	
43		return repo_model.UpdateRepoUnitConfig(ctx, cfgUnit)
44	}
45	
46	// DispatchActionWorkflow manually triggers a workflow_dispatch run.
47	// scopedWorkflowSourceRepoID selects the workflow source: 0 means a repo-level workflow in this repo; a non-zero value is the source repo of a scoped workflow.
48	func DispatchActionWorkflow(ctx reqctx.RequestContext, doer *user_model.User, repo *repo_model.Repository, gitRepo *git.Repository, workflowID, ref string, scopedWorkflowSourceRepoID int64, processInputs func(model *model.WorkflowDispatch, inputs map[string]any) error) (runID int64, _ error) {
49		if workflowID == "" {
50			return 0, util.ErrorWrapTranslatable(
51				util.NewNotExistErrorf("workflowID is empty"),
52				"actions.workflow.not_found", workflowID,
53			)
54		}
55	
56		if ref == "" {
57			return 0, util.ErrorWrapTranslatable(
58				util.NewNotExistErrorf("ref is empty"),
59				"form.target_ref_not_exist", ref,
60			)
61		}
62	
63		isScoped := scopedWorkflowSourceRepoID > 0
64	
65		cfgUnit := repo.MustGetUnit(ctx, unit.TypeActions)
66		cfg := cfgUnit.ActionsConfig()
67		var workflowDisabled bool
68		if isScoped {
69			var err error
70			if workflowDisabled, err = actions_model.IsScopedWorkflowOptedOut(ctx, cfg, repo.OwnerID, scopedWorkflowSourceRepoID, workflowID); err != nil {
71				return 0, err
72			}
73		} else {
74			workflowDisabled = cfg.IsWorkflowDisabled(workflowID)
75		}
76		if workflowDisabled {
77			return 0, util.ErrorWrapTranslatable(
78				util.NewPermissionDeniedErrorf("workflow is disabled"),
79				"actions.workflow.disabled",
80			)
81		}
82	
83		// get target commit of run from specified ref
