1	// Copyright 2023 The Gitea Authors. All rights reserved.
2	// SPDX-License-Identifier: MIT
3	
4	package actions
5	
6	import (
7		"context"
8		"errors"
9		"fmt"
10		"time"
11	
12		actions_model "gitea.dev/models/actions"
13		"gitea.dev/models/db"
14		actions_module "gitea.dev/modules/actions"
15		"gitea.dev/modules/container"
16		"gitea.dev/modules/log"
17		"gitea.dev/modules/setting"
18		"gitea.dev/modules/storage"
19		"gitea.dev/modules/timeutil"
20	
21		"xorm.io/builder"
22	)
23	
24	// Cleanup removes expired actions logs, data, artifacts and used ephemeral runners
25	func Cleanup(ctx context.Context) error {
26		// clean up expired artifacts
27		if err := CleanupArtifacts(ctx); err != nil {
28			return fmt.Errorf("cleanup artifacts: %w", err)
29		}
30	
31		// clean up old logs
32		if err := CleanupExpiredLogs(ctx); err != nil {
33			return fmt.Errorf("cleanup logs: %w", err)
34		}
35	
36		// clean up old ephemeral runners
37		if err := CleanupEphemeralRunners(ctx); err != nil {
38			return fmt.Errorf("cleanup old ephemeral runners: %w", err)
39		}
40	
41		return nil
42	}
43	
44	// CleanupArtifacts removes expired add need-deleted artifacts and set records expired status
45	func CleanupArtifacts(taskCtx context.Context) error {
46		if err := cleanExpiredArtifacts(taskCtx); err != nil {
47			return err
48		}
49		return cleanNeedDeleteArtifacts(taskCtx)
50	}
51	
52	func cleanExpiredArtifacts(taskCtx context.Context) error {
53		artifacts, err := actions_model.ListNeedExpiredArtifacts(taskCtx)
54		if err != nil {
55			return err
56		}
57		log.Info("Found %d expired artifacts", len(artifacts))
58		for _, artifact := range artifacts {
59			if err := actions_model.SetArtifactExpired(taskCtx, artifact.ID); err != nil {
60				log.Error("Cannot set artifact %d expired: %v", artifact.ID, err)
61				continue
62			}
63			if err := storage.ActionsArtifacts.Delete(artifact.StoragePath); err != nil {
64				log.Error("Cannot delete artifact %d: %v", artifact.ID, err)
65				// go on
66			}
67			log.Info("Artifact %d is deleted (due to expiration)", artifact.ID)
68		}
69		return nil
70	}
71	
72	// deleteArtifactBatchSize is the batch size of deleting artifacts
73	const deleteArtifactBatchSize = 100
74	
75	func cleanNeedDeleteArtifacts(taskCtx context.Context) error {
76		for {
77			artifacts, err := actions_model.ListPendingDeleteArtifacts(taskCtx, deleteArtifactBatchSize)
78			if err != nil {
79				return err
80			}
81			log.Info("Found %d artifacts pending deletion", len(artifacts))
82			for _, artifact := range artifacts {
83				if err := actions_model.SetArtifactDeleted(taskCtx, artifact.ID); err != nil {
84					log.Error("Cannot set artifact %d deleted: %v", artifact.ID, err)
85					continue
86				}
87				if err := storage.ActionsArtifacts.Delete(artifact.StoragePath); err != nil {
88					log.Error("Cannot delete artifact %d: %v", artifact.ID, err)
89					// go on
90				}
91				log.Info("Artifact %d is deleted (due to pending deletion)", artifact.ID)
92			}
93			if len(artifacts) < deleteArtifactBatchSize {
94				log.Debug("No more artifacts pending deletion")
95				break
96			}
97		}
98		return nil
99	}
100	
101	const deleteLogBatchSize = 100
102	
103	func removeTaskLog(ctx context.Context, task *actions_model.ActionTask) {
104		if err := actions_module.RemoveLogs(ctx, task.LogInStorage, task.LogFilename); err != nil {
105			log.Error("Failed to remove log %s (in storage %v) of task %v: %v", task.LogFilename, task.LogInStorage, task.ID, err)
106			// do not return error here, go on
107		}
108	}
109	
110	// CleanupExpiredLogs removes logs which are older than the configured retention time
111	func CleanupExpiredLogs(ctx context.Context) error {
112		olderThan := timeutil.TimeStampNow().AddDuration(-time.Duration(setting.Actions.LogRetentionDays) * 24 * time.Hour)
113	
114		count := 0
115		for {
116			tasks, err := actions_model.FindOldTasksToExpire(ctx, olderThan, deleteLogBatchSize)
117			if err != nil {
118				return fmt.Errorf("find old tasks: %w", err)
119			}
120			for _, task := range tasks {
121				removeTaskLog(ctx, task)
122				task.LogIndexes = nil // clear log indexes since it's a heavy field
123				task.LogExpired = true
124				if err := actions_model.UpdateTask(ctx, task, "log_indexes", "log_expired"); err != nil {
125					log.Error("Failed to update task %v: %v", task.ID, err)
126					// do not return error here, continue to next task
127					continue
128				}
129				count++
130				log.Trace("Removed log %s of task %v", task.LogFilename, task.ID)
131			}
132			if len(tasks) < deleteLogBatchSize {
133				break
134			}
135		}
136	
137		log.Info("Removed %d logs", count)
138		return nil
139	}
140	
141	// CleanupEphemeralRunners removes used ephemeral runners which are no longer able to process jobs
142	func CleanupEphemeralRunners(ctx context.Context) error {
143		subQuery := builder.Select("`action_runner`.id").
144			From(builder.Select("*").From("`action_runner`"), "`action_runner`"). // mysql needs this redundant subquery
145			Join("INNER", "`action_task`", "`action_task`.`runner_id` = `action_runner`.`id`").
146			Where(builder.Eq{"`action_runner`.`ephemeral`": true}).
147			And(builder.NotIn("`action_task`.`status`", actions_model.StatusWaiting, actions_model.StatusRunning, actions_model.StatusBlocked, actions_model.StatusCancelling))
148		b := builder.Delete(builder.In("id", subQuery)).From("`action_runner`")
149		res, err := db.GetEngine(ctx).Exec(b)
150		if err != nil {
151			return fmt.Errorf("find runners: %w", err)
152		}
153		affected, _ := res.RowsAffected()
154		log.Info("Removed %d runners", affected)
155		return nil
156	}
157	
158	// CleanupEphemeralRunnersByPickedTaskOfRepo removes all ephemeral runners that have active/finished tasks on the given repository
159	func CleanupEphemeralRunnersByPickedTaskOfRepo(ctx context.Context, repoID int64) error {
160		subQuery := builder.Select("`action_runner`.id").
161			From(builder.Select("*").From("`action_runner`"), "`action_runner`"). // mysql needs this redundant subquery
162			Join("INNER", "`action_task`", "`action_task`.`runner_id` = `action_runner`.`id`").
163			Where(builder.And(builder.Eq{"`action_runner`.`ephemeral`": true}, builder.Eq{"`action_task`.`repo_id`": repoID}))
164		b := builder.Delete(builder.In("id", subQuery)).From("`action_runner`")
165		res, err := db.GetEngine(ctx).Exec(b)
166		if err != nil {
167			return fmt.Errorf("find runners: %w", err)
168		}
169		affected, _ := res.RowsAffected()
170		log.Info("Removed %d runners", affected)
171		return nil
172	}
173	
174	// DeleteRun deletes workflow run, including all logs and artifacts.
175	func DeleteRun(ctx context.Context, run *actions_model.ActionRun) error {
176		if !run.Status.IsDone() {
177			return errors.New("run is not done")
178		}
179	
180		repoID := run.RepoID
181	
182		jobs, err := actions_model.GetAllRunJobsByRepoAndRunID(ctx, run.RepoID, run.ID)
183		if err != nil {
184			return err
185		}
186		jobIDs := container.FilterSlice(jobs, func(j *actions_model.ActionRunJob) (int64, bool) {
187			return j.ID, true
188		})
189		tasks := make(actions_model.TaskList, 0)
190		if len(jobIDs) > 0 {
191			if err := db.GetEngine(ctx).Where("repo_id = ?", repoID).In("job_id", jobIDs).Find(&tasks); err != nil {
192				return err
193			}
194		}
195	
196		artifacts, err := db.Find[actions_model.ActionArtifact](ctx, actions_model.FindArtifactsOptions{
197			RepoID: repoID,
198			RunID:  run.ID,
199		})
200		if err != nil {
201			return err
202		}
203	
204		var recordsToDelete []any
205	
206		recordsToDelete = append(recordsToDelete, &actions_model.ActionRun{
207			RepoID: repoID,
208			ID:     run.ID,
209		})
210		recordsToDelete = append(recordsToDelete, &actions_model.ActionRunAttempt{
211			RepoID: repoID,
212			RunID:  run.ID,
213		})
214		recordsToDelete = append(recordsToDelete, &actions_model.ActionRunJob{
215			RepoID: repoID,
216			RunID:  run.ID,
217		})
218		for _, tas := range tasks {
219			recordsToDelete = append(recordsToDelete, &actions_model.ActionTask{
220				RepoID: repoID,
221				ID:     tas.ID,
222			})
