1	// Copyright 2026 The Gitea Authors. All rights reserved.
2	// SPDX-License-Identifier: MIT
3	
4	package actions
5	
6	import (
7		"context"
8		"fmt"
9	
10		actions_model "gitea.dev/models/actions"
11		"gitea.dev/modules/actions/jobparser"
12		"gitea.dev/modules/json"
13		api "gitea.dev/modules/structs"
14	)
15	
16	func getWorkflowDispatchInputsFromRun(run *actions_model.ActionRun) (map[string]any, error) {
17		if run.Event != "workflow_dispatch" {
18			return map[string]any{}, nil
19		}
20		var payload api.WorkflowDispatchPayload
21		if err := json.Unmarshal([]byte(run.EventPayload), &payload); err != nil {
22			return nil, err
23		}
24		return payload.Inputs, nil
25	}
26	
27	// getInputsForJob returns the `inputs.*` top-level expression context for a job's evaluation.
28	//   - For top-level jobs, it falls back to the run's dispatch inputs (empty for non-dispatch events)
29	//   - For reusable workflow children (and nested callers), this is the direct parent caller's CallPayload.Inputs
30	func getInputsForJob(ctx context.Context, run *actions_model.ActionRun, job *actions_model.ActionRunJob) (map[string]any, error) {
31		if job.ParentJobID == 0 {
32			return getWorkflowDispatchInputsFromRun(run)
33		}
34	
35		caller, err := actions_model.GetRunJobByRunAndID(ctx, run.ID, job.ParentJobID)
36		if err != nil {
37			return nil, fmt.Errorf("load caller job %d: %w", job.ParentJobID, err)
38		}
39		if caller.CallPayload == "" {
40			// should not happen - a child job cannot reach this point if its caller's CallPayload hasn't been evaluated
41			return map[string]any{}, nil
42		}
43		var p api.WorkflowCallPayload
44		if err := json.Unmarshal([]byte(caller.CallPayload), &p); err != nil {
45			return nil, fmt.Errorf("decode caller %d payload: %w", caller.ID, err)
46		}
47		if p.Inputs == nil {
48			return map[string]any{}, nil
49		}
50		return p.Inputs, nil
51	}
52	
53	// evaluateJobIf evaluates a job's `if:`
54	func evaluateJobIf(ctx context.Context, run *actions_model.ActionRun, attempt *actions_model.ActionRunAttempt, job *actions_model.ActionRunJob, vars map[string]string, allNeedsSucceed bool) (bool, error) {
55		parsedJob, err := job.ParseJob()
56		if err != nil {
57			return false, err
58		}
59		// Empty `if:` reduces to implicit `success()` - true iff every need finished as Success.
60		if len(parsedJob.If.Value) == 0 {
61			return allNeedsSucceed, nil
62		}
63		jobResults, err := findJobNeedsAndFillJobResults(ctx, job)
64		if err != nil {
65			return false, err
66		}
67		inputs, err := getInputsForJob(ctx, run, job)
68		if err != nil {
69			return false, err
70		}
71		gitCtx := GenerateGiteaContext(ctx, run, attempt, job)
72		return jobparser.EvaluateJobIfExpression(job.JobID, parsedJob, gitCtx, jobResults, vars, inputs)
73	}
74	
75	func findJobNeedsAndFillJobResults(ctx context.Context, job *actions_model.ActionRunJob) (map[string]*jobparser.JobResult, error) {
76		taskNeeds, err := FindTaskNeeds(ctx, job)
77		if err != nil {
78			return nil, fmt.Errorf("find task needs: %w", err)
79		}
80		jobResults := make(map[string]*jobparser.JobResult, len(taskNeeds))
81		for jobID, taskNeed := range taskNeeds {
82			jobResult := &jobparser.JobResult{
83				Result:  taskNeed.Result.String(),
84				Outputs: taskNeed.Outputs,
85			}
86			jobResults[jobID] = jobResult
87		}
88		jobResults[job.JobID] = &jobparser.JobResult{
89			Needs: job.Needs,
90		}
91		return jobResults, nil
92	}
93

