19		api "gitea.dev/modules/structs"
20		"gitea.dev/modules/util"
21		"gitea.dev/services/context"
22		"gitea.dev/services/convert"
23	
24		"gitea.com/gitea/runner/act/model"
25		"go.yaml.in/yaml/v4"
26	)
27	
28	func EnableOrDisableWorkflow(ctx *context.APIContext, workflowID string, isEnable bool) error {
29		workflow, err := convert.GetActionWorkflow(ctx, ctx.Repo.GitRepo, ctx.Repo.Repository, workflowID)
30		if err != nil {
31			return err
32		}
33	
34		cfgUnit := ctx.Repo.Repository.MustGetUnit(ctx, unit.TypeActions)
35		cfg := cfgUnit.ActionsConfig()
36	
37		if isEnable {
38			cfg.EnableWorkflow(workflow.ID)
39		} else {
40			cfg.DisableWorkflow(workflow.ID)
41		}
42	
43		return repo_model.UpdateRepoUnitConfig(ctx, cfgUnit)
44	}
45	
46	// DispatchActionWorkflow manually triggers a workflow_dispatch run.
47	// scopedWorkflowSourceRepoID selects the workflow source: 0 means a repo-level workflow in this repo; a non-zero value is the source repo of a scoped workflow.
48	func DispatchActionWorkflow(ctx reqctx.RequestContext, doer *user_model.User, repo *repo_model.Repository, gitRepo *git.Repository, workflowID, ref string, scopedWorkflowSourceRepoID int64, processInputs func(model *model.WorkflowDispatch, inputs map[string]any) error) (runID int64, _ error) {
49		if workflowID == "" {
50			return 0, util.ErrorWrapTranslatable(
51				util.NewNotExistErrorf("workflowID is empty"),
52				"actions.workflow.not_found", workflowID,
53			)
54		}
55	
56		if ref == "" {
57			return 0, util.ErrorWrapTranslatable(
58				util.NewNotExistErrorf("ref is empty"),
59				"form.target_ref_not_exist", ref,
60			)
61		}
62	
63		isScoped := scopedWorkflowSourceRepoID > 0
64	
65		cfgUnit := repo.MustGetUnit(ctx, unit.TypeActions)
66		cfg := cfgUnit.ActionsConfig()
67		var workflowDisabled bool
68		if isScoped {
69			var err error
70			if workflowDisabled, err = actions_model.IsScopedWorkflowOptedOut(ctx, cfg, repo.OwnerID, scopedWorkflowSourceRepoID, workflowID); err != nil {
71				return 0, err
72			}
73		} else {
74			workflowDisabled = cfg.IsWorkflowDisabled(workflowID)
75		}
76		if workflowDisabled {
77			return 0, util.ErrorWrapTranslatable(
78				util.NewPermissionDeniedErrorf("workflow is disabled"),
79				"actions.workflow.disabled",
80			)
81		}
82	
83		// get target commit of run from specified ref
84		refName := git.RefName(ref)
85		var runTargetCommit *git.Commit
86		var err error
87		if refName.IsTag() {
88			runTargetCommit, err = gitRepo.GetTagCommit(refName.TagName())
89		} else if refName.IsBranch() {
90			runTargetCommit, err = gitRepo.GetBranchCommit(refName.BranchName())
91		} else {
92			refName = git.RefNameFromBranch(ref)
93			runTargetCommit, err = gitRepo.GetBranchCommit(ref)
94		}
95		if err != nil {
96			return 0, util.ErrorWrapTranslatable(
97				util.NewNotExistErrorf("ref %q doesn't exist", ref),
98				"form.target_ref_not_exist", ref,
99			)
100		}
101	
102		run := &actions_model.ActionRun{
103			Title:             runTargetCommit.MessageTitle(),
104			RepoID:            repo.ID,
105			Repo:              repo,
106			OwnerID:           repo.OwnerID,
107			WorkflowID:        workflowID,
108			TriggerUserID:     doer.ID,
109			TriggerUser:       doer,
110			Ref:               string(refName),
111			CommitSHA:         runTargetCommit.ID.String(),
112			IsForkPullRequest: false,
113			Event:             "workflow_dispatch",
114			TriggerEvent:      "workflow_dispatch",
115			Status:            actions_model.StatusWaiting,
116			// local dispatch: own repo at the target commit; the scoped path overrides these below
117			WorkflowRepoID:    repo.ID,
118			WorkflowCommitSHA: runTargetCommit.ID.String(),
119		}
120	
121		// resolve the workflow content and record its source on the run (scoped runs read from the source repo)
122		content, err := resolveDispatchWorkflowContent(ctx, repo, runTargetCommit, workflowID, scopedWorkflowSourceRepoID, isScoped, run)
123		if err != nil {
124			return 0, err
125		}
126	
127		singleWorkflow := &jobparser.SingleWorkflow{}
128		if err := yaml.Unmarshal(content, singleWorkflow); err != nil {
129			return 0, fmt.Errorf("failed to unmarshal workflow content: %w", err)
130		}
131		// get inputs from post
132		workflow := &model.Workflow{
133			RawOn: singleWorkflow.RawOn,
134		}
135		workflowDispatch := workflow.WorkflowDispatchConfig()
136		if workflowDispatch == nil {
137			return 0, util.ErrorWrapTranslatable(
138				util.NewInvalidArgumentErrorf("workflow %q has no workflow_dispatch event trigger", workflowID),
139				"actions.workflow.has_no_workflow_dispatch", workflowID,
140			)
141		}
142	
143		inputsWithDefaults := make(map[string]any)
144		if err = processInputs(workflowDispatch, inputsWithDefaults); err != nil {
145			return 0, err
146		}
147	
148		// ctx.Req.PostForm -> WorkflowDispatchPayload.Inputs -> ActionRun.EventPayload -> runner: ghc.Event
149		// https://docs.github.com/en/actions/learn-github-actions/contexts#github-context
150		// https://docs.github.com/en/webhooks/webhook-events-and-payloads#workflow_dispatch
151		workflowDispatchPayload := &api.WorkflowDispatchPayload{
152			Workflow:   workflowID,
153			Ref:        ref,
154			Repository: convert.ToRepo(ctx, repo, access_model.Permission{AccessMode: perm.AccessModeNone}),
155			Inputs:     inputsWithDefaults,
156			Sender:     convert.ToUserWithAccessMode(ctx, doer, perm.AccessModeNone),
157		}
158	
159		var eventPayload []byte
160		if eventPayload, err = workflowDispatchPayload.JSONPayload(); err != nil {
161			return 0, fmt.Errorf("JSONPayload: %w", err)
162		}
163		run.EventPayload = string(eventPayload)
164	
165		// Insert the action run and its associated jobs into the database
166		if err := PrepareRunAndInsert(ctx, content, run, inputsWithDefaults); err != nil {
167			return 0, fmt.Errorf("PrepareRun: %w", err)
168		}
169		return run.ID, nil
170	}
