172	// resolveDispatchWorkflowContent returns the YAML for a dispatched workflow and records its source on the run.
173	//   - Repo-level: from the consumer's runTargetCommit.
174	//   - Scoped: from the source repo's default branch.
175	func resolveDispatchWorkflowContent(ctx reqctx.RequestContext, repo *repo_model.Repository, runTargetCommit *git.Commit, workflowID string, sourceRepoID int64, isScoped bool, run *actions_model.ActionRun) ([]byte, error) {
176		if isScoped {
177			return resolveScopedDispatchContent(ctx, repo, sourceRepoID, workflowID, run)
178		}
179	
180		_, entries, err := actions.ListWorkflows(runTargetCommit)
181		if err != nil {
182			return nil, err
183		}
184		for _, e := range entries {
185			if e.Name() == workflowID {
186				return actions.GetContentFromEntry(e)
187			}
188		}
189		return nil, util.ErrorWrapTranslatable(
190			util.NewNotExistErrorf("workflow %q doesn't exist", workflowID),
191			"actions.workflow.not_found", workflowID,
192		)
193	}
194	
195	func resolveScopedDispatchContent(ctx reqctx.RequestContext, repo *repo_model.Repository, sourceRepoID int64, workflowID string, run *actions_model.ActionRun) ([]byte, error) {
196		// the source must be an effective scoped source for this consumer repo
197		effective, err := actions_model.IsScopedWorkflowSourceEffective(ctx, repo.OwnerID, sourceRepoID)
198		if err != nil {
199			return nil, err
200		}
201		if !effective {
202			return nil, util.ErrorWrapTranslatable(
203				util.NewNotExistErrorf("scoped workflow source %d is not effective for this repository", sourceRepoID),
204				"actions.workflow.not_found", workflowID,
205			)
206		}
207	
208		sourceRepo, err := repo_model.GetRepositoryByID(ctx, sourceRepoID)
209		if err != nil {
210			return nil, err
211		}
212	
213		sha, parsed, err := LoadParsedScopedWorkflows(ctx, sourceRepo)
214		if err != nil {
215			return nil, err
216		}
217		for _, p := range parsed {
218			if p.EntryName == workflowID {
219				run.WorkflowRepoID = sourceRepo.ID
220				run.WorkflowCommitSHA = sha
221				run.IsScopedRun = true
222				return p.Content, nil
223			}
224		}
225		return nil, util.ErrorWrapTranslatable(
226			util.NewNotExistErrorf("scoped workflow %q doesn't exist", workflowID),
227			"actions.workflow.not_found", workflowID,
228		)
229	}
