158	// CleanupEphemeralRunnersByPickedTaskOfRepo removes all ephemeral runners that have active/finished tasks on the given repository
159	func CleanupEphemeralRunnersByPickedTaskOfRepo(ctx context.Context, repoID int64) error {
160		subQuery := builder.Select("`action_runner`.id").
161			From(builder.Select("*").From("`action_runner`"), "`action_runner`"). // mysql needs this redundant subquery
162			Join("INNER", "`action_task`", "`action_task`.`runner_id` = `action_runner`.`id`").
163			Where(builder.And(builder.Eq{"`action_runner`.`ephemeral`": true}, builder.Eq{"`action_task`.`repo_id`": repoID}))
164		b := builder.Delete(builder.In("id", subQuery)).From("`action_runner`")
165		res, err := db.GetEngine(ctx).Exec(b)
166		if err != nil {
167			return fmt.Errorf("find runners: %w", err)
168		}
169		affected, _ := res.RowsAffected()
170		log.Info("Removed %d runners", affected)
171		return nil
172	}
