174	// DeleteRun deletes workflow run, including all logs and artifacts.
175	func DeleteRun(ctx context.Context, run *actions_model.ActionRun) error {
176		if !run.Status.IsDone() {
177			return errors.New("run is not done")
178		}
179	
180		repoID := run.RepoID
181	
182		jobs, err := actions_model.GetAllRunJobsByRepoAndRunID(ctx, run.RepoID, run.ID)
183		if err != nil {
184			return err
185		}
186		jobIDs := container.FilterSlice(jobs, func(j *actions_model.ActionRunJob) (int64, bool) {
187			return j.ID, true
188		})
189		tasks := make(actions_model.TaskList, 0)
190		if len(jobIDs) > 0 {
191			if err := db.GetEngine(ctx).Where("repo_id = ?", repoID).In("job_id", jobIDs).Find(&tasks); err != nil {
192				return err
193			}
194		}
195	
196		artifacts, err := db.Find[actions_model.ActionArtifact](ctx, actions_model.FindArtifactsOptions{
197			RepoID: repoID,
198			RunID:  run.ID,
199		})
200		if err != nil {
201			return err
202		}
203	
204		var recordsToDelete []any
205	
206		recordsToDelete = append(recordsToDelete, &actions_model.ActionRun{
207			RepoID: repoID,
208			ID:     run.ID,
209		})
210		recordsToDelete = append(recordsToDelete, &actions_model.ActionRunAttempt{
211			RepoID: repoID,
212			RunID:  run.ID,
213		})
214		recordsToDelete = append(recordsToDelete, &actions_model.ActionRunJob{
215			RepoID: repoID,
216			RunID:  run.ID,
217		})
218		for _, tas := range tasks {
219			recordsToDelete = append(recordsToDelete, &actions_model.ActionTask{
220				RepoID: repoID,
221				ID:     tas.ID,
222			})
223			recordsToDelete = append(recordsToDelete, &actions_model.ActionTaskStep{
224				RepoID: repoID,
225				TaskID: tas.ID,
226			})
227			recordsToDelete = append(recordsToDelete, &actions_model.ActionTaskOutput{
228				TaskID: tas.ID,
229			})
230		}
231		recordsToDelete = append(recordsToDelete, &actions_model.ActionArtifact{
232			RepoID: repoID,
233			RunID:  run.ID,
234		})
235		recordsToDelete = append(recordsToDelete, &actions_model.ActionRunJobSummary{
236			RepoID: repoID,
237			RunID:  run.ID,
238		})
239	
240		if err := db.WithTx(ctx, func(ctx context.Context) error {
241			// TODO: Deleting task records could break current ephemeral runner implementation. This is a temporary workaround suggested by ChristopherHX.
242			// Since you delete potentially the only task an ephemeral act_runner has ever run, please delete the affected runners first.
243			// one of
244			//    call cleanup ephemeral runners first
245			//    delete affected ephemeral act_runners
246			//    I would make ephemeral runners fully delete directly before formally finishing the task
247			//
248			// See also: https://github.com/go-gitea/gitea/pull/34337#issuecomment-2862222788
249			if err := CleanupEphemeralRunners(ctx); err != nil {
250				return err
251			}
252			return db.DeleteBeans(ctx, recordsToDelete...)
253		}); err != nil {
254			return err
255		}
256	
257		actions_model.UpdateRepoRunsNumbers(ctx, repoID)
258	
259		// Delete files on storage
260		for _, tas := range tasks {
261			removeTaskLog(ctx, tas)
262		}
263		for _, art := range artifacts {
264			if err := storage.ActionsArtifacts.Delete(art.StoragePath); err != nil {
265				log.Error("remove artifact file %q: %v", art.StoragePath, err)
266			}
267		}
268	
269		return nil
270	}
