   156	func GetSecretsOfTask(ctx context.Context, task *actions_model.ActionTask) (map[string]string, error) {
   157		baseSecrets := map[string]string{}
   158	
   159		baseSecrets["GITHUB_TOKEN"] = task.Token
   160		baseSecrets["GITEA_TOKEN"] = task.Token
   161	
   162		if task.Job.Run.IsForkPullRequest && task.Job.Run.TriggerEvent != actions_module.GithubEventPullRequestTarget {
   163			// ignore secrets for fork pull request, except GITHUB_TOKEN and GITEA_TOKEN which are automatically generated.
   164			// for the tasks triggered by pull_request_target event, they could access the secrets because they will run in the context of the base branch
   165			// see the documentation: https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#pull_request_target
   166			return baseSecrets, nil
   167		}
   168	
   169		ownerSecrets, err := db.Find[Secret](ctx, FindSecretsOptions{OwnerID: task.Job.Run.Repo.OwnerID})
   170		if err != nil {
   171			log.Error("find secrets of owner %v: %v", task.Job.Run.Repo.OwnerID, err)
   172			return nil, err
   173		}
   174		repoSecrets, err := db.Find[Secret](ctx, FindSecretsOptions{RepoID: task.Job.Run.RepoID})
   175		if err != nil {
   176			log.Error("find secrets of repo %v: %v", task.Job.Run.RepoID, err)
   177			return nil, err
   178		}
   179	
   180		for _, secret := range append(ownerSecrets, repoSecrets...) {
   181			v, err := secret_module.DecryptSecret(setting.SecretKey, secret.Data)
   182			if err != nil {
   183				log.Error("Unable to decrypt Actions secret %v %q, maybe SECRET_KEY is wrong: %v", secret.ID, secret.Name, err)
   184				continue
   185			}
   186			baseSecrets[secret.Name] = v
   187		}
   188	
   189		return getScopedSecretsForJob(ctx, task.Job, baseSecrets)
   190	}
   191	
   192	// getScopedSecretsForJob walks up the caller chain (ParentJobID) and applies
   193	// each caller's secrets policy:
   194	//   - "secrets: inherit" passes the parent scope's secrets through unchanged.
   195	//   - explicit mapping {alias: SOURCE} only forwards the named secrets, plus the auto-generated tokens.
   196	//
   197	// For top-level jobs (ParentJobID == 0) the base secrets are returned as-is.
   198	func getScopedSecretsForJob(ctx context.Context, job *actions_model.ActionRunJob, baseSecrets map[string]string) (map[string]string, error) {
   199		if job.ParentJobID == 0 {
   200			return baseSecrets, nil
   201		}
   202	
   203		caller, err := actions_model.GetRunJobByRunAndID(ctx, job.RunID, job.ParentJobID)
   204		if err != nil {
   205			return nil, fmt.Errorf("load caller job %d: %w", job.ParentJobID, err)
   206		}
   207	
   208		parentScope, err := getScopedSecretsForJob(ctx, caller, baseSecrets)
   209		if err != nil {
   210			return nil, err
   211		}
   212	
   213		if caller.CallSecrets == jobparser.SecretsInherit {
   214			return parentScope, nil
   215		}
   216	
   217		// Empty or explicit-mapping path: only auto-tokens + (any) mapped aliases are exposed.
   218		scoped := map[string]string{
   219			"GITHUB_TOKEN": baseSecrets["GITHUB_TOKEN"],
   220			"GITEA_TOKEN":  baseSecrets["GITEA_TOKEN"],
