59	func isWorkflowInDirs(path string, dirs []string) bool {
60		if (!strings.HasSuffix(path, ".yaml")) && (!strings.HasSuffix(path, ".yml")) {
61			return false
62		}
63	
64		for _, workflowDir := range dirs {
65			if strings.HasPrefix(path, workflowDir+"/") {
66				return true
67			}
68		}
69		return false
70	}
