76	func listWorkflowsInDirs(commit *git.Commit, dirs []string) (string, git.Entries, error) {
77		var tree *git.Tree
78		var err error
79		var workflowDir string
80		for _, workflowDir = range dirs {
81			tree, err = commit.SubTree(workflowDir)
82			if err == nil {
83				break
84			}
85			if !git.IsErrNotExist(err) {
86				return "", nil, err
87			}
88		}
89		if tree == nil {
90			return "", nil, nil
91		}
92	
93		entries, err := tree.ListEntriesRecursiveFast()
94		if err != nil {
95			return "", nil, err
96		}
97	
98		ret := make(git.Entries, 0, len(entries))
99		for _, entry := range entries {
100			if strings.HasSuffix(entry.Name(), ".yml") || strings.HasSuffix(entry.Name(), ".yaml") {
101				ret = append(ret, entry)
102			}
103		}
104		return workflowDir, ret, nil
105	}
