143	// WorkflowDisplayName returns a workflow's display name: its `name:` if non-blank, otherwise the base file name.
144	// This is the value used as the workflow segment of its commit-status context.
145	func WorkflowDisplayName(file string, content []byte) string {
146		displayName := path.Base(file)
147		if wfs, err := jobparser.Parse(content); err == nil && len(wfs) > 0 {
148			if name := strings.TrimSpace(wfs[0].Name); name != "" {
149				displayName = name
150			}
151		}
