155	// WorkflowStatusContextName builds a workflow job's commit-status context name: "<display> / <job> (<event>)".
156	func WorkflowStatusContextName(displayName, jobName, event string) string {
157		return strings.TrimSpace(fmt.Sprintf("%s / %s (%s)", displayName, jobName, event))
158	}
