166	// so its context can serve as a required status check.
167	// TODO: this allowlist duplicates the truth in services/actions.getCommitStatusEventNameAndCommitID, which decides the actual event string and whether a status is posted.
168	// The two are kept in sync by hand and can drift; unify them into a single source so adding a status-producing event in one place automatically updates the other.
169	func ShouldEventCreateCommitStatus(event string) bool {
170		switch event {
171		case "push", "pull_request", "pull_request_target", "pull_request_review", "pull_request_review_comment", "release":
172			return true
