177	func DetectWorkflows(
178		gitRepo *git.Repository,
179		commit *git.Commit,
180		triggedEvent webhook_module.HookEventType,
181		payload api.Payloader,
182		detectSchedule bool,
183	) (workflows, schedules, filtered []*DetectedWorkflow, err error) {
184		_, entries, err := ListWorkflows(commit)
185		if err != nil {
186			return nil, nil, nil, err
187		}
188	
189		for _, entry := range entries {
190			content, err := GetContentFromEntry(entry)
191			if err != nil {
192				return nil, nil, nil, err
193			}
194	
195			// one workflow may have multiple events
196			events, err := GetEventsFromContent(content)
197			if err != nil {
198				log.Warn("ignore invalid workflow %q: %v", entry.Name(), err)
199				continue
200			}
201			for _, evt := range events {
202				log.Trace("detect workflow %q for event %#v matching %q", entry.Name(), evt, triggedEvent)
203				if evt.IsSchedule() {
204					if detectSchedule {
205						dwf := &DetectedWorkflow{
206							EntryName:    entry.Name(),
207							TriggerEvent: evt,
208							Content:      content,
209						}
210						schedules = append(schedules, dwf)
211					}
212				} else {
213					dwf := &DetectedWorkflow{
214						EntryName:    entry.Name(),
215						TriggerEvent: evt,
216						Content:      content,
217					}
218					switch detectWorkflowMatch(gitRepo, commit, triggedEvent, payload, evt) {
219					case detectMatched:
220						workflows = append(workflows, dwf)
221					case detectFilteredOut:
222						filtered = append(filtered, dwf)
223					case detectNotApplicable:
224					}
225				}
226			}
227		}
228	
229		return workflows, schedules, filtered, nil
230	}
