232	func DetectScheduledWorkflows(gitRepo *git.Repository, commit *git.Commit) ([]*DetectedWorkflow, error) {
233		_, entries, err := ListWorkflows(commit)
234		if err != nil {
235			return nil, err
236		}
237	
238		wfs := make([]*DetectedWorkflow, 0, len(entries))
239		for _, entry := range entries {
240			content, err := GetContentFromEntry(entry)
241			if err != nil {
242				return nil, err
243			}
244	
245			// one workflow may have multiple events
246			events, err := GetEventsFromContent(content)
247			if err != nil {
248				log.Warn("ignore invalid workflow %q: %v", entry.Name(), err)
249				continue
250			}
251			for _, evt := range events {
252				if evt.IsSchedule() {
253					log.Trace("detect scheduled workflow: %q", entry.Name())
254					dwf := &DetectedWorkflow{
255						EntryName:    entry.Name(),
256						TriggerEvent: evt,
257						Content:      content,
258					}
259					wfs = append(wfs, dwf)
260				}
261			}
262		}
263	
264		return wfs, nil
265	}
