267	func detectWorkflowMatch(gitRepo *git.Repository, commit *git.Commit, triggedEvent webhook_module.HookEventType, payload api.Payloader, evt *jobparser.Event) detectResult {
268		if !canGithubEventMatch(evt.Name, triggedEvent) {
269			return detectNotApplicable
270		}
271	
272		switch triggedEvent {
273		case // events with no activity types
274			webhook_module.HookEventCreate,
275			webhook_module.HookEventDelete,
276			webhook_module.HookEventFork,
277			webhook_module.HookEventWiki,
278			webhook_module.HookEventSchedule:
279			if len(evt.Acts()) != 0 {
280				log.Warn("Ignore unsupported %s event arguments %v", triggedEvent, evt.Acts())
281			}
282			// no special filter parameters for these events, just return true if name matched
283			return detectMatched
284	
285		case // push
286			webhook_module.HookEventPush:
287			return matchPushEvent(commit, payload.(*api.PushPayload), evt)
288	
289		case // issues
290			webhook_module.HookEventIssues,
291			webhook_module.HookEventIssueAssign,
292			webhook_module.HookEventIssueLabel,
293			webhook_module.HookEventIssueMilestone:
294			if matchIssuesEvent(payload.(*api.IssuePayload), evt) {
295				return detectMatched
296			}
297			return detectNotApplicable
298	
299		case // issue_comment
300			webhook_module.HookEventIssueComment,
301			// `pull_request_comment` is same as `issue_comment`
302			// See https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#pull_request_comment-use-issue_comment
303			webhook_module.HookEventPullRequestComment:
304			if matchIssueCommentEvent(payload.(*api.IssueCommentPayload), evt) {
305				return detectMatched
306			}
307			return detectNotApplicable
308	
309		case // pull_request
310			webhook_module.HookEventPullRequest,
311			webhook_module.HookEventPullRequestSync,
312			webhook_module.HookEventPullRequestAssign,
313			webhook_module.HookEventPullRequestLabel,
314			webhook_module.HookEventPullRequestReviewRequest,
315			webhook_module.HookEventPullRequestMilestone:
316			return matchPullRequestEvent(gitRepo, commit, payload.(*api.PullRequestPayload), evt)
317	
318		case // pull_request_review
319			webhook_module.HookEventPullRequestReviewApproved,
320			webhook_module.HookEventPullRequestReviewRejected:
321			if matchPullRequestReviewEvent(payload.(*api.PullRequestPayload), evt) {
322				return detectMatched
323			}
324			return detectNotApplicable
325	
326		case // pull_request_review_comment
327			webhook_module.HookEventPullRequestReviewComment:
328			if matchPullRequestReviewCommentEvent(payload.(*api.PullRequestPayload), evt) {
329				return detectMatched
330			}
331			return detectNotApplicable
332	
333		case // release
334			webhook_module.HookEventRelease:
335			if matchReleaseEvent(payload.(*api.ReleasePayload), evt) {
336				return detectMatched
337			}
338			return detectNotApplicable
339	
340		case // registry_package
341			webhook_module.HookEventPackage:
342			if matchPackageEvent(payload.(*api.PackagePayload), evt) {
343				return detectMatched
344			}
345			return detectNotApplicable
346	
347		case // workflow_run
348			webhook_module.HookEventWorkflowRun:
349			if matchWorkflowRunEvent(payload.(*api.WorkflowRunPayload), evt) {
350				return detectMatched
351			}
352			return detectNotApplicable
353	
354		default:
355			log.Warn("unsupported event %q", triggedEvent)
356			return detectNotApplicable
357		}
358	}
