360	func matchPushEvent(commit *git.Commit, pushPayload *api.PushPayload, evt *jobparser.Event) detectResult {
361		// with no special filter parameters
362		if len(evt.Acts()) == 0 {
363			return detectMatched
364		}
365	
366		matchTimes := 0
367		hasBranchFilter := false
368		hasTagFilter := false
369		refName := git.RefName(pushPayload.Ref)
370		// all acts conditions should be satisfied
371		for cond, vals := range evt.Acts() {
372			switch cond {
373			case "branches":
374				hasBranchFilter = true
375				if !refName.IsBranch() {
376					break
377				}
378				patterns, err := workflowpattern.CompilePatterns(vals...)
379				if err != nil {
380					break
381				}
382				if !workflowpattern.Skip(patterns, []string{refName.BranchName()}) {
383					matchTimes++
384				}
385			case "branches-ignore":
386				hasBranchFilter = true
387				if !refName.IsBranch() {
388					break
389				}
390				patterns, err := workflowpattern.CompilePatterns(vals...)
391				if err != nil {
392					break
393				}
394				if !workflowpattern.Filter(patterns, []string{refName.BranchName()}) {
395					matchTimes++
396				}
397			case "tags":
398				hasTagFilter = true
399				if !refName.IsTag() {
400					break
401				}
402				patterns, err := workflowpattern.CompilePatterns(vals...)
403				if err != nil {
404					break
405				}
406				if !workflowpattern.Skip(patterns, []string{refName.TagName()}) {
407					matchTimes++
408				}
409			case "tags-ignore":
410				hasTagFilter = true
411				if !refName.IsTag() {
412					break
413				}
414				patterns, err := workflowpattern.CompilePatterns(vals...)
415				if err != nil {
416					break
417				}
418				if !workflowpattern.Filter(patterns, []string{refName.TagName()}) {
419					matchTimes++
420				}
421			case "paths":
422				if refName.IsTag() {
423					matchTimes++
424					break
425				}
426				filesChanged, err := commit.GetFilesChangedSinceCommit(pushPayload.Before)
427				if err != nil {
428					log.Error("GetFilesChangedSinceCommit [commit_sha1: %s]: %v", commit.ID.String(), err)
429					return detectNotApplicable
430				}
431				patterns, err := workflowpattern.CompilePatterns(vals...)
432				if err != nil {
433					break
434				}
435				if !workflowpattern.Skip(patterns, filesChanged) {
436					matchTimes++
437				}
438			case "paths-ignore":
439				if refName.IsTag() {
440					matchTimes++
441					break
442				}
443				filesChanged, err := commit.GetFilesChangedSinceCommit(pushPayload.Before)
444				if err != nil {
445					log.Error("GetFilesChangedSinceCommit [commit_sha1: %s]: %v", commit.ID.String(), err)
446					return detectNotApplicable
447				}
448				patterns, err := workflowpattern.CompilePatterns(vals...)
449				if err != nil {
450					break
451				}
452				if !workflowpattern.Filter(patterns, filesChanged) {
453					matchTimes++
454				}
455			default:
456				log.Warn("push event unsupported condition %q", cond)
457			}
458		}
459		// if both branch and tag filter are defined in the workflow only one needs to match
460		if hasBranchFilter && hasTagFilter {
461			matchTimes++
462		}
463		if matchTimes == len(evt.Acts()) {
464			return detectMatched
465		}
466		return detectFilteredOut
467	}
468	
469	func matchIssuesEvent(issuePayload *api.IssuePayload, evt *jobparser.Event) bool {
470		// with no special filter parameters
471		if len(evt.Acts()) == 0 {
472			return true
473		}
474	
475		matchTimes := 0
476		// all acts conditions should be satisfied
477		for cond, vals := range evt.Acts() {
478			switch cond {
479			case "types":
480				// See https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#issues
481				// Actions with the same name:
482				// opened, edited, closed, reopened, assigned, unassigned, milestoned, demilestoned
483				// Actions need to be converted:
484				// label_updated -> labeled (when adding) or unlabeled (when removing)
485				// label_cleared -> unlabeled
486				// Unsupported activity types:
487				// deleted, transferred, pinned, unpinned, locked, unlocked
488	
489				actions := []string{}
490				switch issuePayload.Action {
491				case api.HookIssueLabelUpdated:
492					if len(issuePayload.Changes.AddedLabels) > 0 {
493						actions = append(actions, "labeled")
494					}
495					if len(issuePayload.Changes.RemovedLabels) > 0 {
496						actions = append(actions, "unlabeled")
497					}
498				case api.HookIssueLabelCleared:
499					actions = append(actions, "unlabeled")
500				default:
501					actions = append(actions, string(issuePayload.Action))
502				}
503	
504				for _, val := range vals {
505					if slices.ContainsFunc(actions, glob.MustCompile(val, '/').Match) {
506						matchTimes++
507						break
508					}
509				}
510			default:
511				log.Warn("issue event unsupported condition %q", cond)
512			}
513		}
514		return matchTimes == len(evt.Acts())
515	}
516	
517	func matchPullRequestEvent(gitRepo *git.Repository, commit *git.Commit, prPayload *api.PullRequestPayload, evt *jobparser.Event) detectResult {
518		acts := evt.Acts()
519		activityTypeMatched := false
520		matchTimes := 0
521	
522		if vals, ok := acts["types"]; !ok {
523			// defaultly, only pull request `opened`, `reopened` and `synchronized` will trigger workflow
524			// See https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#pull_request
525			activityTypeMatched = prPayload.Action == api.HookIssueSynchronized || prPayload.Action == api.HookIssueOpened || prPayload.Action == api.HookIssueReOpened
526		} else {
527			// See https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#pull_request
528			// Actions with the same name:
529			// opened, edited, closed, reopened, assigned, unassigned, review_requested, review_request_removed, milestoned, demilestoned
530			// Actions need to be converted:
531			// synchronized -> synchronize
532			// label_updated -> labeled
533			// label_cleared -> unlabeled
534			// Unsupported activity types:
535			// converted_to_draft, ready_for_review, locked, unlocked, auto_merge_enabled, auto_merge_disabled, enqueued, dequeued
536	
537			action := prPayload.Action
538			switch action {
539			case api.HookIssueSynchronized:
540				action = "synchronize"
541			case api.HookIssueLabelUpdated:
542				action = "labeled"
543			case api.HookIssueLabelCleared:
544				action = "unlabeled"
545			}
546			log.Trace("matching pull_request %s with %v", action, vals)
547			for _, val := range vals {
548				if glob.MustCompile(val, '/').Match(string(action)) {
549					activityTypeMatched = true
550					matchTimes++
551					break
552				}
553			}
554		}
555	
556		var (
557			headCommit = commit
558			err        error
559		)
560		if evt.Name == GithubEventPullRequestTarget && (len(acts["paths"]) > 0 || len(acts["paths-ignore"]) > 0) {
561			headCommit, err = gitRepo.GetCommit(prPayload.PullRequest.Head.Sha)
562			if err != nil {
563				log.Error("GetCommit [ref: %s]: %v", prPayload.PullRequest.Head.Sha, err)
564				return detectNotApplicable
565			}
566		}
567	
568		// all acts conditions should be satisfied
569		for cond, vals := range acts {
570			switch cond {
571			case "types":
572				// types have been checked
573				continue
574			case "branches":
575				refName := git.RefName(prPayload.PullRequest.Base.Ref)
576				patterns, err := workflowpattern.CompilePatterns(vals...)
577				if err != nil {
578					break
579				}
580				if !workflowpattern.Skip(patterns, []string{refName.ShortName()}) {
581					matchTimes++
582				}
583			case "branches-ignore":
584				refName := git.RefName(prPayload.PullRequest.Base.Ref)
585				patterns, err := workflowpattern.CompilePatterns(vals...)
586				if err != nil {
587					break
588				}
589				if !workflowpattern.Filter(patterns, []string{refName.ShortName()}) {
590					matchTimes++
591				}
592			case "paths":
593				filesChanged, err := headCommit.GetFilesChangedSinceCommit(prPayload.PullRequest.MergeBase)
594				if err != nil {
595					log.Error("GetFilesChangedSinceCommit [commit_sha1: %s]: %v", headCommit.ID.String(), err)
596					return detectNotApplicable
597				}
598				patterns, err := workflowpattern.CompilePatterns(vals...)
599				if err != nil {
600					break
601				}
602				if !workflowpattern.Skip(patterns, filesChanged) {
603					matchTimes++
604				}
605			case "paths-ignore":
606				filesChanged, err := headCommit.GetFilesChangedSinceCommit(prPayload.PullRequest.MergeBase)
607				if err != nil {
608					log.Error("GetFilesChangedSinceCommit [commit_sha1: %s]: %v", headCommit.ID.String(), err)
609					return detectNotApplicable
610				}
611				patterns, err := workflowpattern.CompilePatterns(vals...)
612				if err != nil {
613					break
614				}
615				if !workflowpattern.Filter(patterns, filesChanged) {
616					matchTimes++
617				}
618			default:
619				log.Warn("pull request event unsupported condition %q", cond)
620			}
621		}
622		if !activityTypeMatched {
623			return detectNotApplicable
624		}
625		if matchTimes != len(evt.Acts()) {
626			return detectFilteredOut
627		}
628		return detectMatched
629	}
