631	func matchIssueCommentEvent(issueCommentPayload *api.IssueCommentPayload, evt *jobparser.Event) bool {
632		// with no special filter parameters
633		if len(evt.Acts()) == 0 {
634			return true
635		}
636	
637		matchTimes := 0
638		// all acts conditions should be satisfied
639		for cond, vals := range evt.Acts() {
640			switch cond {
641			case "types":
642				// See https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#issue_comment
643				// Actions with the same name:
644				// created, edited, deleted
645				// Actions need to be converted:
646				// NONE
647				// Unsupported activity types:
648				// NONE
649	
650				for _, val := range vals {
651					if glob.MustCompile(val, '/').Match(string(issueCommentPayload.Action)) {
652						matchTimes++
653						break
654					}
655				}
656			default:
657				log.Warn("issue comment event unsupported condition %q", cond)
658			}
659		}
660		return matchTimes == len(evt.Acts())
661	}
