674				// See https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#pull_request_review
675				// Activity types with the same name:
676				// NONE
677				// Activity types need to be converted:
678				// reviewed -> submitted
679				// reviewed -> edited
680				// Unsupported activity types:
681				// dismissed
682	
683				actions := make([]string, 0)
684				if prPayload.Action == api.HookIssueReviewed {
685					// the `reviewed` HookIssueAction can match the two activity types: `submitted` and `edited`
686					// See https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#pull_request_review
687					actions = append(actions, "submitted", "edited")
688				}
