    31		case webhook_module.HookEventDelete:
    32			// GitHub "delete" event
    33			// https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#delete
    34			return true
    35		case webhook_module.HookEventFork:
    36			// GitHub "fork" event
    37			// https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#fork
    38			return true
    39		case webhook_module.HookEventIssueComment:
    40			// GitHub "issue_comment" event
    41			// https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#issue_comment
    42			return true
    43		case webhook_module.HookEventPullRequestComment:
    44			// GitHub "pull_request_comment" event
    45			// https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#pull_request_comment-use-issue_comment
    46			return true
    47		case webhook_module.HookEventWiki:
    48			// GitHub "gollum" event
    49			// https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#gollum
    50			return true
    51		case webhook_module.HookEventSchedule:
    52			// GitHub "schedule" event
    53			// https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#schedule
    54			return true
    55		case webhook_module.HookEventIssues,
    56			webhook_module.HookEventIssueAssign,
    57			webhook_module.HookEventIssueLabel,
    58			webhook_module.HookEventIssueMilestone:
    59			// Github "issues" event
    60			// https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#issues
    61			return true
    62		case webhook_module.HookEventWorkflowRun:
    63			// GitHub "workflow_run" event
    64			// https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#workflow_run
    65			return true
    66		}
    67	
    68		return false
    69	}
