    71	// canGithubEventMatch check if the input Github event can match any Gitea event.
    72	func canGithubEventMatch(eventName string, triggedEvent webhook_module.HookEventType) bool {
    73		switch eventName {
    74		case GithubEventRegistryPackage:
    75			return triggedEvent == webhook_module.HookEventPackage
    76	
    77		// See https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#gollum
    78		case GithubEventGollum:
    79			return triggedEvent == webhook_module.HookEventWiki
    80	
    81		case GithubEventIssues:
    82			switch triggedEvent {
    83			case webhook_module.HookEventIssues,
    84				webhook_module.HookEventIssueAssign,
    85				webhook_module.HookEventIssueLabel,
    86				webhook_module.HookEventIssueMilestone:
    87				return true
    88	
    89			default:
    90				return false
    91			}
    92	
    93		case GithubEventPullRequest, GithubEventPullRequestTarget:
    94			switch triggedEvent {
    95			case webhook_module.HookEventPullRequest,
    96				webhook_module.HookEventPullRequestSync,
    97				webhook_module.HookEventPullRequestAssign,
    98				webhook_module.HookEventPullRequestLabel,
    99				webhook_module.HookEventPullRequestReviewRequest,
   100				webhook_module.HookEventPullRequestMilestone:
   101				return true
   102	
   103			default:
   104				return false
   105			}
   106	
   107		case GithubEventPullRequestReview:
   108			switch triggedEvent {
   109			case webhook_module.HookEventPullRequestReviewApproved,
   110				webhook_module.HookEventPullRequestReviewComment,
   111				webhook_module.HookEventPullRequestReviewRejected:
   112				return true
   113	
   114			default:
   115				return false
   116			}
   117	
   118		case GithubEventSchedule:
   119			return triggedEvent == webhook_module.HookEventSchedule
   120	
   121		case GithubEventIssueComment:
   122			// https://docs.github.com/en/actions/using-workflows/events-that-trigger-workflows#pull_request_comment-use-issue_comment
   123			return triggedEvent == webhook_module.HookEventIssueComment ||
   124				triggedEvent == webhook_module.HookEventPullRequestComment
   125	
   126		default:
   127			return eventName == string(triggedEvent)
   128		}
   129	}
