317	// workflowCallEvent is only fired by another workflow's `uses:`, so it is excluded from trigger detection.
318	const workflowCallEvent = "workflow_call"
319	
320	func ParseRawOn(rawOn *yaml.Node) ([]*Event, error) {
321		switch rawOn.Kind {
322		case yaml.ScalarNode:
323			var val string
324			err := rawOn.Decode(&val)
325			if err != nil {
326				return nil, err
327			}
328			if val == workflowCallEvent {
329				return []*Event{}, nil
330			}
331			return []*Event{
332				{Name: val},
333			}, nil
334		case yaml.SequenceNode:
335			var val []any
336			err := rawOn.Decode(&val)
337			if err != nil {
338				return nil, err
339			}
340			res := make([]*Event, 0, len(val))
341			for _, v := range val {
342				switch t := v.(type) {
343				case string:
344					if t == workflowCallEvent {
345						continue
346					}
347					res = append(res, &Event{Name: t})
348				default:
349					return nil, fmt.Errorf("invalid type %T", t)
350				}
351			}
352			return res, nil
353		case yaml.MappingNode:
354			events, triggers, err := parseMappingNode[yaml.Node](rawOn)
355			if err != nil {
356				return nil, err
357			}
358			res := make([]*Event, 0, len(events))
359			for i, k := range events {
360				if k == workflowCallEvent {
361					continue
362				}
363				v := triggers[i]
364				switch v.Kind {
365				case yaml.ScalarNode:
366					res = append(res, &Event{
367						Name: k,
368					})
369				case yaml.SequenceNode:
370					var t []any
371					err := v.Decode(&t)
372					if err != nil {
373						return nil, err
374					}
375					schedules := make([]map[string]string, len(t))
376					if k == "schedule" {
377						for i, tt := range t {
378							vv, ok := tt.(map[string]any)
379							if !ok {
380								return nil, fmt.Errorf("unknown on type(schedule): %#v", v)
381							}
382							schedules[i] = make(map[string]string, len(vv))
383							for k, vvv := range vv {
384								var ok bool
385								if schedules[i][k], ok = vvv.(string); !ok {
386									return nil, fmt.Errorf("unknown on type(schedule): %#v", v)
387								}
388							}
389						}
390					}
391	
392					if len(schedules) == 0 {
393						schedules = nil
394					}
395					res = append(res, &Event{
396						Name:      k,
397						schedules: schedules,
398					})
399				case yaml.MappingNode:
400					acts := make(map[string][]string, len(v.Content)/2)
401					var inputs []WorkflowDispatchInput
402					expectedKey := true
403					var act string
404					for _, content := range v.Content {
405						if expectedKey {
406							if content.Kind != yaml.ScalarNode {
407								return nil, fmt.Errorf("key type not string: %#v", content)
408							}
409							act = ""
410							err := content.Decode(&act)
411							if err != nil {
412								return nil, err
413							}
414						} else {
415							switch content.Kind {
416							case yaml.SequenceNode:
417								var t []string
418								err := content.Decode(&t)
419								if err != nil {
420									return nil, err
421								}
422								acts[act] = t
423							case yaml.ScalarNode:
424								var t string
425								err := content.Decode(&t)
426								if err != nil {
427									return nil, err
428								}
429								acts[act] = []string{t}
430							case yaml.MappingNode:
431								if k != "workflow_dispatch" || act != "inputs" {
432									return nil, fmt.Errorf("map should only for workflow_dispatch but %s: %#v", act, content)
433								}
434	
435								var key string
436								for i, vv := range content.Content {
437									if i%2 == 0 {
438										if vv.Kind != yaml.ScalarNode {
439											return nil, fmt.Errorf("key type not string: %#v", vv)
440										}
441										key = ""
442										if err := vv.Decode(&key); err != nil {
443											return nil, err
444										}
445									} else {
446										if vv.Kind != yaml.MappingNode {
447											return nil, fmt.Errorf("key type not map(%s): %#v", key, vv)
448										}
449	
450										input := WorkflowDispatchInput{}
451										if err := vv.Decode(&input); err != nil {
452											return nil, err
453										}
454										input.Name = key
455										inputs = append(inputs, input)
456									}
457								}
458							default:
459								return nil, fmt.Errorf("unknown on type: %#v", content)
460							}
461						}
462						expectedKey = !expectedKey
463					}
464					if len(inputs) == 0 {
465						inputs = nil
466					}
467					if len(acts) == 0 {
468						acts = nil
469					}
470					res = append(res, &Event{
471						Name:   k,
472						acts:   acts,
473						inputs: inputs,
474					})
475				default:
476					return nil, fmt.Errorf("unknown on type: %v", v.Kind)
477				}
478			}
479			return res, nil
480		default:
481			return nil, fmt.Errorf("unknown on type: %v", rawOn.Kind)
482		}
483	}
484	
485	func EvaluateJobIfExpression(jobID string, job *Job, gitCtx map[string]any, results map[string]*JobResult, vars map[string]string, inputs map[string]any) (bool, error) {
486		actJob := &model.Job{
487			Strategy: &model.Strategy{
488				FailFastString:    job.Strategy.FailFastString,
489				MaxParallelString: job.Strategy.MaxParallelString,
490				RawMatrix:         job.Strategy.RawMatrix,
491			},
492		}
493		evaluator := NewExpressionEvaluator(NewInterpeter(jobID, actJob, nil, toGitContext(gitCtx), results, vars, inputs))
494		expr, err := rewriteSubExpression(job.If.Value, false)
495		if err != nil {
496			return false, err
497		}
498		result, err := evaluator.evaluate(expr, exprparser.DefaultStatusCheckSuccess)
499		if err != nil {
500			return false, err
501		}
502		return exprparser.IsTruthy(result), nil
503	}
504	
505	// parseMappingNode parse a mapping node and preserve order.
506	func parseMappingNode[T any](node *yaml.Node) ([]string, []T, error) {
507		if node.Kind != yaml.MappingNode {
508			return nil, nil, errors.New("input node is not a mapping node")
509		}
510	
511		var scalars []string
512		var datas []T
513		expectKey := true
514		for _, item := range node.Content {
515			if expectKey {
516				if item.Kind != yaml.ScalarNode {
517					return nil, nil, fmt.Errorf("not a valid scalar node: %v", item.Value)
518				}
519				scalars = append(scalars, item.Value)
520				expectKey = false
521			} else {
522				var val T
523				if err := item.Decode(&val); err != nil {
524					return nil, nil, err
525				}
526				datas = append(datas, val)
527				expectKey = true
528			}
529		}
530	
531		if len(scalars) != len(datas) {
532			return nil, nil, fmt.Errorf("invalid definition of on: %v", node.Value)
533		}
534	
535		return scalars, datas, nil
536	}
537	
538	func asString(v any) string {
539		if v == nil {
540			return ""
541		} else if s, ok := v.(string); ok {
542			return s
543		}
544		return ""
545	}
