35	func (w *SingleWorkflow) jobs() ([]string, []*Job, error) {
36		ids, jobs, err := parseMappingNode[*Job](&w.RawJobs)
37		if err != nil {
38			return nil, nil, err
39		}
40	
41		for _, job := range jobs {
42			steps := make([]*Step, 0, len(job.Steps))
43			for _, s := range job.Steps {
44				if s != nil {
45					steps = append(steps, s)
46				}
47			}
48			job.Steps = steps
49		}
50	
51		return ids, jobs, nil
52	}
53	
54	func (w *SingleWorkflow) SetJob(id string, job *Job) error {
55		m := map[string]*Job{
56			id: job,
57		}
58		var buf bytes.Buffer
59		encoder := yaml.NewEncoder(&buf)
60		encoder.SetIndent(2)
61		if err := encoder.Encode(m); err != nil {
62			return err
63		}
64		encoder.Close()
65	
66		node := yaml.Node{}
67		if err := yaml.Unmarshal(buf.Bytes(), &node); err != nil {
68			return err
69		}
70		if len(node.Content) != 1 || node.Content[0].Kind != yaml.MappingNode {
71			return fmt.Errorf("can not set job: %s", buf.String())
72		}
73		w.RawJobs = *node.Content[0]
74		return nil
75	}
