244	func EvaluateConcurrency(rc *model.RawConcurrency, jobID string, job *Job, gitCtx map[string]any, results map[string]*JobResult, vars map[string]string, inputs map[string]any) (string, bool, error) {
245		actJob := &model.Job{}
246		if job != nil {
247			actJob.Strategy = &model.Strategy{
248				FailFastString:    job.Strategy.FailFastString,
249				MaxParallelString: job.Strategy.MaxParallelString,
250				RawMatrix:         job.Strategy.RawMatrix,
251			}
252			actJob.Strategy.FailFast = actJob.Strategy.GetFailFast()
253			actJob.Strategy.MaxParallel = actJob.Strategy.GetMaxParallel()
254		}
255	
256		matrix := make(map[string]any)
257		matrixes, err := actJob.GetMatrixes()
258		if err != nil {
259			return "", false, err
260		}
261		if len(matrixes) > 0 {
262			matrix = matrixes[0]
263		}
264	
265		evaluator := NewExpressionEvaluator(NewInterpeter(jobID, actJob, matrix, toGitContext(gitCtx), results, vars, inputs))
266		var node yaml.Node
267		if err := node.Encode(rc); err != nil {
268			return "", false, fmt.Errorf("failed to encode concurrency: %w", err)
269		}
270		if err := evaluator.EvaluateYamlNode(&node); err != nil {
271			return "", false, fmt.Errorf("failed to evaluate concurrency: %w", err)
272		}
273		var evaluated model.RawConcurrency
274		if err := node.Decode(&evaluated); err != nil {
275			return "", false, fmt.Errorf("failed to unmarshal evaluated concurrency: %w", err)
276		}
277		if evaluated.RawExpression != "" {
278			return evaluated.RawExpression, false, nil
279		}
280		return evaluated.Group, evaluated.CancelInProgress == "true", nil
281	}
