// Copyright 2026 The Gitea Authors. All rights reserved.
// SPDX-License-Identifier: MIT

package actions

import (
	"context"
	"fmt"
	"testing"
	"time"

	runnerv1 "gitea.dev/actions-proto-go/runner/v1"
	actions_model "gitea.dev/models/actions"
	"gitea.dev/models/db"
	repo_model "gitea.dev/models/repo"
	"gitea.dev/models/unittest"
	user_model "gitea.dev/models/user"
	"gitea.dev/modules/queue"
	"gitea.dev/modules/setting"
	"gitea.dev/modules/timeutil"

	"github.com/stretchr/testify/require"
)

var probeIndex int64 = 9700

func probePayload(jobID string) []byte {
	return fmt.Appendf(nil, "name: test\non: push\njobs:\n  %s:\n    runs-on: ubuntu-latest\n    steps:\n      - run: echo\n", jobID)
}

func probeSetup(t *testing.T) (context.Context, *repo_model.Repository, *user_model.User) {
	require.NoError(t, unittest.PrepareTestDatabase())
	setting.Actions.AbandonedJobTimeout = 24 * time.Hour
	setting.Actions.EndlessTaskTimeout = 3 * time.Hour
	setting.Actions.ZombieTaskTimeout = 10 * time.Minute
	if jobEmitterQueue == nil {
		jobEmitterQueue = queue.CreateUniqueQueue(t.Context(), "probe_ready_job", func(items ...*jobUpdate) []*jobUpdate { return nil })
		require.NotNil(t, jobEmitterQueue)
	}
	repo := unittest.AssertExistsAndLoadBean(t, &repo_model.Repository{ID: 4})
	doer := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 1})
	return t.Context(), repo, doer
}

func probeRun(t *testing.T, status actions_model.Status, mut func(*actions_model.ActionRun)) (*actions_model.ActionRun, *actions_model.ActionRunAttempt) {
	ctx := t.Context()
	probeIndex++
	run := &actions_model.ActionRun{
		RepoID: 4, OwnerID: 1, TriggerUserID: 1, WorkflowID: "test.yml", Index: probeIndex, Ref: "refs/heads/main",
		Event: "push", TriggerEvent: "push", EventPayload: "{}", Status: status, WorkflowRepoID: 4,
	}
	if mut != nil {
		mut(run)
	}
	require.NoError(t, db.Insert(ctx, run))
	attempt := &actions_model.ActionRunAttempt{RepoID: 4, RunID: run.ID, Attempt: 1, TriggerUserID: 1, Status: status}
	require.NoError(t, db.Insert(ctx, attempt))
	_, err := db.Exec(ctx, "UPDATE `action_run` SET latest_attempt_id = ? WHERE id = ?", attempt.ID, run.ID)
	require.NoError(t, err)
	return probeReloadRun(t, run.ID), attempt
}

func probeReloadRun(t *testing.T, id int64) *actions_model.ActionRun {
	run, err := actions_model.GetRunByRepoAndID(t.Context(), 4, id)
	require.NoError(t, err)
	return run
}

func probeJob(t *testing.T, run *actions_model.ActionRun, attempt *actions_model.ActionRunAttempt, n int64, jobID string, status actions_model.Status, mut func(*actions_model.ActionRunJob)) *actions_model.ActionRunJob {
	job := &actions_model.ActionRunJob{
		RunID: run.ID, RunAttemptID: attempt.ID, AttemptJobID: n, Attempt: 1, RepoID: 4, OwnerID: 1,
		JobID: jobID, Name: jobID, Status: status, WorkflowPayload: probePayload(jobID), RunsOn: []string{"ubuntu-latest"},
	}
	if mut != nil {
		mut(job)
	}
	require.NoError(t, db.Insert(t.Context(), job))
	return job
}

func probeTask(t *testing.T, job *actions_model.ActionRunJob, runnerID int64, started timeutil.TimeStamp) *actions_model.ActionTask {
	ctx := t.Context()
	task := &actions_model.ActionTask{JobID: job.ID, RunnerID: runnerID, Status: actions_model.StatusRunning, RepoID: 4, OwnerID: 1, Started: started, LogFilename: fmt.Sprintf("probe/%d.log", job.ID)}
	task.GenerateAndFillToken()
	require.NoError(t, db.Insert(ctx, task))
	_, err := db.Exec(ctx, "UPDATE `action_run_job` SET task_id = ?, status = ? WHERE id = ?", task.ID, actions_model.StatusRunning, job.ID)
	require.NoError(t, err)
	job.TaskID, job.Status = task.ID, actions_model.StatusRunning
	return task
}

func probeJobNow(t *testing.T, id int64) *actions_model.ActionRunJob {
	return unittest.AssertExistsAndLoadBean(t, &actions_model.ActionRunJob{ID: id})
}

func probeAttemptJobs(t *testing.T, run *actions_model.ActionRun) string {
	run = probeReloadRun(t, run.ID)
	jobs, err := actions_model.GetRunJobsByRunAndAttemptID(t.Context(), run.ID, run.LatestAttemptID)
	require.NoError(t, err)
	out := fmt.Sprintf("run=%s need_approval=%v jobs:", run.Status, run.NeedApproval)
	for _, j := range jobs {
		out += fmt.Sprintf(" %s=%s", j.JobID, j.Status)
	}
	return out
}

// 1: "re-run failed jobs" when nothing failed.
func TestProbeRerunFailedNothingFailed(t *testing.T) {
	ctx, repo, doer := probeSetup(t)
	run, attempt := probeRun(t, actions_model.StatusSuccess, nil)
	probeJob(t, run, attempt, 1, "build", actions_model.StatusSuccess, func(j *actions_model.ActionRunJob) { j.TaskID = 9001 })
	probeJob(t, run, attempt, 2, "deploy", actions_model.StatusSuccess, func(j *actions_model.ActionRunJob) { j.TaskID = 9002; j.Needs = []string{"build"} })
	jobs, _ := actions_model.GetRunJobsByRunAndAttemptID(ctx, run.ID, attempt.ID)
	failed := GetFailedJobsForRerun(jobs)
	newAttempt, err := RerunWorkflowRunJobs(ctx, repo, run, doer, failed)
	t.Logf("1: failed jobs selected=%d rerun err=%v new attempt=%v", len(failed), err, newAttempt != nil)
	t.Logf("1: after: %s", probeAttemptJobs(t, run))
}

// 2: "re-run failed jobs" when one job inside a called workflow failed.
func TestProbeRerunFailedInsideCaller(t *testing.T) {
	tmpl := actions_model.ActionJobList{
		{ID: 1, AttemptJobID: 1, JobID: "lint", Status: actions_model.StatusSuccess},
		{ID: 2, AttemptJobID: 2, JobID: "pipeline", Status: actions_model.StatusFailure, IsReusableCaller: true, IsExpanded: true},
		{ID: 3, AttemptJobID: 3, JobID: "build", Status: actions_model.StatusSuccess, ParentJobID: 2},
		{ID: 4, AttemptJobID: 4, JobID: "test", Status: actions_model.StatusFailure, ParentJobID: 2},
		{ID: 5, AttemptJobID: 5, JobID: "publish", Status: actions_model.StatusSuccess, ParentJobID: 2},
	}
	show := func(label string, sel []*actions_model.ActionRunJob) {
		p := &rerunPlan{templateJobs: tmpl}
		require.NoError(t, p.expandRerunJobIDs(sel))
		skip := p.collectResetCallerDescendants()
		out := ""
		for _, j := range tmpl {
			switch {
			case p.rerunAttemptJobIDs.Contains(j.AttemptJobID) || skip.Contains(j.ID):
				out += fmt.Sprintf(" %s(was %s)=RERUN", j.JobID, j.Status)
			default:
				out += fmt.Sprintf(" %s=kept", j.JobID)
			}
		}
		t.Logf("2: %s:%s", label, out)
	}
	show("re-run failed jobs button", GetFailedJobsForRerun(tmpl))
	show("only the failed leaf selected", []*actions_model.ActionRunJob{tmpl[3]})
}

// 3: cancel acting on a job that a runner claimed after the page loaded it.
func TestProbeCancelMissesClaimedJob(t *testing.T) {
	ctx, _, _ := probeSetup(t)
	run, attempt := probeRun(t, actions_model.StatusWaiting, nil)
	job := probeJob(t, run, attempt, 1, "build", actions_model.StatusWaiting, nil)
	stale := probeJobNow(t, job.ID)
	probeTask(t, job, 1, timeutil.TimeStampNow()) // a runner claims it
	cancelled, err := actions_model.CancelJobs(ctx, []*actions_model.ActionRunJob{stale})
	t.Logf("3: cancel err=%v cancelled=%d; %s", err, len(cancelled), probeAttemptJobs(t, run))
}

// 4: cancel acting on a caller that finished after the page loaded it.
func TestProbeCancelOverwritesFinishedCaller(t *testing.T) {
	ctx, _, _ := probeSetup(t)
	run, attempt := probeRun(t, actions_model.StatusSuccess, nil)
	caller := probeJob(t, run, attempt, 1, "pipeline", actions_model.StatusSuccess, func(j *actions_model.ActionRunJob) { j.IsReusableCaller = true; j.IsExpanded = true })
	probeJob(t, run, attempt, 2, "build", actions_model.StatusSuccess, func(j *actions_model.ActionRunJob) { j.ParentJobID = caller.ID; j.TaskID = 9003 })
	stale := probeJobNow(t, caller.ID)
	stale.Status = actions_model.StatusRunning // what the handler read a moment earlier
	t.Logf("4: before: %s", probeAttemptJobs(t, run))
	_, err := actions_model.CancelJobs(ctx, []*actions_model.ActionRunJob{stale})
	t.Logf("4: after cancel err=%v: %s", err, probeAttemptJobs(t, run))
}

// 5: cancelling twice a job whose runner supports the cancelling handshake.
func TestProbeCancelTwiceStaysCancelling(t *testing.T) {
	ctx, _, _ := probeSetup(t)
	runner := &actions_model.ActionRunner{UUID: "11111111-2222-3333-4444-555555555555", Name: "probe", HasCancellingSupport: true}
	runner.GenerateAndFillToken()
	require.NoError(t, db.Insert(ctx, runner))
	run, attempt := probeRun(t, actions_model.StatusRunning, nil)
	job := probeJob(t, run, attempt, 1, "build", actions_model.StatusWaiting, nil)
	task := probeTask(t, job, runner.ID, timeutil.TimeStampNow())
	for i := 1; i <= 3; i++ {
		_, err := actions_model.CancelJobs(ctx, []*actions_model.ActionRunJob{probeJobNow(t, job.ID)})
		t.Logf("5: cancel #%d err=%v: %s", i, err, probeAttemptJobs(t, run))
	}
	// the runner keeps heart-beating (cleanup step hangs): every report refreshes `updated`, so the zombie cron never fires
	got, err := actions_model.UpdateTaskByState(ctx, runner.ID, &runnerv1.TaskState{Id: task.ID})
	require.NoError(t, err)
	require.NoError(t, StopZombieTasks(ctx))
	t.Logf("5: after heartbeat + zombie cron: task=%s; %s", got.Status, probeAttemptJobs(t, run))
}

// 6: abandoned-job cron and a blocked job whose dependency is still running.
func TestProbeAbandonedKillsBlockedDependent(t *testing.T) {
	ctx, _, _ := probeSetup(t)
	run, attempt := probeRun(t, actions_model.StatusRunning, nil)
	build := probeJob(t, run, attempt, 1, "build", actions_model.StatusWaiting, nil)
	deploy := probeJob(t, run, attempt, 2, "deploy", actions_model.StatusBlocked, func(j *actions_model.ActionRunJob) { j.Needs = []string{"build"} })
	probeTask(t, build, 1, timeutil.TimeStampNow()) // build waited in the queue and has just been picked up
	old := timeutil.TimeStampNow().AddDuration(-25 * time.Hour)
	_, err := db.Exec(ctx, "UPDATE `action_run_job` SET created = ?, updated = ? WHERE id = ?", old, old, deploy.ID)
	require.NoError(t, err)
	require.NoError(t, CancelAbandonedJobs(ctx))
	t.Logf("6: after abandoned cron: %s", probeAttemptJobs(t, run))
}

// 7: cancelling a run that contains a called workflow.
func TestProbeCancelCallerDuplicates(t *testing.T) {
	ctx, _, _ := probeSetup(t)
	run, attempt := probeRun(t, actions_model.StatusWaiting, nil)
	caller := probeJob(t, run, attempt, 1, "pipeline", actions_model.StatusWaiting, func(j *actions_model.ActionRunJob) { j.IsReusableCaller = true; j.IsExpanded = true })
	probeJob(t, run, attempt, 2, "build", actions_model.StatusWaiting, func(j *actions_model.ActionRunJob) { j.ParentJobID = caller.ID })
	probeJob(t, run, attempt, 3, "test", actions_model.StatusBlocked, func(j *actions_model.ActionRunJob) { j.ParentJobID = caller.ID; j.Needs = []string{"build"} })
	jobs, _ := actions_model.GetRunJobsByRunAndAttemptID(ctx, run.ID, attempt.ID)
	cancelled, err := actions_model.CancelJobs(ctx, jobs)
	names := ""
	for _, j := range cancelled {
		names += " " + j.JobID
	}
	t.Logf("7: cancel err=%v, 3 jobs in run, returned as cancelled (%d):%s", err, len(cancelled), names)
}

// 8: re-running a run that was cancelled while it still awaited approval.
func TestProbeRerunApprovalPending(t *testing.T) {
	ctx, repo, doer := probeSetup(t)
	run, attempt := probeRun(t, actions_model.StatusCancelled, func(r *actions_model.ActionRun) { r.NeedApproval = true; r.IsForkPullRequest = true })
	probeJob(t, run, attempt, 1, "build", actions_model.StatusCancelled, nil)
	_, err := RerunWorkflowRunJobs(ctx, repo, run, doer, nil)
	t.Logf("8: rerun err=%v: %s approved_by=%d", err, probeAttemptJobs(t, run), probeReloadRun(t, run.ID).ApprovedBy)
}

// 9: what the endless/zombie crons tell a runner that is still alive.
func TestProbeEndlessKillResult(t *testing.T) {
	ctx, _, _ := probeSetup(t)
	run, attempt := probeRun(t, actions_model.StatusRunning, nil)
	job := probeJob(t, run, attempt, 1, "longjob", actions_model.StatusWaiting, nil)
	task := probeTask(t, job, 1, timeutil.TimeStampNow().AddDuration(-4*time.Hour))
	require.NoError(t, StopEndlessTasks(ctx))
	t.Logf("9: after endless cron: %s", probeAttemptJobs(t, run))
	got, err := actions_model.UpdateTaskByState(ctx, 1, &runnerv1.TaskState{Id: task.ID})
	t.Logf("9: runner's next heartbeat: err=%v, server answers result=%s (runner only aborts on %s)", err, got.Status.AsResult(), runnerv1.Result_RESULT_CANCELLED)
}

// 10: two re-run requests racing (second one read the run before the first committed).
func TestProbeDoubleRerun(t *testing.T) {
	ctx, repo, doer := probeSetup(t)
	run, attempt := probeRun(t, actions_model.StatusFailure, nil)
	probeJob(t, run, attempt, 1, "build", actions_model.StatusFailure, func(j *actions_model.ActionRunJob) { j.TaskID = 9004 })
	first, second := probeReloadRun(t, run.ID), probeReloadRun(t, run.ID)
	_, err1 := RerunWorkflowRunJobs(ctx, repo, first, doer, nil)
	_, err2 := RerunWorkflowRunJobs(ctx, repo, second, doer, nil)
	n, _ := db.GetEngine(ctx).Where("run_id = ?", run.ID).Count(new(actions_model.ActionRunAttempt))
	t.Logf("10: first err=%v; second err=%v; attempts=%d; %s", err1, err2, n, probeAttemptJobs(t, run))
	_, err3 := RerunWorkflowRunJobs(ctx, repo, probeReloadRun(t, run.ID), doer, nil)
	t.Logf("10: third (fresh read, run not done) err=%v", err3)
}

// 11: children of a cancelled caller.
func TestProbeChildrenOfCancelledCaller(t *testing.T) {
	ctx, _, _ := probeSetup(t)
	run, attempt := probeRun(t, actions_model.StatusCancelled, nil)
	caller := probeJob(t, run, attempt, 1, "pipeline", actions_model.StatusCancelled, func(j *actions_model.ActionRunJob) { j.IsReusableCaller = true; j.IsExpanded = true })
	probeJob(t, run, attempt, 2, "build", actions_model.StatusBlocked, func(j *actions_model.ActionRunJob) { j.ParentJobID = caller.ID })
	t.Logf("11: before: %s", probeAttemptJobs(t, run))
	err := db.WithTx(ctx, func(ctx context.Context) error {
		_, err := checkJobsOfCurrentRunAttempt(ctx, probeReloadRun(t, run.ID))
		return err
	})
	t.Logf("11: after emitter pass err=%v: %s", err, probeAttemptJobs(t, run))
}

// 12: zombie cron on a task whose FetchTask response never reached the runner.
func TestProbeZombieFailsJob(t *testing.T) {
	ctx, _, _ := probeSetup(t)
	run, attempt := probeRun(t, actions_model.StatusRunning, nil)
	job := probeJob(t, run, attempt, 1, "build", actions_model.StatusWaiting, nil)
	task := probeTask(t, job, 1, timeutil.TimeStampNow().AddDuration(-11*time.Minute))
	_, err := db.Exec(ctx, "UPDATE `action_task` SET updated = ? WHERE id = ?", timeutil.TimeStampNow().AddDuration(-11*time.Minute), task.ID)
	require.NoError(t, err)
	require.NoError(t, StopZombieTasks(ctx))
	t.Logf("12: after zombie cron: %s", probeAttemptJobs(t, run))
}

