		jobEmitterQueue = queue.CreateUniqueQueue(t.Context(), "probe_ready_job", func(items ...*jobUpdate) []*jobUpdate { return nil })
		require.NotNil(t, jobEmitterQueue)
	}
	repo := unittest.AssertExistsAndLoadBean(t, &repo_model.Repository{ID: 4})
	doer := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 1})
	return t.Context(), repo, doer
}

func probeRun(t *testing.T, status actions_model.Status, mut func(*actions_model.ActionRun)) (*actions_model.ActionRun, *actions_model.ActionRunAttempt) {
	ctx := t.Context()
	probeIndex++
	run := &actions_model.ActionRun{
		RepoID: 4, OwnerID: 1, TriggerUserID: 1, WorkflowID: "test.yml", Index: probeIndex, Ref: "refs/heads/main",
		Event: "push", TriggerEvent: "push", EventPayload: "{}", Status: status, WorkflowRepoID: 4,
	}
	if mut != nil {
		mut(run)
	}
	require.NoError(t, db.Insert(ctx, run))
	attempt := &actions_model.ActionRunAttempt{RepoID: 4, RunID: run.ID, Attempt: 1, TriggerUserID: 1, Status: status}
	require.NoError(t, db.Insert(ctx, attempt))
	_, err := db.Exec(ctx, "UPDATE `action_run` SET latest_attempt_id = ? WHERE id = ?", attempt.ID, run.ID)
	require.NoError(t, err)
	return probeReloadRun(t, run.ID), attempt
}

func probeReloadRun(t *testing.T, id int64) *actions_model.ActionRun {
	run, err := actions_model.GetRunByRepoAndID(t.Context(), 4, id)
	require.NoError(t, err)
	return run
}

func probeJob(t *testing.T, run *actions_model.ActionRun, attempt *actions_model.ActionRunAttempt, n int64, jobID string, status actions_model.Status, mut func(*actions_model.ActionRunJob)) *actions_model.ActionRunJob {
	job := &actions_model.ActionRunJob{
		RunID: run.ID, RunAttemptID: attempt.ID, AttemptJobID: n, Attempt: 1, RepoID: 4, OwnerID: 1,
		JobID: jobID, Name: jobID, Status: status, WorkflowPayload: probePayload(jobID), RunsOn: []string{"ubuntu-latest"},
	}
	if mut != nil {
		mut(job)
	}
	require.NoError(t, db.Insert(t.Context(), job))
	return job
