func probeTask(t *testing.T, job *actions_model.ActionRunJob, runnerID int64, started timeutil.TimeStamp) *actions_model.ActionTask {
	ctx := t.Context()
	task := &actions_model.ActionTask{JobID: job.ID, RunnerID: runnerID, Status: actions_model.StatusRunning, RepoID: 4, OwnerID: 1, Started: started, LogFilename: fmt.Sprintf("probe/%d.log", job.ID)}
	task.GenerateAndFillToken()
	require.NoError(t, db.Insert(ctx, task))
	_, err := db.Exec(ctx, "UPDATE `action_run_job` SET task_id = ?, status = ? WHERE id = ?", task.ID, actions_model.StatusRunning, job.ID)
