	probeJob(t, run, attempt, 2, "build", actions_model.StatusSuccess, func(j *actions_model.ActionRunJob) { j.ParentJobID = caller.ID; j.TaskID = 9003 })
	stale := probeJobNow(t, caller.ID)
	stale.Status = actions_model.StatusRunning // what the handler read a moment earlier
	t.Logf("4: before: %s", probeAttemptJobs(t, run))
	_, err := actions_model.CancelJobs(ctx, []*actions_model.ActionRunJob{stale})
	t.Logf("4: after cancel err=%v: %s", err, probeAttemptJobs(t, run))
}

// 5: cancelling twice a job whose runner supports the cancelling handshake.
func TestProbeCancelTwiceStaysCancelling(t *testing.T) {
	ctx, _, _ := probeSetup(t)
	runner := &actions_model.ActionRunner{UUID: "11111111-2222-3333-4444-555555555555", Name: "probe", HasCancellingSupport: true}
	runner.GenerateAndFillToken()
	require.NoError(t, db.Insert(ctx, runner))
	run, attempt := probeRun(t, actions_model.StatusRunning, nil)
	job := probeJob(t, run, attempt, 1, "build", actions_model.StatusWaiting, nil)
	task := probeTask(t, job, runner.ID, timeutil.TimeStampNow())
	for i := 1; i <= 3; i++ {
		_, err := actions_model.CancelJobs(ctx, []*actions_model.ActionRunJob{probeJobNow(t, job.ID)})
		t.Logf("5: cancel #%d err=%v: %s", i, err, probeAttemptJobs(t, run))
	}
	// the runner keeps heart-beating (cleanup step hangs): every report refreshes `updated`, so the zombie cron never fires
	got, err := actions_model.UpdateTaskByState(ctx, runner.ID, &runnerv1.TaskState{Id: task.ID})
	require.NoError(t, err)
	require.NoError(t, StopZombieTasks(ctx))
	t.Logf("5: after heartbeat + zombie cron: task=%s; %s", got.Status, probeAttemptJobs(t, run))
}

// 6: abandoned-job cron and a blocked job whose dependency is still running.
func TestProbeAbandonedKillsBlockedDependent(t *testing.T) {
	ctx, _, _ := probeSetup(t)
	run, attempt := probeRun(t, actions_model.StatusRunning, nil)
	build := probeJob(t, run, attempt, 1, "build", actions_model.StatusWaiting, nil)
	deploy := probeJob(t, run, attempt, 2, "deploy", actions_model.StatusBlocked, func(j *actions_model.ActionRunJob) { j.Needs = []string{"build"} })
	probeTask(t, build, 1, timeutil.TimeStampNow()) // build waited in the queue and has just been picked up
	old := timeutil.TimeStampNow().AddDuration(-25 * time.Hour)
	_, err := db.Exec(ctx, "UPDATE `action_run_job` SET created = ?, updated = ? WHERE id = ?", old, old, deploy.ID)
	require.NoError(t, err)
	require.NoError(t, CancelAbandonedJobs(ctx))
	t.Logf("6: after abandoned cron: %s", probeAttemptJobs(t, run))
}

// 7: cancelling a run that contains a called workflow.
func TestProbeCancelCallerDuplicates(t *testing.T) {
	ctx, _, _ := probeSetup(t)
	run, attempt := probeRun(t, actions_model.StatusWaiting, nil)
