1	// Copyright 2026 The Gitea Authors. All rights reserved.
2	// SPDX-License-Identifier: MIT
3	
4	package jobparser
5	
6	import (
7		"errors"
8		"fmt"
9		"regexp"
10		"strings"
11	
12		"gitea.dev/modules/container"
13		"gitea.dev/modules/util"
14	
15		"gitea.com/gitea/runner/act/exprparser"
16		"gitea.com/gitea/runner/act/model"
17		"go.yaml.in/yaml/v4"
18	)
19	
20	// InputType enumerates the allowed types for a workflow_call input.
21	type InputType string
22	
23	const (
24		InputTypeString  InputType = "string"
25		InputTypeBoolean InputType = "boolean"
26		InputTypeNumber  InputType = "number"
27	)
28	
29	// InputSpec describes a single workflow_call input declaration.
30	type InputSpec struct {
31		Description string    `yaml:"description"`
32		Required    bool      `yaml:"required"`
33		Default     yaml.Node `yaml:"default"`
34		Type        InputType `yaml:"type"`
35	}
36	
37	// SecretSpec describes a single workflow_call secret declaration.
38	type SecretSpec struct {
39		Description string `yaml:"description"`
40		Required    bool   `yaml:"required"`
41	}
42	
43	// OutputSpec describes a single workflow_call output declaration.
44	type OutputSpec struct {
45		Description string `yaml:"description"`
46		Value       string `yaml:"value"`
47	}
48	
49	// WorkflowCallSpec is the parsed "on.workflow_call" schema of a called workflow.
50	type WorkflowCallSpec struct {
51		Inputs  map[string]InputSpec
52		Secrets map[string]SecretSpec
53		Outputs map[string]OutputSpec
54	}
55	
56	// JobOutputs is the per-job-id outputs map used for evaluating workflow_call outputs.
57	type JobOutputs map[string]map[string]string
58	
59	// ParseWorkflowCallSpec extracts on.workflow_call.{inputs,secrets,outputs} from a workflow YAML.
60	// Returns an error if the workflow does not declare on.workflow_call at all.
61	func ParseWorkflowCallSpec(content []byte) (*WorkflowCallSpec, error) {
62		var doc struct {
63			On yaml.Node `yaml:"on"`
64		}
65		if err := yaml.Unmarshal(content, &doc); err != nil {
66			return nil, fmt.Errorf("parse workflow yaml: %w", err)
67		}
68	
69		wcNode, ok := findWorkflowCallNode(&doc.On)
70		if !ok {
71			return nil, errors.New("workflow does not declare on.workflow_call")
72		}
73	
74		spec := &WorkflowCallSpec{
75			Inputs:  map[string]InputSpec{},
76			Secrets: map[string]SecretSpec{},
77			Outputs: map[string]OutputSpec{},
78		}
79	
80		if wcNode == nil || wcNode.Kind != yaml.MappingNode {
81			return spec, nil
82		}
83	
84		for i := 0; i+1 < len(wcNode.Content); i += 2 {
85			key := wcNode.Content[i]
86			val := wcNode.Content[i+1]
87			switch key.Value {
88			case "inputs":
89				if err := decodeWorkflowCallMapping(val, spec.Inputs); err != nil {
90					return nil, fmt.Errorf("parse workflow_call.inputs: %w", err)
91				}
92			case "secrets":
93				if err := decodeWorkflowCallMapping(val, spec.Secrets); err != nil {
94					return nil, fmt.Errorf("parse workflow_call.secrets: %w", err)
95				}
96			case "outputs":
97				if err := decodeWorkflowCallMapping(val, spec.Outputs); err != nil {
98					return nil, fmt.Errorf("parse workflow_call.outputs: %w", err)
99				}
100			}
101		}
102	
103		for name, in := range spec.Inputs {
104			if in.Type == "" {
105				return nil, fmt.Errorf("workflow_call input %q is missing required field \"type\"", name)
106			}
107			switch in.Type {
108			case InputTypeString, InputTypeBoolean, InputTypeNumber:
109			default:
110				return nil, fmt.Errorf("workflow_call input %q has unsupported type %q", name, in.Type)
111			}
112		}
113	
114		return spec, nil
115	}
116	
117	// findWorkflowCallNode walks the "on:" node and returns the value mapping (or nil) for "workflow_call".
118	// "ok" is true when the workflow declares workflow_call (even with an empty body).
119	func findWorkflowCallNode(on *yaml.Node) (val *yaml.Node, ok bool) {
120		if on == nil || on.Kind == 0 {
121			return nil, false
122		}
123		switch on.Kind {
124		case yaml.ScalarNode:
125			return nil, on.Value == "workflow_call"
126		case yaml.SequenceNode:
127			for _, item := range on.Content {
128				if item.Kind == yaml.ScalarNode && item.Value == "workflow_call" {
129					return nil, true
130				}
131			}
132			return nil, false
133		case yaml.MappingNode:
134			for i := 0; i+1 < len(on.Content); i += 2 {
135				k := on.Content[i]
136				v := on.Content[i+1]
137				if k.Value != "workflow_call" {
138					continue
139				}
140				if v.Kind == yaml.MappingNode {
141					return v, true
142				}
143				return nil, true
144			}
145		}
146		return nil, false
147	}
148	
149	func decodeWorkflowCallMapping[T any](node *yaml.Node, dst map[string]T) error {
150		if node == nil || node.Kind != yaml.MappingNode {
151			return nil
152		}
153		for i := 0; i+1 < len(node.Content); i += 2 {
154			name := node.Content[i].Value
155			var v T
156			if err := node.Content[i+1].Decode(&v); err != nil {
157				return fmt.Errorf("%q: %w", name, err)
158			}
159			dst[name] = v
160		}
161		return nil
162	}
163	
164	// EvaluateCallerWith evaluates the caller-side expressions in `job.With` against the provided contexts
165	func EvaluateCallerWith(
166		jobID string,
167		job *Job,
168		gitCtx map[string]any,
169		results map[string]*JobResult,
170		vars map[string]string,
171		inputs map[string]any,
172	) (map[string]any, error) {
173		actJob := &model.Job{Strategy: &model.Strategy{
174			FailFastString:    job.Strategy.FailFastString,
175			MaxParallelString: job.Strategy.MaxParallelString,
176			RawMatrix:         job.Strategy.RawMatrix,
177		}}
178	
179		var matrix map[string]any
180		matrixes, err := actJob.GetMatrixes()
181		if err != nil {
182			return nil, fmt.Errorf("get caller %q matrix: %w", jobID, err)
183		}
184		if len(matrixes) > 0 {
185			matrix = matrixes[0]
186		}
187	
188		evaluator := NewExpressionEvaluator(NewInterpeter(jobID, actJob, matrix, toGitContext(gitCtx), results, vars, inputs))
189	
190		out := make(map[string]any, len(job.With))
191		for k, raw := range job.With {
192			var evaluated any
193			switch v := raw.(type) {
194			case string:
195				node := yaml.Node{}
196				if err := node.Encode(v); err != nil {
197					return nil, fmt.Errorf("encode caller %q with[%q]: %w", jobID, k, err)
198				}
199				if err := evaluator.EvaluateYamlNode(&node); err != nil {
200					return nil, fmt.Errorf("evaluate caller %q with[%q]: %w", jobID, k, err)
201				}
202				if err := node.Decode(&evaluated); err != nil {
203					return nil, fmt.Errorf("decode caller %q with[%q]: %w", jobID, k, err)
204				}
205			default:
206				evaluated = v
207			}
208			out[k] = evaluated
209		}
210		return out, nil
211	}
212	
213	// MatchCallerInputsAgainstSpec checks the caller's already-evaluated `with:` values against the callee's declared `on.workflow_call.inputs` schema
214	func MatchCallerInputsAgainstSpec(spec *WorkflowCallSpec, evaluated map[string]any) (map[string]any, error) {
215		resolved := make(map[string]any, len(spec.Inputs))
216	
217		// fill defaults first
218		for name, in := range spec.Inputs {
219			if in.Default.IsZero() {
220				continue
221			}
222			var defaultVal any
223			if err := in.Default.Decode(&defaultVal); err != nil {
224				return nil, fmt.Errorf("decode workflow_call input %q default: %w", name, err)
225			}
226			v, err := parseWorkflowCallInput(name, in.Type, defaultVal)
227			if err != nil {
228				return nil, err
229			}
230			resolved[name] = v
231		}
232	
233		for k, raw := range evaluated {
234			inputSpec, ok := spec.Inputs[k]
235			if !ok {
236				// ignore unknown "with:" keys
237				continue
238			}
239			converted, err := parseWorkflowCallInput(k, inputSpec.Type, raw)
240			if err != nil {
241				return nil, err
242			}
243			resolved[k] = converted
244		}
245	
246		for name, in := range spec.Inputs {
247			if !in.Required {
248				continue
249			}
250			// resolved[name] is set when caller provided it OR when spec has a non-zero default - both satisfy "required".
251			if _, ok := resolved[name]; ok {
252				continue
253			}
254			return nil, fmt.Errorf("workflow_call input %q is required", name)
255		}
256	
257		return resolved, nil
258	}
259	
260	func parseWorkflowCallInput(name string, typ InputType, v any) (any, error) {
261		switch typ {
262		case InputTypeString:
263			return toString(v), nil
264		case InputTypeBoolean:
265			// strict type matching: a boolean input only accepts a native bool, not a "true"/"false" string
266			if b, ok := v.(bool); ok {
267				return b, nil
268			}
269			return false, fmt.Errorf("workflow_call input %q expects boolean", name)
270		case InputTypeNumber:
271			// strict type matching: a number input rejects "123"/"3.14" strings.
272			if _, isString := v.(string); isString {
273				return 0.0, fmt.Errorf("workflow_call input %q expects number", name)
274			}
275			return util.ToFloat64(v)
276		default:
277			return nil, fmt.Errorf("workflow_call input %q has unsupported type %q", name, typ)
278		}
279	}
280	
281	// SecretsInherit is the literal keyword used in a caller's `secrets: inherit` directive
282	const SecretsInherit = "inherit"
283	
284	// callerSecretValueRegexp matches the `${{ secrets.NAME }}` form expected for each value in a caller's `secrets:` mapping.
285	var callerSecretValueRegexp = regexp.MustCompile(`^\s*\$\{\{\s*secrets\.([A-Za-z_][A-Za-z0-9_]*)\s*\}\}\s*$`)
286	
287	// ParseCallerSecrets decodes a caller's "secrets:" YAML node into one of two forms:
288	//   - inherit == true: the caller wrote `secrets: inherit`; mapping is nil
289	//   - inherit == false, mapping == {alias: source_name}: explicit mapping. Each value must be of the form `${{ secrets.NAME }}`.
290	//
291	// Both alias and source name are upper-cased: secret names are case-insensitive (matching GitHub),
292	// and Gitea stores secrets upper-cased, so this keeps lookups and schema validation consistent.
293	func ParseCallerSecrets(node yaml.Node) (inherit bool, mapping map[string]string, err error) {
294		if node.IsZero() {
295			return false, nil, nil
296		}
297		if node.Kind == yaml.ScalarNode && strings.TrimSpace(node.Value) == SecretsInherit {
298			return true, nil, nil
299		}
300		if node.Kind != yaml.MappingNode {
301			return false, nil, errors.New("invalid secrets: section, expected mapping or 'inherit'")
302		}
303		out := make(map[string]string, len(node.Content)/2)
304		for i := 0; i+1 < len(node.Content); i += 2 {
305			k := node.Content[i]
306			v := node.Content[i+1]
307			var sv string
308			if err := v.Decode(&sv); err != nil {
309				return false, nil, fmt.Errorf("decode secret %q: %w", k.Value, err)
310			}
311			matches := callerSecretValueRegexp.FindStringSubmatch(sv)
312			if len(matches) != 2 {
313				return false, nil, fmt.Errorf("caller secret %q value must be of the form ${{ secrets.NAME }}", k.Value)
314			}
315			out[strings.ToUpper(k.Value)] = strings.ToUpper(matches[1])
316		}
317		return false, out, nil
318	}
319	
320	// ValidateCallerSecrets checks a caller's parsed explicit-mapping `secrets:` against the called workflow's declared `on.workflow_call.secrets` schema.
321	func ValidateCallerSecrets(spec *WorkflowCallSpec, mapping map[string]string) error {
322		if spec == nil {
323			return errors.New("ValidateCallerSecrets: nil workflow_call spec")
324		}
325		// Secret names are case-insensitive, so compare declared names and caller aliases upper-cased.
326		declaredNames := make(container.Set[string], len(spec.Secrets))
327		for name := range spec.Secrets {
328			declaredNames.Add(strings.ToUpper(name))
329		}
330		provided := make(container.Set[string], len(mapping))
331		for alias := range mapping {
332			up := strings.ToUpper(alias)
333			provided.Add(up)
334			if !declaredNames.Contains(up) {
335				return fmt.Errorf("caller secret %q is not declared in the called workflow's on.workflow_call.secrets", alias)
336			}
337		}
338		for name, sec := range spec.Secrets {
339			if sec.Required && !provided.Contains(strings.ToUpper(name)) {
340				return fmt.Errorf("required secret %q is not provided by the caller", name)
341			}
342		}
343		return nil
344	}
345	
346	// EvaluateWorkflowCallOutputs evaluates a called workflow's "on.workflow_call.outputs.<name>.value" expressions against the provided contexts.
347	func EvaluateWorkflowCallOutputs(spec *WorkflowCallSpec, gitCtx *model.GithubContext, vars map[string]string, inputs map[string]any, jobOutputs JobOutputs) (map[string]string, error) {
348		if spec == nil || len(spec.Outputs) == 0 {
349			return map[string]string{}, nil
350		}
351	
352		jobsCtx := make(map[string]*model.WorkflowCallResult, len(jobOutputs))
353		for jobID, outputs := range jobOutputs {
354			jobsCtx[jobID] = &model.WorkflowCallResult{Outputs: outputs}
355		}
356	
357		// See `on.workflow_call.outputs.<output_id>.value` in https://docs.github.com/en/actions/reference/workflows-and-actions/contexts#context-availability
358		env := &exprparser.EvaluationEnvironment{
359			Github: gitCtx,
360			Jobs:   &jobsCtx,
361			Vars:   vars,
362			Inputs: inputs,
363		}
364		interpreter := exprparser.NewInterpeter(env, exprparser.Config{})
365	
366		out := make(map[string]string, len(spec.Outputs))
367		for name, o := range spec.Outputs {
368			v, err := evaluateWorkflowCallOutputValue(interpreter, o.Value)
369			if err != nil {
370				return nil, fmt.Errorf("workflow_call output %q: %w", name, err)
371			}
372			out[name] = v
373		}
374		return out, nil
375	}
376	
377	func evaluateWorkflowCallOutputValue(interpreter exprparser.Interpreter, value string) (string, error) {
378		if !strings.Contains(value, "${{") || !strings.Contains(value, "}}") {
379			return value, nil
380		}
381		expr, err := rewriteSubExpression(value, true)
382		if err != nil {
383			return "", err
384		}
385		evaluated, err := interpreter.Evaluate(expr, exprparser.DefaultStatusCheckNone)
386		if err != nil {
387			return "", err
388		}
389		return toString(evaluated), nil
390	}
391	
392	func toString(v any) string {
393		switch s := v.(type) {
394		case string:
395			return s
396		case nil:
397			return ""
398		default:
399			return fmt.Sprintf("%v", s)
400		}
401	}
