59	// ParseWorkflowCallSpec extracts on.workflow_call.{inputs,secrets,outputs} from a workflow YAML.
60	// Returns an error if the workflow does not declare on.workflow_call at all.
61	func ParseWorkflowCallSpec(content []byte) (*WorkflowCallSpec, error) {
62		var doc struct {
63			On yaml.Node `yaml:"on"`
64		}
65		if err := yaml.Unmarshal(content, &doc); err != nil {
66			return nil, fmt.Errorf("parse workflow yaml: %w", err)
67		}
68	
69		wcNode, ok := findWorkflowCallNode(&doc.On)
70		if !ok {
71			return nil, errors.New("workflow does not declare on.workflow_call")
72		}
73	
74		spec := &WorkflowCallSpec{
75			Inputs:  map[string]InputSpec{},
76			Secrets: map[string]SecretSpec{},
77			Outputs: map[string]OutputSpec{},
78		}
79	
80		if wcNode == nil || wcNode.Kind != yaml.MappingNode {
81			return spec, nil
82		}
83	
84		for i := 0; i+1 < len(wcNode.Content); i += 2 {
85			key := wcNode.Content[i]
86			val := wcNode.Content[i+1]
87			switch key.Value {
88			case "inputs":
89				if err := decodeWorkflowCallMapping(val, spec.Inputs); err != nil {
90					return nil, fmt.Errorf("parse workflow_call.inputs: %w", err)
91				}
92			case "secrets":
93				if err := decodeWorkflowCallMapping(val, spec.Secrets); err != nil {
94					return nil, fmt.Errorf("parse workflow_call.secrets: %w", err)
95				}
96			case "outputs":
97				if err := decodeWorkflowCallMapping(val, spec.Outputs); err != nil {
98					return nil, fmt.Errorf("parse workflow_call.outputs: %w", err)
99				}
100			}
101		}
102	
103		for name, in := range spec.Inputs {
104			if in.Type == "" {
105				return nil, fmt.Errorf("workflow_call input %q is missing required field \"type\"", name)
106			}
107			switch in.Type {
108			case InputTypeString, InputTypeBoolean, InputTypeNumber:
109			default:
110				return nil, fmt.Errorf("workflow_call input %q has unsupported type %q", name, in.Type)
111			}
112		}
113	
114		return spec, nil
115	}
