117	// findWorkflowCallNode walks the "on:" node and returns the value mapping (or nil) for "workflow_call".
118	// "ok" is true when the workflow declares workflow_call (even with an empty body).
119	func findWorkflowCallNode(on *yaml.Node) (val *yaml.Node, ok bool) {
120		if on == nil || on.Kind == 0 {
121			return nil, false
122		}
123		switch on.Kind {
124		case yaml.ScalarNode:
125			return nil, on.Value == "workflow_call"
126		case yaml.SequenceNode:
127			for _, item := range on.Content {
128				if item.Kind == yaml.ScalarNode && item.Value == "workflow_call" {
129					return nil, true
130				}
131			}
132			return nil, false
133		case yaml.MappingNode:
134			for i := 0; i+1 < len(on.Content); i += 2 {
135				k := on.Content[i]
136				v := on.Content[i+1]
137				if k.Value != "workflow_call" {
138					continue
139				}
140				if v.Kind == yaml.MappingNode {
141					return v, true
142				}
143				return nil, true
144			}
145		}
146		return nil, false
147	}
148	
149	func decodeWorkflowCallMapping[T any](node *yaml.Node, dst map[string]T) error {
150		if node == nil || node.Kind != yaml.MappingNode {
151			return nil
152		}
153		for i := 0; i+1 < len(node.Content); i += 2 {
154			name := node.Content[i].Value
155			var v T
156			if err := node.Content[i+1].Decode(&v); err != nil {
157				return fmt.Errorf("%q: %w", name, err)
158			}
159			dst[name] = v
160		}
161		return nil
162	}
