func TestProbeLeadingIndent(t *testing.T) {
	pre := "on: push\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n"
	cases := []rtCase{
		{"run: |2 (explicit indent indicator)", pre + "      - run: |2\n            indented first\n          second\n"},
		{"run: leading blank line", pre + "      - run: |\n\n          echo a\n          echo b\n"},
		{"run: quoted, starts with newline+spaces", pre + "      - run: \"\\n  make build\\n  make test\\n\"\n"},
		{"run: quoted, starts with spaces", pre + "      - run: \"  make build\\nmake test\\n\"\n"},
		{"run: single line starting with space", pre + "      - run: \" make build\"\n"},
		{"with.script starts with spaces (multi-line)", pre + "      - uses: actions/github-script@v7\n        with:\n          script: \"  const a = 1;\\nreturn a;\\n\"\n"},
		{"env value multi-line starting with space", pre + "      - run: echo\n        env:\n          MSG: \"  indented\\nnext\\n\"\n"},
		{"markdown/yaml heredoc body indented in |", pre + "      - run: |\n          cat <<EOF > k8s.yaml\n            spec:\n              replicas: 2\n          EOF\n"},
		{"python script via | with first line indented (|4)", pre + "      - shell: python\n        run: |4\n              import sys\n            print(sys.version)\n"},
		{"job name with leading space multi-line", "on: push\njobs:\n  build:\n    name: \"  a\\nb\"\n    runs-on: ubuntu-latest\n    steps:\n      - run: echo\n"},
	}
	for _, c := range cases {
		if _, err := actions_module.GetEventsFromContent([]byte(c.content)); err != nil {
			t.Logf("%-52s => rejected at detection: %v", c.name, err)
			continue
		}
		wfs, err := jobparser.Parse([]byte(c.content))
		if err != nil || len(wfs) != 1 {
			t.Logf("%-52s => parse err=%v n=%d", c.name, err, len(wfs))
			continue
		}
		id, job := wfs[0].Job()
		_ = wfs[0].SetJob(id, job.EraseNeeds())
		payload, merr := wfs[0].Marshal()
		_, err = (&actions_model.ActionRunJob{ID: 1, WorkflowPayload: payload}).ParseJob()
		if err != nil {
			t.Logf("%-52s => accepted, stored (marshal err=%v), READ-BACK FAILS: %v\n--- stored payload ---\n%s", c.name, merr, err, strings.TrimRight(string(payload), "\n"))
		} else {
			t.Logf("%-52s => ok", c.name)
		}
	}
}
