	files := map[string]string{
		"bad.yml":  "on: push\njobs:\n  build:\n    runs-on: probe-linux\n    steps:\n      - run: |\n\n          set -e\n          make build\n",
		"good.yml": "on: push\njobs:\n  test:\n    runs-on: probe-linux\n    steps:\n      - name: Test\n        run: make test\n",
		"named.yml": "on: push\njobs:\n  build:\n    runs-on: probe-linux\n    steps:\n      - name: Build\n        run: |\n\n          set -e\n          make build\n",
	}
	sha := pCommit(t, files)
	named, err := pTrigger(t, sha, files, "named.yml")
	require.NoError(t, err)
	t.Logf("control (same script, step has a name:): %s%s", pTree(t, named), pNotes(pDrive(t, runner, named)))
	t.Logf("control after drive: %s", pTree(t, named))

	bad, err := pTrigger(t, sha, files, "bad.yml")
	t.Logf("bad.yml (unnamed step, script starts with a blank line): insert err=%v", err)
	require.NoError(t, err)
	_, err = db.Exec(ctx, "UPDATE `action_run_job` SET updated = updated - 5 WHERE run_id = ?", bad.ID) // it was queued first
	require.NoError(t, err)
	good, err := pTrigger(t, sha, files, "good.yml")
	require.NoError(t, err)
	for i := 1; i <= 3; i++ {
		task, ok, err := actions_model.CreateTaskForRunner(ctx, runner)
		t.Logf("runner poll #%d: got task=%v err=%v", i, ok && task != nil, err)
	}
	t.Logf("bad:  %s", pTree(t, bad))
	t.Logf("good (queued behind it): %s", pTree(t, good))
}

func TestProbeFanOut(t *testing.T) {
	runner := pSetup(t)
	level := func(next string) string {
		if next == "" {
			return "on:\n  workflow_call:\njobs:\n  leaf:\n    strategy:\n      matrix:\n        shard: [1, 2, 3, 4, 5]\n    runs-on: probe-linux\n    steps:\n      - run: make test\n"
		}
		return "on:\n  workflow_call:\njobs:\n  fan:\n    strategy:\n      matrix:\n        part: [1, 2, 3, 4, 5]\n    uses: ./.gitea/workflows/" + next + "\n"
	}
	files := map[string]string{
		"l3.yml": level(""), "l2.yml": level("l3.yml"), "l1.yml": level("l2.yml"),
		"top.yml": "on: push\njobs:\n  all:\n    strategy:\n      matrix:\n        region: [1, 2, 3, 4, 5]\n    uses: ./.gitea/workflows/l1.yml\n",
	}
	sha := pCommit(t, files)
	start := time.Now()
	run, err := pTrigger(t, sha, files, "top.yml")
	require.NoError(t, err)
	passes := 0
	for range 10 {
		before := len(pJobs(t, run))
		require.NoError(t, pEmit(t, run.ID))
		passes++
		if len(pJobs(t, run)) == before {
			break
		}
	}
	jobs := pJobs(t, run)
	byStatus := map[string]int{}
	callers, payload, content := 0, 0, 0
	for _, j := range jobs {
		byStatus[j.Status.String()]++
		if j.IsReusableCaller {
			callers++
		}
		payload += len(j.WorkflowPayload)
		content += len(j.ReusableWorkflowContent)
	}
	keys := []string{}
	for k, v := range byStatus {
		keys = append(keys, fmt.Sprintf("%s=%d", k, v))
	}
	sort.Strings(keys)
	t.Logf("fan-out: 4 files, a 5-way matrix at each of 4 levels => %d job rows (%d callers) after %d emitter passes in %s; statuses: %s; stored payload=%dKB, stored called-workflow copies=%dKB; MaxJobNumPerRun constant=%d, MAX levels=%d",
		len(jobs), callers, passes, time.Since(start).Round(time.Millisecond), strings.Join(keys, " "), payload/1024, content/1024, actions_model.MaxJobNumPerRun, MaxReusableCallLevels)
	_ = runner
	_ = setting.AppURL
}

