const wfDir = ".gitea/workflows/"

func pGit(t *testing.T, dir string, env []string, stdin string, args ...string) string {
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), env...)
	cmd.Stdin = strings.NewReader(stdin)
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	require.NoError(t, cmd.Run(), "git %v: %s", args, errb.String())
	return strings.TrimSpace(out.String())
}

// pCommit writes the given workflow files as one commit into the test copy of user5/repo4 and returns its SHA.
func pCommit(t *testing.T, files map[string]string) string {
	dir := repo_model.RepoPath("user5", "repo4")
	idx := filepath.Join(t.TempDir(), "index")
	env := []string{"GIT_INDEX_FILE=" + idx, "GIT_AUTHOR_NAME=p", "GIT_AUTHOR_EMAIL=p@example.com", "GIT_COMMITTER_NAME=p", "GIT_COMMITTER_EMAIL=p@example.com"}
	for name, content := range files {
		blob := pGit(t, dir, env, content, "hash-object", "-w", "--stdin")
		pGit(t, dir, env, "", "update-index", "--add", "--cacheinfo", "100644,"+blob+","+wfDir+name)
	}
	tree := pGit(t, dir, env, "", "write-tree")
	return pGit(t, dir, env, "", "commit-tree", tree, "-m", "probe")
}

func pSetup(t *testing.T) *actions_model.ActionRunner {
	require.NoError(t, unittest.PrepareTestDatabase())
	if jobEmitterQueue == nil {
		jobEmitterQueue = queue.CreateUniqueQueue(t.Context(), "probe_ready_job", func(items ...*jobUpdate) []*jobUpdate { return nil })
	}
	runner := &actions_model.ActionRunner{UUID: fmt.Sprintf("11111111-2222-3333-4444-%012d", time.Now().UnixNano()%1e12), Name: "probe", RepoID: 4, AgentLabels: []string{"probe-linux"}}
	runner.GenerateAndFillToken()
	require.NoError(t, db.Insert(t.Context(), runner))
	return runner
}

// pTrigger does what a push does for one workflow file: detection, then run insertion.
func pTrigger(t *testing.T, sha string, files map[string]string, entry string) (run *actions_model.ActionRun, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("PANIC: %v", r)
		}
	}()
	if _, derr := actions_module.GetEventsFromContent([]byte(files[entry])); derr != nil {
		return nil, fmt.Errorf("rejected at detection: %w", derr)
	}
	doer := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 5})
	run = &actions_model.ActionRun{
		Title: "probe", RepoID: 4, OwnerID: 5, WorkflowID: entry, TriggerUserID: doer.ID, Ref: "refs/heads/master", CommitSHA: sha,
		Event: "push", TriggerEvent: "push", EventPayload: `{"ref":"refs/heads/master"}`, WorkflowRepoID: 4, WorkflowCommitSHA: sha,
	}
	if err := PrepareRunAndInsert(t.Context(), []byte(files[entry]), run, nil); err != nil {
		return nil, err
	}
	return run, nil
}

func pEmit(t *testing.T, runID int64) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("PANIC in emitter: %v", r)
		}
	}()
	return checkJobsByRunID(t.Context(), runID)
}

// pDrive plays emitter + one runner until nothing moves. Every claimed task is reported as success.
func pDrive(t *testing.T, runner *actions_model.ActionRunner, run *actions_model.ActionRun) (notes []string) {
	ctx := t.Context()
	seen := map[string]bool{}
	note := func(s string) {
		if !seen[s] {
			seen[s] = true
			notes = append(notes, s)
		}
	}
	for range 40 {
		progressed := false
		before := pTree(t, run)
		if err := pEmit(t, run.ID); err != nil {
			note("emitter: " + err.Error())
		}
		for {
			task, ok, err := actions_model.CreateTaskForRunner(ctx, runner)
			if err != nil {
				note("runner poll: " + err.Error())
				break
			}
			if !ok {
				break
			}
			progressed = true
			_, err = actions_model.UpdateTaskByState(ctx, runner.ID, &runnerv1.TaskState{Id: task.ID, Result: runnerv1.Result_RESULT_SUCCESS, StoppedAt: timestamppb.Now()})
			require.NoError(t, err)
		}
		if !progressed && before == pTree(t, run) {
			break
		}
	}
	return notes
}

func pJobs(t *testing.T, run *actions_model.ActionRun) actions_model.ActionJobList {
	r, err := actions_model.GetRunByRepoAndID(t.Context(), 4, run.ID)
	require.NoError(t, err)
	jobs, err := actions_model.GetRunJobsByRunAndAttemptID(t.Context(), run.ID, r.LatestAttemptID)
	require.NoError(t, err)
	return jobs
}

func pTree(t *testing.T, run *actions_model.ActionRun) string {
	jobs := pJobs(t, run)
	r, _ := actions_model.GetRunByRepoAndID(t.Context(), 4, run.ID)
	children := map[int64][]*actions_model.ActionRunJob{}
	for _, j := range jobs {
		children[j.ParentJobID] = append(children[j.ParentJobID], j)
	}
	var b strings.Builder
	fmt.Fprintf(&b, "run=%s", r.Status)
	var walk func(parent int64, depth int)
	walk = func(parent int64, depth int) {
		for _, j := range children[parent] {
			fmt.Fprintf(&b, "\n        %s%s = %s", strings.Repeat("  ", depth), j.Name, j.Status)
			if j.IsReusableCaller {
				b.WriteString(" (calls " + j.CallUses + ")")
			}
			walk(j.ID, depth+1)
		}
	}
	walk(0, 0)
	return b.String()
}

func pScenario(t *testing.T, runner *actions_model.ActionRunner, title string, files map[string]string, entry string) *actions_model.ActionRun {
	sha := pCommit(t, files)
	run, err := pTrigger(t, sha, files, entry)
	if err != nil {
		t.Logf("%s\n    => NO RUN CREATED: %v", title, err)
		return nil
	}
	notes := pDrive(t, runner, run)
	t.Logf("%s\n    => %s%s", title, pTree(t, run), pNotes(notes))
	return run
}

func pNotes(notes []string) string {
	if len(notes) == 0 {
		return ""
	}
	return "\n    notes: " + strings.Join(notes, "\n           ")
}

