const wfDir = ".gitea/workflows/"

func pGit(t *testing.T, dir string, env []string, stdin string, args ...string) string {
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), env...)
	cmd.Stdin = strings.NewReader(stdin)
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	require.NoError(t, cmd.Run(), "git %v: %s", args, errb.String())
	return strings.TrimSpace(out.String())
}

// pCommit writes the given workflow files as one commit into the test copy of user5/repo4 and returns its SHA.
func pCommit(t *testing.T, files map[string]string) string {
	dir := repo_model.RepoPath("user5", "repo4")
	idx := filepath.Join(t.TempDir(), "index")
	env := []string{"GIT_INDEX_FILE=" + idx, "GIT_AUTHOR_NAME=p", "GIT_AUTHOR_EMAIL=p@example.com", "GIT_COMMITTER_NAME=p", "GIT_COMMITTER_EMAIL=p@example.com"}
	for name, content := range files {
		blob := pGit(t, dir, env, content, "hash-object", "-w", "--stdin")
		pGit(t, dir, env, "", "update-index", "--add", "--cacheinfo", "100644,"+blob+","+wfDir+name)
	}
	tree := pGit(t, dir, env, "", "write-tree")
	return pGit(t, dir, env, "", "commit-tree", tree, "-m", "probe")
}

