		t.Logf("%s: %s | name#attempt_job_id:%s", label, strings.SplitN(pTree(t, run), "\n", 2)[0], out)
	}
	show("attempt 1")
	repo := unittest.AssertExistsAndLoadBean(t, &repo_model.Repository{ID: 4})
	doer := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 5})
	r, _ := actions_model.GetRunByRepoAndID(ctx, 4, run.ID)
	_, err = RerunWorkflowRunJobs(ctx, repo, r, doer, nil)
	require.NoError(t, err)
	require.NoError(t, pEmit(t, run.ID))
	show("attempt 2 (re-run all)")
}
