29	// CreateCommitStatusForRunJobs creates a commit status for the given job if it has a supported event and related commit.
30	// It won't return an error failed, but will log it, because it's not critical.
31	func CreateCommitStatusForRunJobs(ctx context.Context, run *actions_model.ActionRun, jobs ...*actions_model.ActionRunJob) {
32		// don't create commit status for cron job
33		if run.ScheduleID != 0 {
34			return
35		}
36	
37		event, commitID, err := getCommitStatusEventNameAndCommitID(run)
38		if err != nil {
39			log.Error("GetCommitStatusEventNameAndSHA: %v", err)
40		}
41		if event == "" || commitID == "" {
42			return // unsupported event, or no commit id, or error occurs, do nothing
43		}
44	
45		if err = run.LoadAttributes(ctx); err != nil {
46			log.Error("run.LoadAttributes: %v", err)
47			return
48		}
49	
50		// Compute the scoped source-repo prefix once per run; it is identical for every job.
51		var scopedPrefix string
52		if run.IsScopedRun {
53			scopedPrefix = actions_model.ScopedStatusContextPrefix(ctx, run.WorkflowRepoID)
54		}
55	
56		for _, job := range jobs {
57			if err = createCommitStatus(ctx, run.Repo, event, commitID, scopedPrefix, run, job); err != nil {
58				log.Error("Failed to create commit status for job %d: %v", job.ID, err)
59			}
60		}
61	}
62	
63	func GetRunsFromCommitStatuses(ctx context.Context, statuses []*git_model.CommitStatus) ([]*actions_model.ActionRun, error) {
64		runMap := make(map[int64]*actions_model.ActionRun)
65		for _, status := range statuses {
66			runID, _, ok := status.ParseGiteaActionsTargetURL(ctx)
67			if !ok {
68				continue
69			}
70			_, ok = runMap[runID]
71			if !ok {
72				run, err := actions_model.GetRunByRepoAndID(ctx, status.RepoID, runID)
73				if err != nil {
74					if errors.Is(err, util.ErrNotExist) {
75						// the run may be deleted manually, just skip it
76						continue
77					}
78					return nil, fmt.Errorf("GetRunByRepoAndID: %w", err)
79				}
80				runMap[runID] = run
81			}
82		}
83		runs := make([]*actions_model.ActionRun, 0, len(runMap))
84		for _, run := range runMap {
85			runs = append(runs, run)
86		}
87		return runs, nil
88	}
89	
90	func getCommitStatusEventNameAndCommitID(run *actions_model.ActionRun) (event, commitID string, _ error) {
91		switch run.Event {
92		case webhook_module.HookEventPush:
93			event = "push"
94			payload, err := run.GetPushEventPayload()
95			if err != nil {
96				return "", "", fmt.Errorf("GetPushEventPayload: %w", err)
97			}
98			if payload.HeadCommit == nil {
99				return "", "", errors.New("head commit is missing in event payload")
100			}
101			commitID = payload.HeadCommit.ID
102		case // pull_request
103			webhook_module.HookEventPullRequest,
104			webhook_module.HookEventPullRequestSync,
105			webhook_module.HookEventPullRequestAssign,
106			webhook_module.HookEventPullRequestLabel,
107			webhook_module.HookEventPullRequestReviewRequest,
108			webhook_module.HookEventPullRequestMilestone:
109			if run.TriggerEvent == actions_module.GithubEventPullRequestTarget {
110				event = "pull_request_target"
111			} else {
112				event = "pull_request"
113			}
114			payload, err := run.GetPullRequestEventPayload()
115			if err != nil {
116				return "", "", fmt.Errorf("GetPullRequestEventPayload: %w", err)
117			}
118			if payload.PullRequest == nil {
119				return "", "", errors.New("pull request is missing in event payload")
120			} else if payload.PullRequest.Head == nil {
121				return "", "", errors.New("head of pull request is missing in event payload")
122			}
123			commitID = payload.PullRequest.Head.Sha
124		case // pull_request_review events share the same PullRequestPayload as pull_request
125			webhook_module.HookEventPullRequestReviewApproved,
126			webhook_module.HookEventPullRequestReviewRejected,
127			webhook_module.HookEventPullRequestReviewComment:
128			event = run.TriggerEvent
129			payload, err := run.GetPullRequestEventPayload()
130			if err != nil {
131				return "", "", fmt.Errorf("GetPullRequestEventPayload: %w", err)
132			}
133			if payload.PullRequest == nil {
134				return "", "", errors.New("pull request is missing in event payload")
135			} else if payload.PullRequest.Head == nil {
136				return "", "", errors.New("head of pull request is missing in event payload")
137			}
138			commitID = payload.PullRequest.Head.Sha
139		case webhook_module.HookEventRelease:
140			event = string(run.Event)
141			commitID = run.CommitSHA
142		default: // do nothing, return empty
143		}
144		return event, commitID, nil
145	}
146	
147	func createCommitStatus(ctx context.Context, repo *repo_model.Repository, event, commitID, scopedPrefix string, run *actions_model.ActionRun, job *actions_model.ActionRunJob) error {
148		displayName := actions_module.WorkflowDisplayName(run.WorkflowID, job.WorkflowPayload)
149		ctxName := actions_module.WorkflowStatusContextName(displayName, job.Name, event) // git_model.NewCommitStatus also trims spaces
150		if run.IsScopedRun {
151			// A scoped run is prefixed with its source repo (set off by a colon) so it stays distinct from a same-named repo-level workflow.
152			// scopedPrefix is computed once per run by the caller. The settings page derives the same string to preview expected checks.
153			ctxName = actions_module.ScopedWorkflowStatusContextName(scopedPrefix, displayName, job.Name, event)
154		}
155		targetURL := fmt.Sprintf("%s/jobs/%d", run.Link(), job.ID)
156		return createWorkflowCommitStatus(ctx, repo, commitID, ctxName, run.WorkflowID, toCommitStatus(job.Status), targetURL, toCommitStatusDescription(job))
157	}
158	
159	// getAllRequiredStatusContextGlobs returns the compiled globs of every status-check context required in the repo:
160	// its protected branch rules' contexts and its required scoped workflows' patterns (see EffectiveRequiredContexts).
161	func getAllRequiredStatusContextGlobs(ctx context.Context, repo *repo_model.Repository) ([]glob.Glob, error) {
162		rules, err := git_model.FindRepoProtectedBranchRules(ctx, repo.ID)
163		if err != nil {
164			return nil, fmt.Errorf("FindRepoProtectedBranchRules: %w", err)
165		}
166		required, err := pull_service.EffectiveRequiredContexts(ctx, repo, rules...)
167		if err != nil {
168			return nil, fmt.Errorf("EffectiveRequiredContexts: %w", err)
169		}
170		globs := make([]glob.Glob, 0, len(required))
171		for _, c := range required {
172			if gp, err := glob.Compile(c); err != nil {
173				log.Error("glob.Compile %q: %v", c, err)
174			} else {
175				globs = append(globs, gp)
176			}
177		}
178		return globs, nil
179	}
180	
181	// CreateSkippedCommitStatusForFilteredWorkflow posts a skipped commit status for each job of a
182	// workflow that matched the triggering event but was excluded by a branch/paths filter.
183	// This lets a required status check tied to that context be satisfied without the workflow running.
184	// Only contexts matching requiredGlobs are posted; a non-required context gets no skipped status.
185	// No ActionRun is created, so the status has no target URL (there is no run/job to link to).
186	// A non-empty scopedPrefix prefixes each context with its source repo, matching scoped runs.
187	//
188	// TODO: requiredGlobs over-approximates by including every protected branch rule's required contexts.
189	// If possible, the set should be narrowed to the required contexts of a specific branch protection rule (and the contexts from required scoped workflows).
190	// Currently, a `push` event must keep the repo-wide union since its future pull request base branch is unknown.
191	func CreateSkippedCommitStatusForFilteredWorkflow(ctx context.Context, repo *repo_model.Repository, event webhook_module.HookEventType, triggerEvent, workflowID string, content []byte, payload api.Payloader, scopedPrefix string, requiredGlobs []glob.Glob) error {
192		if len(requiredGlobs) == 0 {
193			return nil // nothing is required, so no skipped status is needed
194		}
195	
196		// Derive the status event name and target commit from the payload.
197		// TODO: this mirrors getCommitStatusEventNameAndCommitID, which derives the same from a persisted run. Should merge the logic if possible.
198		var statusEvent, commitID string
199		switch event {
200		case webhook_module.HookEventPush:
201			if p, ok := payload.(*api.PushPayload); ok && p.HeadCommit != nil {
202				statusEvent, commitID = "push", p.HeadCommit.ID
203			}
204		case webhook_module.HookEventPullRequest,
205			webhook_module.HookEventPullRequestSync,
206			webhook_module.HookEventPullRequestAssign,
207			webhook_module.HookEventPullRequestLabel,
208			webhook_module.HookEventPullRequestReviewRequest,
209			webhook_module.HookEventPullRequestMilestone:
210			if p, ok := payload.(*api.PullRequestPayload); ok && p.PullRequest != nil && p.PullRequest.Head != nil {
211				statusEvent, commitID = "pull_request", p.PullRequest.Head.Sha
212				if triggerEvent == actions_module.GithubEventPullRequestTarget {
213					statusEvent = "pull_request_target"
214				}
215			}
216		}
217		if statusEvent == "" || commitID == "" {
218			return nil // unsupported event or missing commit id, nothing to post
219		}
220	
221		workflows, err := jobparser.Parse(content)
222		if err != nil {
223			return fmt.Errorf("jobparser.Parse: %w", err)
224		}
225	
226		displayName := actions_module.WorkflowDisplayName(workflowID, content)
227		for _, sw := range workflows {
228			_, job := sw.Job()
229			if job == nil {
230				continue
231			}
232			jobName := util.EllipsisDisplayString(job.Name, 255) // run creation truncates job names the same way
233			ctxName := actions_module.WorkflowStatusContextName(displayName, jobName, statusEvent)
234			if scopedPrefix != "" {
235				ctxName = actions_module.ScopedWorkflowStatusContextName(scopedPrefix, displayName, jobName, statusEvent)
236			}
237			// Only a required context needs the skipped status.
238			if !slices.ContainsFunc(requiredGlobs, func(gp glob.Glob) bool { return gp.Match(ctxName) }) {
239				continue
240			}
241			// "Skipped" mirrors toCommitStatusDescription for StatusSkipped.
242			if err := createWorkflowCommitStatus(ctx, repo, commitID, ctxName, workflowID, commitstatus.CommitStatusSkipped, "", "Skipped"); err != nil {
243				return err
244			}
245		}
246		return nil
247	}
248	
249	// createWorkflowCommitStatus posts the commit status for one workflow-job context.
250	func createWorkflowCommitStatus(ctx context.Context, repo *repo_model.Repository, commitID, ctxName, workflowID string, state commitstatus.CommitStatusState, targetURL, description string) error {
251		// Mix the workflow file path into the hash so two workflow files that
252		// share the same `name:` and job name produce distinct commit statuses
253		// even though they render identically — matching GitHub's behavior
254		// (issue #35699).
255		ctxHash := git_model.HashCommitStatusContext(ctxName + "\x00" + workflowID)
256		// Pre-fix rows were hashed from Context alone. If a pre-existing row with
257		// the legacy hash is still the "latest" for this SHA, reuse that hash so
258		// the new row supersedes it; otherwise the old pending status would stay
259		// stuck forever (it lives in its own dedupe group). Only relevant for
260		// in-flight workflows at upgrade time.
261		legacyHash := git_model.HashCommitStatusContext(ctxName)
262	
263		statuses, err := git_model.GetLatestCommitStatus(ctx, repo.ID, commitID, db.ListOptionsAll)
264		if err != nil {
265			return fmt.Errorf("GetLatestCommitStatus: %w", err)
266		}
267		for _, v := range statuses {
268			if v.ContextHash == legacyHash && v.Context == ctxName {
269				ctxHash = legacyHash
270				break
271			}
272		}
273		for _, v := range statuses {
274			if v.ContextHash == ctxHash {
275				if v.State == state && v.TargetURL == targetURL && v.Description == description {
276					return nil
277				}
278				break
279			}
280		}
281	
282		creator := user_model.NewActionsUser()
283		status := git_model.CommitStatus{
284			SHA:         commitID,
285			TargetURL:   targetURL,
286			Description: description,
287			Context:     ctxName,
288			ContextHash: ctxHash,
289			State:       state,
290			CreatorID:   creator.ID,
291		}
292	
293		return commitstatus_service.CreateCommitStatus(ctx, repo, creator, commitID, &status)
294	}
295	
296	func toCommitStatusDescription(job *actions_model.ActionRunJob) string {
297		switch job.Status {
298		// TODO: if we want support description in different languages, we need to support i18n placeholders in it
299		case actions_model.StatusSuccess:
300			return fmt.Sprintf("Successful in %s", job.Duration())
301		case actions_model.StatusFailure:
302			return fmt.Sprintf("Failing after %s", job.Duration())
303		case actions_model.StatusCancelled:
304			return fmt.Sprintf("Canceled after %s", job.Duration())
305		case actions_model.StatusSkipped:
306			return "Skipped"
307		case actions_model.StatusRunning:
308			return "In progress"
309		case actions_model.StatusCancelling:
310			return "Canceling"
311		case actions_model.StatusWaiting:
312			return "Waiting to run"
313		case actions_model.StatusBlocked:
314			return "Blocked by required conditions"
315		default:
316			return fmt.Sprintf("Unknown status: %d", job.Status)
317		}
318	}
319	
320	func toCommitStatus(status actions_model.Status) commitstatus.CommitStatusState {
321		switch status {
322		case actions_model.StatusSuccess:
323			return commitstatus.CommitStatusSuccess
324		case actions_model.StatusFailure, actions_model.StatusCancelled:
325			return commitstatus.CommitStatusFailure
326		case actions_model.StatusWaiting, actions_model.StatusBlocked, actions_model.StatusRunning, actions_model.StatusCancelling:
327			return commitstatus.CommitStatusPending
328		case actions_model.StatusSkipped:
329			return commitstatus.CommitStatusSkipped
330		default:
331			return commitstatus.CommitStatusError
332		}
333	}
