   164		if opts.RepoID > 0 {
   165			cond = cond.And(builder.Eq{"repo_id": opts.RepoID})
   166		}
   167		if opts.RunID > 0 {
   168			cond = cond.And(builder.Eq{"run_id": opts.RunID})
   169		}
   170		if opts.RunAttemptID.Has() {
   171			cond = cond.And(builder.Eq{"run_attempt_id": opts.RunAttemptID.Value()})
   172		}
   173		if opts.ArtifactName != "" {
   174			cond = cond.And(builder.Eq{"artifact_name": opts.ArtifactName})
   175		}
   176		if opts.Status > 0 {
   177			cond = cond.And(builder.Eq{"status": opts.Status})
   178		}
   179		if opts.FinalizedArtifactsV4 {
   180			cond = cond.And(builder.Eq{"status": ArtifactStatusUploadConfirmed}.Or(builder.Eq{"status": ArtifactStatusExpired}))
   181			// see the comment of ActionArtifact.ContentEncodingOrType: "*/*" means the field is a content type
   182			cond = cond.And(builder.Like{"content_encoding", "%/%"})
   183		}
   184	
   185		return cond
   186	}
