   188	// ActionArtifactMeta is the meta-data of an artifact
   189	type ActionArtifactMeta struct {
   190		ArtifactName string
   191		FileSize     int64
   192		Status       ArtifactStatus
   193		ExpiredUnix  timeutil.TimeStamp
   194	}
