   196	// ListUploadedArtifactsMetaByRunAttempt returns uploaded artifacts meta scoped to a specific run and attempt.
   197	// Pass runAttemptID=0 to target legacy artifacts (pre-v331) belonging to the run.
   198	func ListUploadedArtifactsMetaByRunAttempt(ctx context.Context, repoID, runID, runAttemptID int64) ([]*ActionArtifactMeta, error) {
   199		arts := make([]*ActionArtifactMeta, 0, 10)
   200		return arts, db.GetEngine(ctx).Table("action_artifact").
   201			Where("repo_id=? AND run_id=? AND run_attempt_id=? AND (status=? OR status=?)", repoID, runID, runAttemptID, ArtifactStatusUploadConfirmed, ArtifactStatusExpired).
   202			GroupBy("artifact_name").
   203			Select("artifact_name, sum(file_size) as file_size, max(status) as status, max(expired_unix) as expired_unix").
   204			Find(&arts)
   205	}
