   214	// ListPendingDeleteArtifacts returns all artifacts in pending-delete status.
   215	// limit is the max number of artifacts to return.
   216	func ListPendingDeleteArtifacts(ctx context.Context, limit int) ([]*ActionArtifact, error) {
   217		arts := make([]*ActionArtifact, 0, limit)
   218		return arts, db.GetEngine(ctx).
   219			Where("status = ?", ArtifactStatusPendingDeletion).Limit(limit).Find(&arts)
   220	}
