   222	// SetArtifactExpired sets an artifact to expired
   223	func SetArtifactExpired(ctx context.Context, artifactID int64) error {
   224		_, err := db.GetEngine(ctx).Where("id=? AND status = ?", artifactID, ArtifactStatusUploadConfirmed).Cols("status").Update(&ActionArtifact{Status: ArtifactStatusExpired})
   225		return err
   226	}
