   228	// SetArtifactNeedDeleteByID sets an artifact to need-delete by ID, cron job will delete it.
   229	func SetArtifactNeedDeleteByID(ctx context.Context, artifactID int64) error {
   230		_, err := db.GetEngine(ctx).Where("id=? AND status = ?", artifactID, ArtifactStatusUploadConfirmed).Cols("status").Update(&ActionArtifact{Status: ArtifactStatusPendingDeletion})
   231		return err
