   241	// GetArtifactsByRunAttemptAndName returns all artifacts with the given name in the specified run attempt.
   242	// This supports both attempt-scoped data and legacy artifacts with run_attempt_id=0.
   243	func GetArtifactsByRunAttemptAndName(ctx context.Context, runID, runAttemptID int64, artifactName string) ([]*ActionArtifact, error) {
   244		arts := make([]*ActionArtifact, 0)
   245		return arts, db.GetEngine(ctx).
   246			Where("run_id = ? AND run_attempt_id = ? AND artifact_name = ?", runID, runAttemptID, artifactName).
   247			OrderBy("id").
   248			Find(&arts)
   249	}
