   252	func SetArtifactDeleted(ctx context.Context, artifactID int64) error {
   253		_, err := db.GetEngine(ctx).ID(artifactID).Cols("status").Update(&ActionArtifact{Status: ArtifactStatusDeleted})
   254		return err
