    62	// ActionArtifact is a file that is stored in the artifact storage.
    63	type ActionArtifact struct {
    64		ID                 int64 `xorm:"pk autoincr"`
    65		RunID              int64 `xorm:"index unique(runid_attempt_name_path)"` // The run id of the artifact
    66		RunAttemptID       int64 `xorm:"index unique(runid_attempt_name_path) NOT NULL DEFAULT 0"`
    67		RunnerID           int64
    68		RepoID             int64 `xorm:"index"`
    69		OwnerID            int64
    70		CommitSHA          string
    71		StoragePath        string // The path to the artifact in the storage
    72		FileSize           int64  // The size of the artifact in bytes
    73		FileCompressedSize int64  // The size of the artifact in bytes after gzip compression
    74	
