// pClaim claims the next task and returns what the server would hand to the runner for it.
func pClaim(t *testing.T, runner *actions_model.ActionRunner) (*actions_model.ActionTask, *runnerv1.Task) {
	task, ok, err := actions_model.CreateTaskForRunner(t.Context(), runner)
	require.NoError(t, err)
	if !ok {
		return nil, nil
	}
	rt, _, err := buildRunnerTask(t.Context(), task)
	require.NoError(t, err)
	return task, rt
}

func pFinish(t *testing.T, runner *actions_model.ActionRunner, task *actions_model.ActionTask, result runnerv1.Result) {
	_, err := actions_model.UpdateTaskByState(t.Context(), runner.ID, &runnerv1.TaskState{Id: task.ID, Result: result, StoppedAt: timestamppb.Now()})
	require.NoError(t, err)
	job, err := actions_model.GetRunJobByRepoAndID(t.Context(), 4, task.JobID)
	require.NoError(t, err)
	require.NoError(t, job.LoadAttributes(t.Context()))
	CreateCommitStatusForRunJobs(t.Context(), job.Run, job) // as the UpdateTask RPC handler does
}

func pCtx(rt *runnerv1.Task, keys ...string) string {
	m := rt.Context.AsMap()
	out := []string{}
	for _, k := range keys {
		var v any = m
		for _, part := range strings.Split(k, ".") {
			if mm, ok := v.(map[string]any); ok {
				v = mm[part]
			} else {
				v = nil
			}
		}
		out = append(out, fmt.Sprintf("%s=%v", k, v))
	}
	return strings.Join(out, "  ")
}

func pEventKeys(rt *runnerv1.Task) string {
	ev, _ := rt.Context.AsMap()["event"].(map[string]any)
	keys := []string{}
	for k := range ev {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return strings.Join(keys, ",")
}

func pSecretNames(rt *runnerv1.Task) string {
	keys := []string{}
	for k := range rt.Secrets {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return strings.Join(keys, ",")
}

func pStatuses(t *testing.T, sha string) string {
	sts, err := git_model.GetLatestCommitStatus(t.Context(), 4, sha, db.ListOptionsAll)
	require.NoError(t, err)
	out := []string{}
	for _, s := range sts {
		out = append(out, fmt.Sprintf("\n        %-34q %-8s %-22q -> %s", s.Context, s.State, s.Description, s.TargetURL[strings.Index(s.TargetURL, "/actions"):]))
	}
	sort.Strings(out)
	return strings.Join(out, "")
}

func pJobs(t *testing.T, runID int64) string {
	run, err := actions_model.GetRunByRepoAndID(t.Context(), 4, runID)
	require.NoError(t, err)
	jobs, err := actions_model.GetRunJobsByRunAndAttemptID(t.Context(), runID, run.LatestAttemptID)
	require.NoError(t, err)
	out := "run=" + run.Status.String()
	for _, j := range jobs {
		out += fmt.Sprintf(" | %s(job %d)=%s", j.Name, j.ID, j.Status)
	}
	return out
}

