const wfDir = ".gitea/workflows/"

func pGit(t *testing.T, env []string, stdin string, args ...string) string {
	cmd := exec.Command("git", args...)
	cmd.Dir = repo_model.RepoPath("user5", "repo4")
	cmd.Env = append(os.Environ(), env...)
	cmd.Stdin = strings.NewReader(stdin)
	var out, errb bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &errb
	require.NoError(t, cmd.Run(), "git %v: %s", args, errb.String())
	return strings.TrimSpace(out.String())
}

func pCommitMsg(t *testing.T, msg string, files map[string]string) string {
	idx := filepath.Join(t.TempDir(), "index")
	env := []string{"GIT_INDEX_FILE=" + idx, "GIT_AUTHOR_NAME=p", "GIT_AUTHOR_EMAIL=p@example.com", "GIT_COMMITTER_NAME=p", "GIT_COMMITTER_EMAIL=p@example.com"}
	for name, content := range files {
		blob := pGit(t, env, content, "hash-object", "-w", "--stdin")
		pGit(t, env, "", "update-index", "--add", "--cacheinfo", "100644,"+blob+","+wfDir+name)
	}
	return pGit(t, env, "", "commit-tree", pGit(t, env, "", "write-tree"), "-m", msg+"\n\n"+fmt.Sprint(time.Now().UnixNano()))
}

func pCommit(t *testing.T, files map[string]string) string { return pCommitMsg(t, "probe", files) }

func pSetup(t *testing.T) (*actions_model.ActionRunner, *repo_model.Repository, *git.Repository) {
	require.NoError(t, unittest.PrepareTestDatabase())
	setting.Actions.SkipWorkflowStrings = []string{"[skip ci]", "[ci skip]", "[no ci]", "[skip actions]", "[actions skip]"}
	if jobEmitterQueue == nil {
		jobEmitterQueue = queue.CreateUniqueQueue(t.Context(), "probe_ready_job", func(items ...*jobUpdate) []*jobUpdate { return nil })
	}
	runner := &actions_model.ActionRunner{UUID: fmt.Sprintf("11111111-2222-3333-4444-%012d", time.Now().UnixNano()%1e12), Name: "probe", RepoID: 4, AgentLabels: []string{"probe-linux"}}
	runner.GenerateAndFillToken()
	require.NoError(t, db.Insert(t.Context(), runner))
	repo := unittest.AssertExistsAndLoadBean(t, &repo_model.Repository{ID: 4})
	gitRepo, err := gitrepo.OpenRepository(t.Context(), repo)
	require.NoError(t, err)
	t.Cleanup(func() { gitRepo.Close() })
	return runner, repo, gitRepo
}

func pEmit(t *testing.T, runID int64) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("PANIC in emitter: %v", r)
		}
	}()
	return checkJobsByRunID(t.Context(), runID)
}

func pLatestRun(t *testing.T) *actions_model.ActionRun {
	run := &actions_model.ActionRun{}
