func pFinish(t *testing.T, runner *actions_model.ActionRunner, task *actions_model.ActionTask, result runnerv1.Result) {
	_, err := actions_model.UpdateTaskByState(t.Context(), runner.ID, &runnerv1.TaskState{Id: task.ID, Result: result, StoppedAt: timestamppb.Now()})
	require.NoError(t, err)
