// 11. re-run selection after duplicate child IDs
func TestProbeJ_RerunDuplicateSelect(t *testing.T) {
	runner, repo, _ := pSetup(t)
	ctx := t.Context()
	files := map[string]string{
		"test.yml": "on:\n  workflow_call:\njobs:\n  test:\n    name: Test ${{ matrix.os }}\n    strategy:\n      matrix:\n        os: [linux, windows]\n        node: [18, 20]\n    runs-on: probe-linux\n    steps:\n      - run: npm test\n",
		"top.yml":  "on: push\njobs:\n  ci:\n    uses: ./.gitea/workflows/test.yml\n",
	}
	sha := pCommit(t, files)
	run := pInsert(t, sha, "top.yml", files["top.yml"])
	doer := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 5})
	drive := func(failFirst string) {
		failed := false
		for range 10 {
			require.NoError(t, pEmit(t, run.ID))
			for {
				task, rt := pClaim(t, runner)
				if rt == nil {
					break
				}
				res := runnerv1.Result_RESULT_SUCCESS
				if !failed && task.Job.Name == failFirst {
					res, failed = runnerv1.Result_RESULT_FAILURE, true
				}
				pFinish(t, runner, task, res)
			}
		}
		require.NoError(t, pEmit(t, run.ID))
	}
	drive("")
	r, _ := actions_model.GetRunByRepoAndID(ctx, 4, run.ID)
	_, err := RerunWorkflowRunJobs(ctx, repo, r, doer, nil) // re-run all: children now share IDs
	require.NoError(t, err)
	drive("Test linux") // one of the two "Test linux" legs fails in attempt 2
	t.Logf("attempt 2 finished: %s", pJobs(t, run.ID))
	r, _ = actions_model.GetRunByRepoAndID(ctx, 4, run.ID)
	jobs, _ := actions_model.GetRunJobsByRunAndAttemptID(ctx, run.ID, r.LatestAttemptID)
	var target *actions_model.ActionRunJob
	for _, j := range jobs {
		if j.Status == actions_model.StatusFailure && !j.IsReusableCaller {
			target = j
		}
	}
	require.NotNil(t, target)
	_, err = RerunWorkflowRunJobs(ctx, repo, r, doer, []*actions_model.ActionRunJob{target}) // re-run only the failed leg
	require.NoError(t, err)
	t.Logf("re-run of the ONE failed leg -> attempt 3: %s", pJobs(t, run.ID))
}
