func sm(m map[string]string) string {
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	var b strings.Builder
	for _, k := range ks {
		fmt.Fprintf(&b, "%s=%q;", k, m[k])
	}
	return b.String()
}

func typed(m map[string]any) string {
	ks := make([]string, 0, len(m))
	for k := range m {
		ks = append(ks, k)
	}
	sort.Strings(ks)
	var b strings.Builder
	for _, k := range ks {
		fmt.Fprintf(&b, "%s=%T(%v) ", k, m[k], m[k])
	}
	return strings.TrimSpace(b.String())
}

// describe lists everything the runner would read from a job, as flat key -> value.
func describe(wf *model.Workflow, job *model.Job) map[string]string {
	d := map[string]string{
		"workflow.env": sm(wf.Env), "workflow.defaults": fmt.Sprintf("%+v", wf.Defaults),
		"job.if": job.If.Value, "job.env": sm(job.Environment()), "job.timeout": job.TimeoutMinutes, "job.outputs": sm(job.Outputs),
		"job.defaults": fmt.Sprintf("%+v", job.Defaults), "job.runs-on": fmt.Sprint(job.RunsOn()),
	}
	if c := job.Container(); c != nil {
		d["job.container"] = fmt.Sprintf("%s|%s|%v|%v|%q|%s|%v", c.Image, sm(c.Env), c.Ports, c.Volumes, c.Options, sm(c.Credentials), c.Cmd)
	}
	for name, c := range job.Services {
		d["job.services."+name] = fmt.Sprintf("%s|%s|%v|%v|%q|%s|%v", c.Image, sm(c.Env), c.Ports, c.Volumes, c.Options, sm(c.Credentials), c.Cmd)
	}
	if job.Strategy != nil {
		d["job.strategy"] = job.Strategy.FailFastString + "|" + job.Strategy.MaxParallelString
	}
	for i, s := range job.Steps {
		if s == nil {
			continue
		}
		p := fmt.Sprintf("step%d.", i)
		d[p+"id"], d[p+"name"], d[p+"uses"], d[p+"run"], d[p+"shell"], d[p+"cwd"] = s.ID, s.Name, s.Uses, s.Run, s.Shell, s.WorkingDirectory
		d[p+"if"], d[p+"with"], d[p+"env"], d[p+"timeout"], d[p+"coe"] = s.If.Value, sm(s.With), sm(s.Environment()), s.TimeoutMinutes, s.RawContinueOnError
	}
	return d
}

func TestProbeR1_DeepRoundTrip(t *testing.T) {
	cases := map[string]string{
		"scripts": "on: push\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - name: Build\n        run: |\n          set -euo pipefail\n\n          cat > config.json <<EOF\n          {\"a\": 1}\n          EOF\n          \tindented with a tab\n          trailing spaces   \n      - run: >-\n          curl -H \"Authorization: token ${{ secrets.TOKEN }}\"\n          https://example.com/api?x=1&y=[2]#frag\n      - run: |+\n          echo keep\n\n\n      - run: 'echo \"key: value\" && echo {a} *b &c !d %e @f'\n",
		"crlf": strings.ReplaceAll("on: push\njobs:\n  build:\n    runs-on: ubuntu-latest\n    env:\n      A: one\n    steps:\n      - name: Two lines\n        run: |\n          echo one\n          echo two\n        env:\n          B: two\n", "\n", "\r\n"),
		"values that look like other types": `on: push
env:
  DEBUG: on
  VERSION: "1.10"
  ZIP: "012345"
  EMPTY: ""
  NULLISH: "null"
  TILDE: "~"
  HEX: "0x10"
  SCI: "1e3"
  DATE: "2024-01-01"
  UNDERSCORE: "1_000"
jobs:
  build:
    runs-on: ubuntu-latest
    timeout-minutes: 30
    env:
      PY: "3.10"
      FLAG: "yes"
      BOOL: "true"
      COLON: "a: b"
      HASH: "#not-a-comment"
      DASH: "- item"
      STAR: "*alias"
      AT: "@at"
      LEAD: " leading space"
      TRAIL: "trailing space "
      MULTI: "line1\nline2\n"
      QUOTES: "it's \"quoted\""
      UNICODE: "déjà vu ✅"
    outputs:
      version: ${{ steps.v.outputs.version }}
      num: "007"
    steps:
      - id: v
        name: "Step: with colon # and hash"
        uses: actions/setup-python@v5
        if: "!cancelled() && github.ref == 'refs/heads/main'"
        shell: bash -euo pipefail {0}
        working-directory: ./a b/c
        timeout-minutes: 5
        continue-on-error: true
        with:
          python-version: "3.10"
          node-version: "20"
          token: "0123"
          cache: true
          fetch-depth: 0
          flag: "yes"
          empty: ""
          lead: " x"
          multi: |
            a
            b
          script: "  const a = 1;\nreturn a;\n"
        env:
          A: "1.0"
          B: "null"
          C: "~"
          D: "true"
          E: "0o17"
          F: "1_000"
          G: "2024-01-01T00:00:00Z"
          H: "!tagged"
          I: "{braces}"
          J: "[brackets]"
          K: "%percent"
          L: "back\\slash"
`,
		"services + container": "on: push\ndefaults:\n  run:\n    shell: bash\n    working-directory: ./app\njobs:\n  test:\n    runs-on: [self-hosted, linux]\n    defaults:\n      run:\n        shell: sh\n    strategy:\n      fail-fast: false\n      max-parallel: 2\n    container:\n      image: node:20\n      options: --user 1001 --cpus 2\n      env:\n        CI: true\n        N: 5\n      volumes:\n        - /cache:/cache\n      credentials:\n        username: bot\n        password: ${{ secrets.REG }}\n    services:\n      db:\n        image: postgres:16\n        env:\n          POSTGRES_PASSWORD: 12345\n          POSTGRES_DB: \"0010\"\n        ports:\n          - 5432:5432\n          - 6379\n        options: >-\n          --health-cmd pg_isready\n          --health-interval 10s\n    steps:\n      - run: npm test\n",
		"anchors + merge keys": "on: push\nx-defaults: &d\n  runs-on: ubuntu-latest\n  timeout-minutes: 10\n  env:\n    SHARED: \"1.0\"\njobs:\n  a:\n    <<: *d\n    steps: &steps\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n      - run: make\n  b:\n    <<: *d\n    steps: *steps\n",
	}
	names := make([]string, 0, len(cases))
	for n := range cases {
		names = append(names, n)
	}
	sort.Strings(names)
	for _, name := range names {
		content := []byte(cases[name])
		origWf, err := model.ReadWorkflow(bytes.NewReader(content))
		require.NoError(t, err, name)
		wfs, err := jobparser.Parse(content)
		require.NoError(t, err, name)
		diffs, compared := []string{}, 0
		for _, sw := range wfs {
			id, job := sw.Job()
			require.NoError(t, sw.SetJob(id, job.EraseNeeds()))
			payload, _ := sw.Marshal() // exactly what InsertRun stores and the runner later receives
			backWf, err := model.ReadWorkflow(bytes.NewReader(payload))
			if err != nil {
				diffs = append(diffs, fmt.Sprintf("%s: runner cannot parse stored job: %v", id, err))
				continue
			}
			want, got := describe(origWf, origWf.GetJob(id)), describe(backWf, backWf.GetJob(id))
			keys := map[string]bool{}
			for k := range want {
				keys[k] = true
			}
			for k := range got {
				keys[k] = true
			}
			for k := range keys {
				compared++
				if want[k] != got[k] {
					diffs = append(diffs, fmt.Sprintf("\n        %s %s:\n          workflow file: %q\n          runner gets:   %q", id, k, want[k], got[k]))
				}
			}
		}
		sort.Strings(diffs)
		if len(diffs) == 0 {
			t.Logf("%-34s => identical (%d fields compared)", name, compared)
		} else {
			t.Logf("%-34s => %d of %d fields DIFFER:%s", name, len(diffs), compared, strings.Join(diffs, ""))
		}
	}
}

func TestProbeR2_MatrixTypes(t *testing.T) {
	content := []byte("on: push\njobs:\n  test:\n    runs-on: ubuntu-latest\n    strategy:\n      matrix:\n        v: [18, \"20\", 22.5, \"1e3\", \"yes\", true, \"true\", null, \"\", \"3.10\", \"0123\", \"~\", \"2024-01-01\"]\n    steps:\n      - run: echo \"${{ matrix.v }}\"\n")
	origWf, err := model.ReadWorkflow(bytes.NewReader(content))
	require.NoError(t, err)
	orig, err := origWf.GetJob("test").GetMatrixes()
	require.NoError(t, err)
	origSet := map[string]bool{}
	for _, m := range orig {
		origSet[typed(m)] = true
	}
	wfs, err := jobparser.Parse(content)
	require.NoError(t, err)
	changed := []string{}
	for _, sw := range wfs {
		id, job := sw.Job()
		require.NoError(t, sw.SetJob(id, job.EraseNeeds()))
		payload, _ := sw.Marshal()
		backWf, err := model.ReadWorkflow(bytes.NewReader(payload))
		require.NoError(t, err)
		back, err := backWf.GetJob(id).GetMatrixes()
		require.NoError(t, err)
		if len(back) != 1 {
			changed = append(changed, fmt.Sprintf("%q expands to %d legs after storing", job.Name, len(back)))
			continue
		}
		if !origSet[typed(back[0])] {
			changed = append(changed, fmt.Sprintf("job %q: runner gets %s", job.Name, typed(back[0])))
		}
	}
	t.Logf("%d matrix legs in the file, %d stored jobs; values whose type or value changed: %d %v", len(orig), len(wfs), len(changed), changed)
}

func TestProbeR3_ConcurrentRerun(t *testing.T) {
	_, repo, _ := pSetup(t)
	ctx := t.Context()
	doer := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 5})
	wf := "on: push\njobs:\n  build:\n    runs-on: probe-linux\n    steps:\n      - run: make\n  deploy:\n    needs: build\n    runs-on: probe-linux\n    steps:\n      - run: ./deploy.sh\n"
	outcomes := map[string]int{}
	bad := 0
	for range 15 {
		run := pInsert(t, "c2d72f548424103f01ee1dc02889c1e2bff816b0", "ci.yml", wf)
		_, err := db.Exec(ctx, "UPDATE `action_run_job` SET status = ? WHERE run_id = ?", actions_model.StatusFailure, run.ID)
		require.NoError(t, err)
		_, err = db.Exec(ctx, "UPDATE `action_run` SET status = ? WHERE id = ?", actions_model.StatusFailure, run.ID)
		require.NoError(t, err)
		_, err = db.Exec(ctx, "UPDATE `action_run_attempt` SET status = ? WHERE run_id = ?", actions_model.StatusFailure, run.ID)
		require.NoError(t, err)
		var wg sync.WaitGroup
		var mu sync.Mutex
		ok := 0
		for range 6 { // six people (or six clicks) hit re-run at the same moment
			wg.Add(1)
			go func() {
				defer wg.Done()
				r, err := actions_model.GetRunByRepoAndID(ctx, 4, run.ID)
				if err != nil {
					return
				}
				_, err = RerunWorkflowRunJobs(ctx, repo, r, doer, nil)
				mu.Lock()
				defer mu.Unlock()
				if err == nil {
					ok++
				} else {
					msg := err.Error()
					if len(msg) > 48 {
						msg = msg[:48]
					}
					outcomes[msg]++
				}
			}()
		}
		wg.Wait()
		attempts, _ := db.GetEngine(ctx).Where("run_id = ?", run.ID).Count(new(actions_model.ActionRunAttempt))
		jobs, _ := db.GetEngine(ctx).Where("run_id = ?", run.ID).Count(new(actions_model.ActionRunJob))
		r, _ := actions_model.GetRunByRepoAndID(ctx, 4, run.ID)
		latest, _ := db.GetEngine(ctx).Where("run_id = ? AND run_attempt_id = ?", run.ID, r.LatestAttemptID).Count(new(actions_model.ActionRunJob))
		if ok != 1 || attempts != 2 || jobs != 4 || latest != 2 {
			bad++
			t.Logf("  inconsistent round: succeeded=%d attempts=%d job rows=%d jobs in latest attempt=%d run=%s", ok, attempts, jobs, latest, r.Status)
		}
		outcomes[fmt.Sprintf("succeeded x%d", ok)]++
	}
	t.Logf("15 rounds of 6 simultaneous re-runs: inconsistent rounds=%d; outcomes=%v", bad, outcomes)
}

