func TestProbeR5_CancelVsClaimRace(t *testing.T) {
	runner, _, _ := pSetup(t)
	ctx := t.Context()
	wf := "on: push\njobs:\n  build:\n    runs-on: probe-linux\n    steps:\n      - run: make\n"
	counts := map[string]int{}
	for range 150 {
		run := pInsert(t, "c2d72f548424103f01ee1dc02889c1e2bff816b0", "ci.yml", wf)
		var wg sync.WaitGroup
		var cancelled int
		var cancelErr, claimErr error
		wg.Add(2)
		go func() { // web Cancel handler: read jobs, then cancel them in a transaction
			defer wg.Done()
			r, _ := actions_model.GetRunByRepoAndID(ctx, 4, run.ID)
			jobs, _ := actions_model.GetRunJobsByRunAndAttemptID(ctx, run.ID, r.LatestAttemptID)
			cancelErr = db.WithTx(ctx, func(ctx context.Context) error {
				c, err := actions_model.CancelJobs(ctx, jobs)
				cancelled = len(c)
				return err
			})
		}()
		go func() { // a runner polling at the same moment
			defer wg.Done()
			_, _, claimErr = actions_model.CreateTaskForRunner(ctx, runner)
		}()
		wg.Wait()
		r, _ := actions_model.GetRunByRepoAndID(ctx, 4, run.ID)
		jobs, _ := actions_model.GetRunJobsByRunAndAttemptID(ctx, run.ID, r.LatestAttemptID)
		key := fmt.Sprintf("job ends %s, cancel reported %d cancelled", jobs[0].Status, cancelled)
		if cancelErr != nil {
			key += ", cancel returned an error"
		}
		if claimErr != nil {
			key += ", runner poll returned an error"
		}
		counts[key]++
		if !jobs[0].Status.IsDone() { // tidy up so the next round starts clean
			_, _ = actions_model.CancelJobs(ctx, jobs)
		}
	}
	keys := make([]string, 0, len(counts))
	for k, v := range counts {
		keys = append(keys, fmt.Sprintf("\n        %3d x %s", v, k))
	}
	sort.Strings(keys)
	t.Logf("150 rounds of cancel racing a runner poll:%s", strings.Join(keys, ""))
}

func TestProbeR6_DeepNestingAndCycle(t *testing.T) {
	_, _, _ = pSetup(t)
	files := map[string]string{"top.yml": "on: push\njobs:\n  side:\n    runs-on: probe-linux\n    steps:\n      - run: echo\n  after:\n    needs: side\n    runs-on: probe-linux\n    steps:\n      - run: echo\n  go:\n    uses: ./.gitea/workflows/l1.yml\n"}
	for i := 1; i <= 11; i++ {
		body := fmt.Sprintf("on:\n  workflow_call:\njobs:\n  go:\n    uses: ./.gitea/workflows/l%d.yml\n", i+1)
		if i == 11 {
			body = "on:\n  workflow_call:\njobs:\n  leaf:\n    runs-on: probe-linux\n    steps:\n      - run: echo\n"
		}
		files[fmt.Sprintf("l%d.yml", i)] = body
	}
	files["cyc-a.yml"] = "on:\n  push:\n  workflow_call:\njobs:\n  go:\n    uses: ./.gitea/workflows/cyc-b.yml\n"
	files["cyc-b.yml"] = "on:\n  workflow_call:\njobs:\n  go:\n    uses: ./.gitea/workflows/cyc-a.yml\n"
	sha := pCommit(t, files)
	for _, entry := range []string{"top.yml", "cyc-a.yml"} {
		run := pInsert(t, sha, entry, files[entry])
		var lastErr error
		passes := 0
		for range 15 {
			passes++
			if lastErr = pEmit(t, run.ID); lastErr != nil {
				break
			}
		}
		r, _ := actions_model.GetRunByRepoAndID(t.Context(), 4, run.ID)
		jobs, _ := actions_model.GetRunJobsByRunAndAttemptID(t.Context(), run.ID, r.LatestAttemptID)
		callers := 0
		for _, j := range jobs {
			if j.IsReusableCaller {
				callers++
			}
		}
		t.Logf("%s: %d caller rows expanded, emitter stopped at pass %d with err=%v", entry, callers, passes, lastErr)
	}
}

