      FLAG: "yes"
      BOOL: "true"
      COLON: "a: b"
      HASH: "#not-a-comment"
      DASH: "- item"
      STAR: "*alias"
      AT: "@at"
      LEAD: " leading space"
      TRAIL: "trailing space "
      MULTI: "line1\nline2\n"
      QUOTES: "it's \"quoted\""
      UNICODE: "déjà vu ✅"
    outputs:
