        continue-on-error: true
        with:
          python-version: "3.10"
          node-version: "20"
          token: "0123"
          cache: true
          fetch-depth: 0
          flag: "yes"
          empty: ""
          lead: " x"
          multi: |
            a
            b
          script: "  const a = 1;\nreturn a;\n"
        env:
          A: "1.0"
          B: "null"
          C: "~"
          D: "true"
          E: "0o17"
          F: "1_000"
          G: "2024-01-01T00:00:00Z"
