		"services + container": "on: push\ndefaults:\n  run:\n    shell: bash\n    working-directory: ./app\njobs:\n  test:\n    runs-on: [self-hosted, linux]\n    defaults:\n      run:\n        shell: sh\n    strategy:\n      fail-fast: false\n      max-parallel: 2\n    container:\n      image: node:20\n      options: --user 1001 --cpus 2\n      env:\n        CI: true\n        N: 5\n      volumes:\n        - /cache:/cache\n      credentials:\n        username: bot\n        password: ${{ secrets.REG }}\n    services:\n      db:\n        image: postgres:16\n        env:\n          POSTGRES_PASSWORD: 12345\n          POSTGRES_DB: \"0010\"\n        ports:\n          - 5432:5432\n          - 6379\n        options: >-\n          --health-cmd pg_isready\n          --health-interval 10s\n    steps:\n      - run: npm test\n",
