				continue
			}
			want, got := describe(origWf, origWf.GetJob(id)), describe(backWf, backWf.GetJob(id))
			keys := map[string]bool{}
			for k := range want {
				keys[k] = true
			}
			for k := range got {
				keys[k] = true
			}
			for k := range keys {
				compared++
				if want[k] != got[k] {
					diffs = append(diffs, fmt.Sprintf("\n        %s %s:\n          workflow file: %q\n          runner gets:   %q", id, k, want[k], got[k]))
				}
			}
		}
		sort.Strings(diffs)
		if len(diffs) == 0 {
			t.Logf("%-34s => identical (%d fields compared)", name, compared)
		} else {
			t.Logf("%-34s => %d of %d fields DIFFER:%s", name, len(diffs), compared, strings.Join(diffs, ""))
		}
	}
