func TestProbeR2_MatrixTypes(t *testing.T) {
	content := []byte("on: push\njobs:\n  test:\n    runs-on: ubuntu-latest\n    strategy:\n      matrix:\n        v: [18, \"20\", 22.5, \"1e3\", \"yes\", true, \"true\", null, \"\", \"3.10\", \"0123\", \"~\", \"2024-01-01\"]\n    steps:\n      - run: echo \"${{ matrix.v }}\"\n")
	origWf, err := model.ReadWorkflow(bytes.NewReader(content))
	require.NoError(t, err)
	orig, err := origWf.GetJob("test").GetMatrixes()
	require.NoError(t, err)
	origSet := map[string]bool{}
	for _, m := range orig {
		origSet[typed(m)] = true
	}
	wfs, err := jobparser.Parse(content)
	require.NoError(t, err)
	changed := []string{}
	for _, sw := range wfs {
		id, job := sw.Job()
		require.NoError(t, sw.SetJob(id, job.EraseNeeds()))
		payload, _ := sw.Marshal()
		backWf, err := model.ReadWorkflow(bytes.NewReader(payload))
		require.NoError(t, err)
		back, err := backWf.GetJob(id).GetMatrixes()
		require.NoError(t, err)
		if len(back) != 1 {
			changed = append(changed, fmt.Sprintf("%q expands to %d legs after storing", job.Name, len(back)))
			continue
		}
		if !origSet[typed(back[0])] {
			changed = append(changed, fmt.Sprintf("job %q: runner gets %s", job.Name, typed(back[0])))
		}
	}
	t.Logf("%d matrix legs in the file, %d stored jobs; values whose type or value changed: %d %v", len(orig), len(wfs), len(changed), changed)
}

func TestProbeR3_ConcurrentRerun(t *testing.T) {
	_, repo, _ := pSetup(t)
	ctx := t.Context()
	doer := unittest.AssertExistsAndLoadBean(t, &user_model.User{ID: 5})
	wf := "on: push\njobs:\n  build:\n    runs-on: probe-linux\n    steps:\n      - run: make\n  deploy:\n    needs: build\n    runs-on: probe-linux\n    steps:\n      - run: ./deploy.sh\n"
	outcomes := map[string]int{}
	bad := 0
	for range 15 {
		run := pInsert(t, "c2d72f548424103f01ee1dc02889c1e2bff816b0", "ci.yml", wf)
		_, err := db.Exec(ctx, "UPDATE `action_run_job` SET status = ? WHERE run_id = ?", actions_model.StatusFailure, run.ID)
		require.NoError(t, err)
		_, err = db.Exec(ctx, "UPDATE `action_run` SET status = ? WHERE id = ?", actions_model.StatusFailure, run.ID)
		require.NoError(t, err)
		_, err = db.Exec(ctx, "UPDATE `action_run_attempt` SET status = ? WHERE run_id = ?", actions_model.StatusFailure, run.ID)
		require.NoError(t, err)
		var wg sync.WaitGroup
		var mu sync.Mutex
		ok := 0
		for range 6 { // six people (or six clicks) hit re-run at the same moment
			wg.Add(1)
			go func() {
				defer wg.Done()
				r, err := actions_model.GetRunByRepoAndID(ctx, 4, run.ID)
				if err != nil {
					return
				}
				_, err = RerunWorkflowRunJobs(ctx, repo, r, doer, nil)
				mu.Lock()
				defer mu.Unlock()
				if err == nil {
					ok++
				} else {
					msg := err.Error()
					if len(msg) > 48 {
						msg = msg[:48]
					}
					outcomes[msg]++
				}
			}()
		}
		wg.Wait()
		attempts, _ := db.GetEngine(ctx).Where("run_id = ?", run.ID).Count(new(actions_model.ActionRunAttempt))
		jobs, _ := db.GetEngine(ctx).Where("run_id = ?", run.ID).Count(new(actions_model.ActionRunJob))
		r, _ := actions_model.GetRunByRepoAndID(ctx, 4, run.ID)
		latest, _ := db.GetEngine(ctx).Where("run_id = ? AND run_attempt_id = ?", run.ID, r.LatestAttemptID).Count(new(actions_model.ActionRunJob))
		if ok != 1 || attempts != 2 || jobs != 4 || latest != 2 {
			bad++
			t.Logf("  inconsistent round: succeeded=%d attempts=%d job rows=%d jobs in latest attempt=%d run=%s", ok, attempts, jobs, latest, r.Status)
		}
		outcomes[fmt.Sprintf("succeeded x%d", ok)]++
	}
	t.Logf("15 rounds of 6 simultaneous re-runs: inconsistent rounds=%d; outcomes=%v", bad, outcomes)
}

