package report

import (
	"context"
	"errors"
	"testing"
	"time"

	"gitea.com/gitea/runner/internal/pkg/client/mocks"
	"gitea.com/gitea/runner/internal/pkg/config"

	runnerv1 "code.gitea.io/actions-proto-go/runner/v1"
	connect_go "connectrpc.com/connect"
	"github.com/stretchr/testify/mock"
	"github.com/stretchr/testify/require"
	"google.golang.org/protobuf/types/known/structpb"
)

// What does the runner do when the server answers a heartbeat with each result?
func TestProbeServerAnswer(t *testing.T) {
	for _, answer := range []runnerv1.Result{runnerv1.Result_RESULT_FAILURE, runnerv1.Result_RESULT_SUCCESS, runnerv1.Result_RESULT_SKIPPED, runnerv1.Result_RESULT_CANCELLED} {
		client := mocks.NewClient(t)
		client.On("UpdateTask", mock.Anything, mock.Anything).Return(
			func(_ context.Context, req *connect_go.Request[runnerv1.UpdateTaskRequest]) (*connect_go.Response[runnerv1.UpdateTaskResponse], error) {
				return connect_go.NewResponse(&runnerv1.UpdateTaskResponse{State: &runnerv1.TaskState{Id: req.Msg.State.Id, Result: answer}}), nil
			},
		)
		ctx, cancel := context.WithCancel(context.Background())
		taskCtx, err := structpb.NewStruct(map[string]any{})
		require.NoError(t, err)
		cfg, _ := config.LoadDefault("")
		reporter := NewReporter(ctx, cancel, client, &runnerv1.Task{Context: taskCtx}, cfg)
		reporter.ResetSteps(1)
		reporter.stateMu.Lock()
		reporter.stateChanged = true
		reporter.stateMu.Unlock()
		require.NoError(t, reporter.ReportState(false))
		t.Logf("server answers heartbeat with %-16s -> job context cancelled (runner aborts the job): %v", answer, ctx.Err() != nil)
		cancel()
	}
}

// How long does the runner keep trying to deliver the final result when the server is unreachable?
func TestProbeFinalFlushBound(t *testing.T) {
	client := mocks.NewClient(t)
	calls := 0
	client.On("UpdateLog", mock.Anything, mock.Anything).Return(
		func(_ context.Context, _ *connect_go.Request[runnerv1.UpdateLogRequest]) (*connect_go.Response[runnerv1.UpdateLogResponse], error) {
			return nil, errors.New("connection refused")
		},
	)
	client.On("UpdateTask", mock.Anything, mock.Anything).Return(
		func(_ context.Context, _ *connect_go.Request[runnerv1.UpdateTaskRequest]) (*connect_go.Response[runnerv1.UpdateTaskResponse], error) {
			calls++
			return nil, errors.New("connection refused")
		},
	)
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	taskCtx, err := structpb.NewStruct(map[string]any{})
	require.NoError(t, err)
	cfg, _ := config.LoadDefault("")
	t.Logf("default report_close_timeout = %s", cfg.Runner.ReportCloseTimeout)
	reporter := NewReporter(ctx, cancel, client, &runnerv1.Task{Context: taskCtx}, cfg)
	reporter.ResetSteps(1)
	reporter.RunDaemon()
	start := time.Now()
	err = reporter.Close("")
	t.Logf("job finished with the server unreachable: Close() gave up after %s (final-state attempts: %d), err != nil: %v", time.Since(start).Round(100*time.Millisecond), calls, err != nil)
}
EOF
